```typescript
type MomentType =
  | "proposal"
  | "discovery"
  | "pivot"
  | "confirmation"
  | "rejection"
  | "commitment"
  | "struggle"
  | "breakthrough"
  | "execution";

interface SessionMoment {
  id: string;
  chunkId: string;
  type: MomentType;
  statement: string;
  significance: string;
  agency: "developer" | "ai" | "collaborative" | "ambiguous";
  confidence: "high" | "medium" | "low";
  topicFingerprint: string;
  relatedMomentIds: string[];
  arcId?: string;
  arcRole?: "origin" | "escalation" | "turning_point" | "resolution";
  evidence: Evidence[];
}

interface Evidence {
  quote: string;
  sourceEventId: string;
  sourceType: "human_message" | "ai_message" | "tool_output" | "tool_input";
  quoteType: "verbatim" | "summarized";
}
```

