// ── Raw Dev Event ─────────────────────────────────────────────────────
// Unified event format produced by source adapters (Claude Code, etc.)

export interface RawDevEvent {
  /** Unique ID — the uuid from the original log entry */
  id: string;

  /** Which tool/system produced this event */
  source: "claude-code";

  /** ISO 8601 timestamp */
  timestamp: string;

  /** Semantic event type */
  type:
    | "conversation_turn" // user message
    | "tool_call"         // AI tool use (Edit, Write, Bash, etc.)
    | "tool_result"       // progress events with tool output
    | "ai_response";      // AI text response

  /** Original log entry, preserved verbatim */
  raw: Record<string, unknown>;
}

// ── Source Adapter Interface ──────────────────────────────────────────

export interface SourceAdapter {
  /** Parse a log file and return raw events */
  parse(filePath: string): Promise<RawDevEvent[]>;
}

import { readFile } from "node:fs/promises";
import type { RawDevEvent, SourceAdapter } from "./types.js";

// CC log entry types we skip entirely
const SKIP_TYPES = new Set([
  "queue-operation",
  "file-history-snapshot",
  "system",
]);

// ── Helpers ───────────────────────────────────────────────────────────

interface ContentBlock {
  type: string;
  text?: string;
  thinking?: string;
  name?: string;
  input?: Record<string, unknown>;
}

interface CCLogEntry {
  type: string;
  timestamp: string;
  uuid: string;
  sessionId?: string;
  parentUuid?: string;
  message?: {
    role?: string;
    content?: string | ContentBlock[];
    model?: string;
  };
  data?: Record<string, unknown>;
}

function isProgressMeaningful(entry: CCLogEntry): boolean {
  // Skip hook-only progress events — they're CC infrastructure
  if (entry.data?.type === "hook_progress") return false;
  // Keep progress events that carry actual data
  return entry.data !== undefined && Object.keys(entry.data).length > 0;
}

// ── Adapter ───────────────────────────────────────────────────────────

function parseEntry(entry: CCLogEntry): RawDevEvent[] {
  if (SKIP_TYPES.has(entry.type)) return [];

  const base = {
    source: "claude-code" as const,
    timestamp: entry.timestamp,
    raw: entry as unknown as Record<string, unknown>,
  };

  // User message → conversation_turn
  if (entry.type === "user") {
    return [{ ...base, id: entry.uuid, type: "conversation_turn" }];
  }

  // Assistant message → fan out per content block
  if (entry.type === "assistant") {
    const content = entry.message?.content;
    if (!Array.isArray(content)) return [];

    const events: RawDevEvent[] = [];
    let blockIndex = 0;

    for (const block of content) {
      if (block.type === "text" && block.text) {
        events.push({
          ...base,
          id: `${entry.uuid}-text-${blockIndex}`,
          type: "ai_response",
        });
      } else if (block.type === "tool_use" && block.name) {
        events.push({
          ...base,
          id: `${entry.uuid}-tool-${blockIndex}`,
          type: "tool_call",
        });
      }
      // skip "thinking" blocks — internal reasoning
      blockIndex++;
    }

    return events;
  }

  // Progress → tool_result (only meaningful ones)
  if (entry.type === "progress") {
    if (!isProgressMeaningful(entry)) return [];
    return [{ ...base, id: entry.uuid, type: "tool_result" }];
  }

  return [];
}

export class ClaudeCodeAdapter implements SourceAdapter {
  async parse(filePath: string): Promise<RawDevEvent[]> {
    const text = await readFile(filePath, "utf-8");
    const lines = text.split("\n").filter((line) => line.trim().length > 0);

    const events: RawDevEvent[] = [];

    for (const line of lines) {
      let entry: CCLogEntry;
      try {
        entry = JSON.parse(line) as CCLogEntry;
      } catch {
        // skip malformed lines
        continue;
      }
      events.push(...parseEntry(entry));
    }

    return events;
  }
}

import { readdir, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

const CLAUDE_PROJECTS_DIR = join(homedir(), ".claude", "projects");

interface LogFile {
  path: string;
  mtime: Date;
}

/** Recursively collect all .jsonl files under a directory */
async function collectJsonl(dir: string): Promise<LogFile[]> {
  const results: LogFile[] = [];

  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await collectJsonl(fullPath)));
    } else if (entry.isFile() && entry.name.endsWith(".jsonl")) {
      const info = await stat(fullPath);
      results.push({ path: fullPath, mtime: info.mtime });
    }
  }

  return results;
}

/**
 * Find the most recent JSONL log in ~/.claude/projects/.
 * If projectDir is provided, scopes to that project's subdirectory.
 */
export async function discoverLatestLog(
  projectDir?: string,
): Promise<string | null> {
  const logs = await discoverLogs(1, projectDir);
  return logs[0] ?? null;
}

/**
 * Return the N most recent JSONL log files, newest first.
 * If projectDir is provided, scopes to that project's subdirectory.
 */
export async function discoverLogs(
  count: number,
  projectDir?: string,
): Promise<string[]> {
  const searchDir = projectDir
    ? join(CLAUDE_PROJECTS_DIR, projectDir)
    : CLAUDE_PROJECTS_DIR;

  const files = await collectJsonl(searchDir);

  files.sort((a, b) => b.mtime.getTime() - a.mtime.getTime());

  return files.slice(0, count).map((f) => f.path);
}

