export declare function parseSession(filePath: string, options?: ParseOptions): Promise<Session>;
/** Build map of agentId -> subagentType from Task calls in transcript */
export declare function buildAgentTypeMap(transcript: Transcript): Map<string, string>;
/** Resolve subagentType for an agent transcript by finding its Task call in main session */
