 35→function isProgressMeaningful(entry: CCLogEntry): boolean {
 36→  // Skip hook-only progress events — they're CC infrastructure
 37→  if (entry.data?.type === "hook_progress") return false;
 38→  // Keep progress events that carry actual data
 39→  return entry.data !== undefined && Object.keys(entry.data).length > 0;
 40→}
