 42→// ── Adapter ───────────────────────────────────────────────────────────
 43→
 44→function parseEntry(entry: CCLogEntry): RawDevEvent[] {
 45→  if (SKIP_TYPES.has(entry.type)) return [];
 46→
 47→  const base = {
 48→    source: "claude-code" as const,
 49→    timestamp: entry.timestamp,
 50→    raw: entry as unknown as Record<string, unknown>,
 51→  };
 52→
 53→  // User message → conversation_turn
 54→  if (entry.type === "user") {
 55→    return [{ ...base, id: entry.uuid, type: "conversation_turn" }];
 56→  }
 57→
 58→  // Assistant message → fan out per content block
 59→  if (entry.type === "assistant") {
 60→    const content = entry.message?.content;
 61→    if (!Array.isArray(content)) return [];
 62→
 63→    const events: RawDevEvent[] = [];
 64→    let blockIndex = 0;
 65→
 66→    for (const block of content) {
 67→      if (block.type === "text" && block.text) {
 68→        events.push({
 69→          ...base,
 70→          id: `${entry.uuid}-text-${blockIndex}`,
 71→          type: "ai_response",
 72→        });
 73→      } else if (block.type === "tool_use" && block.name) {
 74→        events.push({
 75→          ...base,
 76→          id: `${entry.uuid}-tool-${blockIndex}`,
 77→          type: "tool_call",
 78→        });
 79→      }
 80→      // skip "thinking" blocks — internal reasoning
 81→      blockIndex++;
 82→    }
 83→
 84→    return events;
 85→  }
 86→
 87→  // Progress → tool_result (only meaningful ones)
 88→  if (entry.type === "progress") {
 89→    if (!isProgressMeaningful(entry)) return [];
 90→    return [{ ...base, id: entry.uuid, type: "tool_result" }];
 91→  }
 92→
 93→  return [];
 94→}
