 96→export class ClaudeCodeAdapter implements SourceAdapter {
 97→  async parse(filePath: string): Promise<RawDevEvent[]> {
 98→    const text = await readFile(filePath, "utf-8");
 99→    const lines = text.split("\n").filter((line) => line.trim().length > 0);
100→
101→    const events: RawDevEvent[] = [];
102→
103→    for (const line of lines) {
104→      let entry: CCLogEntry;
105→      try {
106→        entry = JSON.parse(line) as CCLogEntry;
107→      } catch {
108→        // skip malformed lines
109→        continue;
110→      }
111→      events.push(...parseEntry(entry));
112→    }
113→
114→    return events;
115→  }
116→}
