 1→import { readdir, stat } from "node:fs/promises";
 2→import { homedir } from "node:os";
 3→import { join } from "node:path";
 4→
 5→const CLAUDE_PROJECTS_DIR = join(homedir(), ".claude", "projects");
 6→
 7→interface LogFile {
 8→  path: string;
 9→  mtime: Date;
10→}
11→
12→/** Recursively collect all .jsonl files under a directory */
13→async function collectJsonl(dir: string): Promise<LogFile[]> {
14→  const results: LogFile[] = [];
15→
16→  let entries;
17→  try {
18→    entries = await readdir(dir, { withFileTypes: true });
19→  } catch {
20→    return results;
21→  }
22→
23→  for (const entry of entries) {
24→    const fullPath = join(dir, entry.name);
25→    if (entry.isDirectory()) {
26→      results.push(...(await collectJsonl(fullPath)));
27→    } else if (entry.isFile() && entry.name.endsWith(".jsonl")) {
28→      const info = await stat(fullPath);
29→      results.push({ path: fullPath, mtime: info.mtime });
30→    }
31→  }
32→
33→  return results;
34→}
35→
36→/**
37→ * Find the most recent JSONL log in ~/.claude/projects/.
38→ * If projectDir is provided, scopes to that project's subdirectory.
39→ */
40→export async function discoverLatestLog(
41→  projectDir?: string,
42→): Promise<string | null> {
43→  const logs = await discoverLogs(1, projectDir);
44→  return logs[0] ?? null;
45→}
46→
47→/**
48→ * Return the N most recent JSONL log files, newest first.
49→ * If projectDir is provided, scopes to that project's subdirectory.
50→ */
51→export async function discoverLogs(
52→  count: number,
53→  projectDir?: string,
54→): Promise<string[]> {
55→  const searchDir = projectDir
56→    ? join(CLAUDE_PROJECTS_DIR, projectDir)
57→    : CLAUDE_PROJECTS_DIR;
58→
59→  const files = await collectJsonl(searchDir);
60→
61→  files.sort((a, b) => b.mtime.getTime() - a.mtime.getTime());
62→
63→  return files.slice(0, count).map((f) => f.path);
64→}
