import type { RawDevEvent, NormalizedDevEvent } from "../adapters/types.js";

// Tools that modify state — their tool_call events are categorized as "action"
const STATE_MODIFYING_TOOLS = new Set([
  "Edit",
  "Write",
  "Bash",
  "NotebookEdit",
]);

// Tools that read state — their tool_call events are categorized as "reflection"
// (Read, Glob, Grep, Agent, Explore, WebSearch, WebFetch, etc.)

/**
 * Normalize a sequence of RawDevEvents into NormalizedDevEvents.
 *
 * Assigns causal order, classifies each event into a semantic category,
 * extracts content summaries, and filters out events with no meaningful content.
 */
export function normalize(
  events: RawDevEvent[],
  sessionId: string,
): NormalizedDevEvent[] {
  const result: NormalizedDevEvent[] = [];
  let causalOrder = 0;

  for (let i = 0; i < events.length; i++) {
    const event = events[i];
    const extracted = extractContent(event);

    // Filter out events with no meaningful content
    if (!extracted) continue;

    const { category, actor } = classify(event, events, i);

    result.push({
      id: `${sessionId}-${causalOrder}`,
      sessionId,
      timestamp: event.timestamp,
      causalOrder,
      category,
      actor,
      content: extracted,
      rawEventId: event.id,
    });

    causalOrder++;
  }

  return result;
}

// ── Classification ───────────────────────────────────────────────────

type Classification = {
  category: NormalizedDevEvent["category"];
  actor: NormalizedDevEvent["actor"];
};

function classify(
  event: RawDevEvent,
  events: RawDevEvent[],
  index: number,
): Classification {
  switch (event.type) {
    case "conversation_turn":
      return { category: "intent", actor: "user" };

    case "tool_result":
      return { category: "result", actor: "user" };

    case "tool_call":
      return {
        category: isStateModifying(event) ? "action" : "reflection",
        actor: "ai",
      };

    case "ai_response":
      return {
        category: isAfterToolResult(events, index)
          ? "reflection"
          : "proposal",
        actor: "ai",
      };
  }
}

/**
 * Check whether a tool_call event uses a state-modifying tool.
 */
function isStateModifying(event: RawDevEvent): boolean {
  const toolName = getToolName(event);
  return toolName !== undefined && STATE_MODIFYING_TOOLS.has(toolName);
}

/**
 * An ai_response is a "reflection" if the most recent non-ai_response event
 * before it (scanning backwards) is a tool_result. Otherwise it's a "proposal".
 */
function isAfterToolResult(events: RawDevEvent[], index: number): boolean {
  for (let j = index - 1; j >= 0; j--) {
    const prev = events[j];
    // Skip over other ai_response events in the same message
    if (prev.type === "ai_response") continue;
    return prev.type === "tool_result";
  }
  return false;
}

// ── Content Extraction ───────────────────────────────────────────────

function extractContent(
  event: RawDevEvent,
): NormalizedDevEvent["content"] | null {
  const raw = event.raw;

  switch (event.type) {
    case "conversation_turn": {
      const text = getUserText(raw);
      if (!text) return null;
      return {
        summary: truncate(text, 200),
        detail: text,
      };
    }

    case "ai_response": {
      const text = getAiText(event);
      if (!text) return null;
      return {
        summary: truncate(text, 200),
        detail: text,
      };
    }

    case "tool_call": {
      const toolName = getToolName(event);
      const input = getToolInput(event);
      if (!toolName) return null;

      const filePath = extractFilePath(input);
      const summary = filePath
        ? `Tool: ${toolName} on ${filePath}`
        : `Tool: ${toolName}`;
      const detail = input ? JSON.stringify(input) : summary;
      const filesAffected = filePath ? [filePath] : undefined;

      return { summary: truncate(summary, 200), detail, filesAffected };
    }

    case "tool_result": {
      const text = getToolResultText(raw);
      if (!text) return null;
      return {
        summary: truncate(text, 200),
        detail: text,
      };
    }
  }
}

// ── Helpers ──────────────────────────────────────────────────────────

function truncate(s: string, maxLen: number): string {
  return s.length <= maxLen ? s : s.slice(0, maxLen);
}

/**
 * Extract user text from the raw log entry.
 * Content can be a string or an array of content blocks.
 */
function getUserText(raw: Record<string, unknown>): string | null {
  const msg = raw.message as { content?: unknown } | undefined;
  if (!msg?.content) return null;
  if (typeof msg.content === "string") return msg.content;
  return null;
}

/**
 * Extract AI text from an ai_response event.
 * The event ID encodes which content block it came from (e.g., "a-001-text-1").
 */
function getAiText(event: RawDevEvent): string | null {
  const raw = event.raw;
  const msg = raw.message as { content?: unknown[] } | undefined;
  if (!msg?.content || !Array.isArray(msg.content)) return null;

  // Find the text block index from the event ID (format: "...-text-N")
  const match = event.id.match(/-text-(\d+)$/);
  if (match) {
    const idx = parseInt(match[1], 10);
    const block = msg.content[idx] as { type?: string; text?: string } | undefined;
    if (block?.type === "text" && block.text) return block.text;
  }

  // Fallback: find first text block
  for (const block of msg.content) {
    const b = block as { type?: string; text?: string };
    if (b.type === "text" && b.text) return b.text;
  }
  return null;
}

/**
 * Extract tool name from a tool_call event.
 */
function getToolName(event: RawDevEvent): string | undefined {
  const raw = event.raw;
  const msg = raw.message as { content?: unknown[] } | undefined;
  if (!msg?.content || !Array.isArray(msg.content)) return undefined;

  // Find tool_use block index from event ID (format: "...-tool-N")
  const match = event.id.match(/-tool-(\d+)$/);
  if (match) {
    const idx = parseInt(match[1], 10);
    const block = msg.content[idx] as { type?: string; name?: string } | undefined;
    if (block?.type === "tool_use" && block.name) return block.name;
  }

  // Fallback: first tool_use block
  for (const block of msg.content) {
    const b = block as { type?: string; name?: string };
    if (b.type === "tool_use" && b.name) return b.name;
  }
  return undefined;
}

/**
 * Extract tool input from a tool_call event.
 */
function getToolInput(
  event: RawDevEvent,
): Record<string, unknown> | undefined {
  const raw = event.raw;
  const msg = raw.message as { content?: unknown[] } | undefined;
  if (!msg?.content || !Array.isArray(msg.content)) return undefined;

  const match = event.id.match(/-tool-(\d+)$/);
  if (match) {
    const idx = parseInt(match[1], 10);
    const block = msg.content[idx] as {
      type?: string;
      input?: Record<string, unknown>;
    } | undefined;
    if (block?.type === "tool_use" && block.input) return block.input;
  }

  for (const block of msg.content) {
    const b = block as { type?: string; input?: Record<string, unknown> };
    if (b.type === "tool_use" && b.input) return b.input;
  }
  return undefined;
}

/**
 * Extract file path from tool input parameters.
 */
function extractFilePath(
  input: Record<string, unknown> | undefined,
): string | undefined {
  if (!input) return undefined;
  const candidates = ["file_path", "path", "filePath"];
  for (const key of candidates) {
    if (typeof input[key] === "string") return input[key] as string;
  }
  return undefined;
}

/**
 * Extract text from a tool_result event.
 */
function getToolResultText(raw: Record<string, unknown>): string | null {
  const msg = raw.message as { content?: unknown } | undefined;
  if (!msg?.content) return null;

  if (typeof msg.content === "string") return msg.content;

  if (Array.isArray(msg.content)) {
    for (const block of msg.content) {
      const b = block as { type?: string; content?: unknown };
      if (b.type === "tool_result") {
        // content can be a string or array of text blocks
        if (typeof b.content === "string") return b.content;
        if (Array.isArray(b.content)) {
          const texts: string[] = [];
          for (const inner of b.content) {
            const t = inner as { type?: string; text?: string };
            if (t.type === "text" && t.text) texts.push(t.text);
          }
          if (texts.length > 0) return texts.join("\n");
        }
      }
    }
  }
  return null;
}

import { describe, it, expect } from "vitest";
import { normalize } from "../../src/pipeline/normalize.js";
import type { RawDevEvent } from "../../src/adapters/types.js";

/**
 * Build a minimal RawDevEvent sequence that exercises all category rules:
 *
 * 1. User message           → intent
 * 2. AI text (before tool)  → proposal
 * 3. AI tool_call (Edit)    → action
 * 4. Tool result            → result
 * 5. AI text (after result) → reflection
 * 6. AI tool_call (Read)    → reflection
 */
function buildTestSequence(): RawDevEvent[] {
  const base = { source: "claude-code" as const };

  return [
    // 1. User message → intent
    {
      ...base,
      id: "u-001",
      timestamp: "2026-05-20T10:00:01.000Z",
      type: "conversation_turn",
      raw: {
        message: { content: "Add a hello world function to utils.ts" },
      },
    },
    // 2. AI text before tool calls → proposal
    {
      ...base,
      id: "a-001-text-0",
      timestamp: "2026-05-20T10:00:02.000Z",
      type: "ai_response",
      raw: {
        message: {
          content: [
            { type: "text", text: "I'll add a hello world function." },
            {
              type: "tool_use",
              name: "Edit",
              input: { file_path: "src/utils.ts" },
            },
          ],
        },
      },
    },
    // 3. AI tool_call (Edit — state-modifying) → action
    {
      ...base,
      id: "a-001-tool-1",
      timestamp: "2026-05-20T10:00:02.000Z",
      type: "tool_call",
      raw: {
        message: {
          content: [
            { type: "text", text: "I'll add a hello world function." },
            {
              type: "tool_use",
              name: "Edit",
              input: {
                file_path: "src/utils.ts",
                old_string: "",
                new_string: "export function hello() { return 'hello world'; }",
              },
            },
          ],
        },
      },
    },
    // 4. Tool result → result
    {
      ...base,
      id: "u-002-result-0",
      timestamp: "2026-05-20T10:00:03.000Z",
      type: "tool_result",
      raw: {
        message: {
          content: [
            {
              type: "tool_result",
              tool_use_id: "tu-001",
              content: [{ type: "text", text: "File edited successfully" }],
            },
          ],
        },
      },
    },
    // 5. AI text after tool result → reflection
    {
      ...base,
      id: "a-002-text-0",
      timestamp: "2026-05-20T10:00:04.000Z",
      type: "ai_response",
      raw: {
        message: {
          content: [
            {
              type: "text",
              text: "Done! I've added the hello world function to utils.ts.",
            },
          ],
        },
      },
    },
    // 6. AI tool_call (Read — read-only) → reflection
    {
      ...base,
      id: "a-003-tool-0",
      timestamp: "2026-05-20T10:00:05.000Z",
      type: "tool_call",
      raw: {
        message: {
          content: [
            {
              type: "tool_use",
              name: "Read",
              input: { file_path: "src/utils.ts" },
            },
          ],
        },
      },
    },
  ];
}

describe("normalize", () => {
  const sessionId = "test-session-001";
  const events = buildTestSequence();
  const normalized = normalize(events, sessionId);

  it("produces one NormalizedDevEvent per input event", () => {
    expect(normalized).toHaveLength(6);
  });

  it("assigns sequential causalOrder starting at 0", () => {
    const orders = normalized.map((e) => e.causalOrder);
    expect(orders).toEqual([0, 1, 2, 3, 4, 5]);
  });

  it("sets sessionId on all events", () => {
    for (const e of normalized) {
      expect(e.sessionId).toBe(sessionId);
    }
  });

  it("links rawEventId back to the original event", () => {
    expect(normalized[0].rawEventId).toBe("u-001");
    expect(normalized[1].rawEventId).toBe("a-001-text-0");
    expect(normalized[2].rawEventId).toBe("a-001-tool-1");
  });

  // ── Category mapping ────────────────────────────────────────────────

  it("classifies user message as intent", () => {
    expect(normalized[0].category).toBe("intent");
    expect(normalized[0].actor).toBe("user");
  });

  it("classifies AI text before tool calls as proposal", () => {
    expect(normalized[1].category).toBe("proposal");
    expect(normalized[1].actor).toBe("ai");
  });

  it("classifies Edit tool_call as action", () => {
    expect(normalized[2].category).toBe("action");
    expect(normalized[2].actor).toBe("ai");
  });

  it("classifies tool_result as result", () => {
    expect(normalized[3].category).toBe("result");
    expect(normalized[3].actor).toBe("user");
  });

  it("classifies AI text after tool_result as reflection", () => {
    expect(normalized[4].category).toBe("reflection");
    expect(normalized[4].actor).toBe("ai");
  });

  it("classifies Read tool_call as reflection (read-only tool)", () => {
    expect(normalized[5].category).toBe("reflection");
    expect(normalized[5].actor).toBe("ai");
  });

  // ── Content extraction ──────────────────────────────────────────────

  it("generates summary for user messages (truncated to 200 chars)", () => {
    expect(normalized[0].content.summary).toBe(
      "Add a hello world function to utils.ts",
    );
    expect(normalized[0].content.detail).toBe(
      "Add a hello world function to utils.ts",
    );
  });

  it("generates summary for AI text responses", () => {
    expect(normalized[1].content.summary).toBe(
      "I'll add a hello world function.",
    );
  });

  it("generates tool summary with file path", () => {
    expect(normalized[2].content.summary).toBe("Tool: Edit on src/utils.ts");
    expect(normalized[2].content.filesAffected).toEqual(["src/utils.ts"]);
  });

  it("generates tool summary without file path for Read", () => {
    expect(normalized[5].content.summary).toBe("Tool: Read on src/utils.ts");
    expect(normalized[5].content.filesAffected).toEqual(["src/utils.ts"]);
  });

  it("extracts tool result text", () => {
    expect(normalized[3].content.summary).toBe("File edited successfully");
  });

  // ── Edge cases ──────────────────────────────────────────────────────

  it("filters out events with no meaningful content", () => {
    const emptyEvents: RawDevEvent[] = [
      {
        id: "empty-1",
        source: "claude-code",
        timestamp: "2026-05-20T10:00:00.000Z",
        type: "conversation_turn",
        raw: { message: { content: [] } }, // array, not string → null
      },
    ];
    const result = normalize(emptyEvents, "s-empty");
    expect(result).toHaveLength(0);
  });

  it("truncates long summaries to 200 characters", () => {
    const longText = "x".repeat(500);
    const longEvents: RawDevEvent[] = [
      {
        id: "long-1",
        source: "claude-code",
        timestamp: "2026-05-20T10:00:00.000Z",
        type: "conversation_turn",
        raw: { message: { content: longText } },
      },
    ];
    const result = normalize(longEvents, "s-long");
    expect(result[0].content.summary).toHaveLength(200);
    expect(result[0].content.detail).toHaveLength(500);
  });

  // ── State-modifying tool classification ─────────────────────────────

  it("classifies Write, Bash, NotebookEdit as action", () => {
    const tools = ["Write", "Bash", "NotebookEdit"];
    for (const toolName of tools) {
      const toolEvents: RawDevEvent[] = [
        {
          id: `t-${toolName}-tool-0`,
          source: "claude-code",
          timestamp: "2026-05-20T10:00:00.000Z",
          type: "tool_call",
          raw: {
            message: {
              content: [{ type: "tool_use", name: toolName, input: {} }],
            },
          },
        },
      ];
      const result = normalize(toolEvents, `s-${toolName}`);
      expect(result[0].category).toBe("action");
    }
  });

  it("classifies Glob, Grep, Agent as reflection", () => {
    const tools = ["Glob", "Grep", "Agent"];
    for (const toolName of tools) {
      const toolEvents: RawDevEvent[] = [
        {
          id: `t-${toolName}-tool-0`,
          source: "claude-code",
          timestamp: "2026-05-20T10:00:00.000Z",
          type: "tool_call",
          raw: {
            message: {
              content: [{ type: "tool_use", name: toolName, input: {} }],
            },
          },
        },
      ];
      const result = normalize(toolEvents, `s-${toolName}`);
      expect(result[0].category).toBe("reflection");
    }
  });
});

