import type { NormalizedDevEvent, SessionChunk } from "../adapters/types.js";

// ── Constants ────────────────────────────────────────────────────────

const PAUSE_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes
const FILE_SHIFT_THRESHOLD = 0.7; // 70% new files
const SIZE_CAP = 80;
const OVERLAP = 3;
const SHORT_SESSION_THRESHOLD = 10;

const TOPIC_SHIFT_PATTERNS = [
  /\bnow let'?s\b/i,
  /\bmoving on\b/i,
  /\bnext\b/i,
  /\bswitch to\b/i,
  /\bok let'?s work on\b/i,
];

// ── Main Entry Point ─────────────────────────────────────────────────

/**
 * Split a session's normalized events into bounded reasoning windows (chunks).
 * Deterministic — no LLM calls.
 */
export function chunkSession(
  events: NormalizedDevEvent[],
  sessionId: string,
): SessionChunk[] {
  if (events.length === 0) return [];

  // Short sessions: one chunk, no splitting
  if (events.length < SHORT_SESSION_THRESHOLD) {
    return [buildChunk(events, sessionId, 0, [])];
  }

  // Find all split points
  const splitIndices = findSplitPoints(events);

  // Build chunks from split points
  const rawChunks = splitAtIndices(events, splitIndices);

  // Apply size cap to oversized chunks
  const cappedChunks = rawChunks.flatMap((chunk) => applySizeCap(chunk));

  // Build SessionChunk objects with overlap
  return buildChunksWithOverlap(cappedChunks, sessionId);
}

// ── Split Point Detection ────────────────────────────────────────────

/**
 * Find indices where the event list should be split.
 * A split index N means: chunk boundary between events[N-1] and events[N].
 */
function findSplitPoints(events: NormalizedDevEvent[]): number[] {
  const splits = new Set<number>();

  for (let i = 1; i < events.length; i++) {
    // Priority 1: Large pauses (>5 min gap)
    const gap =
      new Date(events[i].timestamp).getTime() -
      new Date(events[i - 1].timestamp).getTime();
    if (gap > PAUSE_THRESHOLD_MS) {
      splits.add(i);
      continue;
    }

    // Priority 2: File cluster shift
    if (hasFileClusterShift(events, i)) {
      splits.add(i);
      continue;
    }

    // Priority 3: Explicit topic shift in user messages
    if (hasTopicShift(events[i])) {
      splits.add(i);
    }
  }

  return Array.from(splits).sort((a, b) => a - b);
}

/**
 * Check if >70% of files at index i are new compared to
 * the preceding window of events (look back up to 10 events).
 */
function hasFileClusterShift(
  events: NormalizedDevEvent[],
  index: number,
): boolean {
  const currentFiles = getFilesAffected(events[index]);
  if (currentFiles.length === 0) return false;

  // Collect files from the preceding window (up to 10 events back)
  const lookback = Math.max(0, index - 10);
  const previousFiles = new Set<string>();
  for (let j = lookback; j < index; j++) {
    for (const f of getFilesAffected(events[j])) {
      previousFiles.add(f);
    }
  }

  if (previousFiles.size === 0) return false;

  const newFiles = currentFiles.filter((f) => !previousFiles.has(f));
  return newFiles.length / currentFiles.length > FILE_SHIFT_THRESHOLD;
}

/**
 * Check if an event contains an explicit topic shift phrase.
 */
function hasTopicShift(event: NormalizedDevEvent): boolean {
  if (event.category !== "intent") return false;
  const text = event.content.detail;
  return TOPIC_SHIFT_PATTERNS.some((p) => p.test(text));
}

// ── Chunk Building ───────────────────────────────────────────────────

/**
 * Split events array at the given indices into sub-arrays.
 */
function splitAtIndices(
  events: NormalizedDevEvent[],
  indices: number[],
): NormalizedDevEvent[][] {
  if (indices.length === 0) return [events];

  const chunks: NormalizedDevEvent[][] = [];
  let start = 0;

  for (const idx of indices) {
    if (idx > start) {
      chunks.push(events.slice(start, idx));
    }
    start = idx;
  }

  // Remaining events after the last split
  if (start < events.length) {
    chunks.push(events.slice(start));
  }

  return chunks;
}

/**
 * If a chunk exceeds SIZE_CAP, split it at natural boundaries.
 */
function applySizeCap(events: NormalizedDevEvent[]): NormalizedDevEvent[][] {
  if (events.length <= SIZE_CAP) return [events];

  const result: NormalizedDevEvent[][] = [];
  let start = 0;

  while (start < events.length) {
    if (events.length - start <= SIZE_CAP) {
      result.push(events.slice(start));
      break;
    }

    // Find the nearest natural boundary around SIZE_CAP
    const target = start + SIZE_CAP;
    const splitAt = findNaturalBoundary(events, target);
    result.push(events.slice(start, splitAt));
    start = splitAt;
  }

  return result;
}

/**
 * Find a natural boundary near the target index.
 * Prefer splitting after a tool_result or before a conversation_turn.
 * Search within +/- 10 events of target.
 */
function findNaturalBoundary(
  events: NormalizedDevEvent[],
  target: number,
): number {
  const searchRadius = 10;
  const lo = Math.max(1, target - searchRadius);
  const hi = Math.min(events.length, target + searchRadius);

  // Prefer: after tool_result (split at i+1)
  for (let i = target; i >= lo; i--) {
    if (events[i - 1]?.category === "result") return i;
  }
  for (let i = target + 1; i < hi; i++) {
    if (events[i - 1]?.category === "result") return i;
  }

  // Fallback: before conversation_turn
  for (let i = target; i >= lo; i--) {
    if (events[i]?.category === "intent") return i;
  }
  for (let i = target + 1; i < hi; i++) {
    if (events[i]?.category === "intent") return i;
  }

  // Last resort: split at target
  return Math.min(target, events.length);
}

/**
 * Build final SessionChunk objects with overlap between consecutive chunks.
 */
function buildChunksWithOverlap(
  rawChunks: NormalizedDevEvent[][],
  sessionId: string,
): SessionChunk[] {
  const result: SessionChunk[] = [];

  for (let i = 0; i < rawChunks.length; i++) {
    const ownedEvents = rawChunks[i];
    // Prepend overlap from previous chunk (last OVERLAP events)
    const overlapEvents =
      i > 0 ? rawChunks[i - 1].slice(-OVERLAP) : [];

    result.push(buildChunk(ownedEvents, sessionId, i, overlapEvents));
  }

  return result;
}

/**
 * Build a single SessionChunk from owned events and optional overlap events.
 */
function buildChunk(
  ownedEvents: NormalizedDevEvent[],
  sessionId: string,
  chunkIndex: number,
  overlapEvents: NormalizedDevEvent[],
): SessionChunk {
  const allEvents = [...overlapEvents, ...ownedEvents];

  const startCausalOrder = ownedEvents[0].causalOrder;
  const endCausalOrder = ownedEvents[ownedEvents.length - 1].causalOrder;

  return {
    id: `${sessionId}-chunk-${chunkIndex}`,
    sessionId,
    chunkIndex,
    events: allEvents,
    topicHint: deriveTopicHint(ownedEvents),
    filesInScope: deriveFilesInScope(allEvents),
    eventRange: [startCausalOrder, endCausalOrder],
  };
}

// ── Topic Hint & Files ───────────────────────────────────────────────

/**
 * Derive a topic hint from the chunk's owned events.
 * Heuristic: most frequent directory/filename from filesAffected,
 * falling back to first user message summary.
 */
function deriveTopicHint(events: NormalizedDevEvent[]): string {
  // Count file path frequency
  const freq = new Map<string, number>();
  for (const event of events) {
    for (const file of getFilesAffected(event)) {
      freq.set(file, (freq.get(file) ?? 0) + 1);
    }
  }

  if (freq.size > 0) {
    // Return the most frequent file path
    let best = "";
    let bestCount = 0;
    for (const [file, count] of freq) {
      if (count > bestCount) {
        best = file;
        bestCount = count;
      }
    }
    return best;
  }

  // Fallback: first user message summary
  const userEvent = events.find((e) => e.category === "intent");
  if (userEvent) {
    return userEvent.content.summary;
  }

  return "unknown";
}

/**
 * Collect all unique files from events' filesAffected.
 */
function deriveFilesInScope(events: NormalizedDevEvent[]): string[] {
  const files = new Set<string>();
  for (const event of events) {
    for (const f of getFilesAffected(event)) {
      files.add(f);
    }
  }
  return Array.from(files);
}

/**
 * Get filesAffected from an event, defaulting to empty array.
 */
function getFilesAffected(event: NormalizedDevEvent): string[] {
  return event.content.filesAffected ?? [];
}

import { describe, it, expect } from "vitest";
import { chunkSession } from "../../src/pipeline/chunk.js";
import type { NormalizedDevEvent } from "../../src/adapters/types.js";

// ── Helpers ──────────────────────────────────────────────────────────

function makeEvent(
  overrides: Partial<NormalizedDevEvent> & { causalOrder: number },
): NormalizedDevEvent {
  const order = overrides.causalOrder;
  return {
    id: `s1-${order}`,
    sessionId: "s1",
    timestamp: overrides.timestamp ?? "2026-05-20T10:00:00.000Z",
    causalOrder: order,
    category: overrides.category ?? "action",
    actor: overrides.actor ?? "ai",
    content: overrides.content ?? {
      summary: `Event ${order}`,
      detail: `Detail for event ${order}`,
    },
    rawEventId: `raw-${order}`,
  };
}

/** Generate N events with sequential causalOrder and timestamps spaced 10s apart. */
function makeEvents(
  n: number,
  opts?: {
    startTime?: Date;
    category?: NormalizedDevEvent["category"];
    filesAffected?: string[];
  },
): NormalizedDevEvent[] {
  const start = opts?.startTime ?? new Date("2026-05-20T10:00:00.000Z");
  return Array.from({ length: n }, (_, i) => {
    const ts = new Date(start.getTime() + i * 10_000); // 10s apart
    return makeEvent({
      causalOrder: i,
      timestamp: ts.toISOString(),
      category: opts?.category,
      content: opts?.filesAffected
        ? {
            summary: `Event ${i}`,
            detail: `Detail for event ${i}`,
            filesAffected: opts.filesAffected,
          }
        : undefined,
    });
  });
}

// ── Tests ────────────────────────────────────────────────────────────

describe("chunkSession", () => {
  const sessionId = "test-session";

  // 1. Empty events → empty array
  it("returns empty array for empty events", () => {
    expect(chunkSession([], sessionId)).toEqual([]);
  });

  // 2. Short session (<10 events) → one chunk
  it("returns one chunk for short sessions (<10 events)", () => {
    const events = makeEvents(5);
    const chunks = chunkSession(events, sessionId);

    expect(chunks).toHaveLength(1);
    expect(chunks[0].chunkIndex).toBe(0);
    expect(chunks[0].events).toHaveLength(5);
    expect(chunks[0].eventRange).toEqual([0, 4]);
    expect(chunks[0].sessionId).toBe(sessionId);
    expect(chunks[0].id).toBe(`${sessionId}-chunk-0`);
  });

  // 3. Pause-based split (>5min gap)
  it("splits at pauses >5 minutes", () => {
    const t0 = new Date("2026-05-20T10:00:00.000Z");
    const events: NormalizedDevEvent[] = [];

    // First batch: 6 events, 10s apart
    for (let i = 0; i < 6; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
        }),
      );
    }

    // Gap of 10 minutes
    const afterGap = new Date(t0.getTime() + 6 * 10_000 + 10 * 60_000);

    // Second batch: 6 events after the gap
    for (let i = 6; i < 12; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(
            afterGap.getTime() + (i - 6) * 10_000,
          ).toISOString(),
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);

    expect(chunks).toHaveLength(2);
    expect(chunks[0].eventRange).toEqual([0, 5]);
    expect(chunks[1].eventRange).toEqual([6, 11]);
  });

  // 4. File cluster shift
  it("splits when file cluster shifts (>70% new files)", () => {
    const t0 = new Date("2026-05-20T10:00:00.000Z");
    const events: NormalizedDevEvent[] = [];

    // First 6 events touch files in src/
    for (let i = 0; i < 6; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
          content: {
            summary: `Edit src/file${i}.ts`,
            detail: `Editing src/file${i}.ts`,
            filesAffected: [`src/file${i}.ts`],
          },
        }),
      );
    }

    // Next 6 events touch completely different files in tests/
    for (let i = 6; i < 12; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
          content: {
            summary: `Edit tests/test${i}.ts`,
            detail: `Editing tests/test${i}.ts`,
            filesAffected: [`tests/test${i}.ts`],
          },
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);

    // Should split when files shift from src/ to tests/
    expect(chunks.length).toBeGreaterThanOrEqual(2);

    // First chunk should have src/ files in scope
    expect(chunks[0].filesInScope.some((f) => f.startsWith("src/"))).toBe(
      true,
    );
  });

  // 5. Explicit topic shift
  it("splits on explicit topic shift phrases in user messages", () => {
    const t0 = new Date("2026-05-20T10:00:00.000Z");
    const events: NormalizedDevEvent[] = [];

    // First batch: 6 events
    for (let i = 0; i < 6; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
        }),
      );
    }

    // Topic shift event
    events.push(
      makeEvent({
        causalOrder: 6,
        timestamp: new Date(t0.getTime() + 6 * 10_000).toISOString(),
        category: "intent",
        actor: "user",
        content: {
          summary: "Now let's work on the tests",
          detail: "Now let's work on the tests",
        },
      }),
    );

    // More events after shift
    for (let i = 7; i < 12; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);

    expect(chunks.length).toBeGreaterThanOrEqual(2);
    // The topic shift event should be at the start of a new chunk
    expect(chunks[1].eventRange[0]).toBe(6);
  });

  // 6. Size cap → splits at ~80 events at natural boundary
  it("splits chunks exceeding 80 events at natural boundaries", () => {
    const t0 = new Date("2026-05-20T10:00:00.000Z");
    const events: NormalizedDevEvent[] = [];

    // Create 100 events (exceeds 80 cap)
    for (let i = 0; i < 100; i++) {
      // Place some tool_results as natural boundaries
      const category: NormalizedDevEvent["category"] =
        i % 20 === 19 ? "result" : "action";
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
          category,
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);

    expect(chunks.length).toBeGreaterThanOrEqual(2);
    // Each chunk's owned events should not exceed ~80 + search radius
    for (const chunk of chunks) {
      const ownedCount =
        chunk.eventRange[1] - chunk.eventRange[0] + 1;
      expect(ownedCount).toBeLessThanOrEqual(90); // 80 + tolerance for boundary search
    }
  });

  // 7. Overlap → last 3 events of chunk N appear at start of chunk N+1
  it("includes 3-event overlap between consecutive chunks", () => {
    const t0 = new Date("2026-05-20T10:00:00.000Z");
    const events: NormalizedDevEvent[] = [];

    // Create 12 events split by a 10-minute pause after event 5
    for (let i = 0; i < 6; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
        }),
      );
    }

    const afterGap = new Date(t0.getTime() + 6 * 10_000 + 10 * 60_000);
    for (let i = 6; i < 12; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(
            afterGap.getTime() + (i - 6) * 10_000,
          ).toISOString(),
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);

    expect(chunks).toHaveLength(2);

    // First chunk: 6 owned events, no overlap
    expect(chunks[0].events).toHaveLength(6);
    expect(chunks[0].eventRange).toEqual([0, 5]);

    // Second chunk: 3 overlap + 6 owned = 9 events
    expect(chunks[1].events).toHaveLength(9);
    expect(chunks[1].eventRange).toEqual([6, 11]);

    // The overlap events should be the last 3 from chunk 0
    const overlapEvents = chunks[1].events.slice(0, 3);
    const lastThreeOfChunk0 = chunks[0].events.slice(-3);
    expect(overlapEvents.map((e) => e.causalOrder)).toEqual(
      lastThreeOfChunk0.map((e) => e.causalOrder),
    );
  });

  // ── Additional edge cases ──────────────────────────────────────────

  it("generates topic hint from most frequent file", () => {
    const events: NormalizedDevEvent[] = [];
    const t0 = new Date("2026-05-20T10:00:00.000Z");

    for (let i = 0; i < 5; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
          content: {
            summary: `Edit src/main.ts`,
            detail: `Editing src/main.ts`,
            filesAffected: ["src/main.ts"],
          },
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);
    expect(chunks[0].topicHint).toBe("src/main.ts");
  });

  it("falls back to user message for topic hint when no files", () => {
    const events: NormalizedDevEvent[] = [];
    const t0 = new Date("2026-05-20T10:00:00.000Z");

    events.push(
      makeEvent({
        causalOrder: 0,
        timestamp: t0.toISOString(),
        category: "intent",
        actor: "user",
        content: {
          summary: "Fix the login bug",
          detail: "Fix the login bug please",
        },
      }),
    );
    for (let i = 1; i < 5; i++) {
      events.push(
        makeEvent({
          causalOrder: i,
          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
          content: {
            summary: `AI response ${i}`,
            detail: `AI response detail ${i}`,
          },
        }),
      );
    }

    const chunks = chunkSession(events, sessionId);
    expect(chunks[0].topicHint).toBe("Fix the login bug");
  });

  it("collects all unique files in filesInScope", () => {
    const events: NormalizedDevEvent[] = [];
    const t0 = new Date("2026-05-20T10:00:00.000Z");

    events.push(
      makeEvent({
        causalOrder: 0,
        timestamp: t0.toISOString(),
        content: {
          summary: "Edit a.ts",
          detail: "Edit a.ts",
          filesAffected: ["src/a.ts"],
        },
      }),
    );
    events.push(
      makeEvent({
        causalOrder: 1,
        timestamp: new Date(t0.getTime() + 10_000).toISOString(),
        content: {
          summary: "Edit b.ts",
          detail: "Edit b.ts",
          filesAffected: ["src/b.ts"],
        },
      }),
    );
    events.push(
      makeEvent({
        causalOrder: 2,
        timestamp: new Date(t0.getTime() + 20_000).toISOString(),
        content: {
          summary: "Edit a.ts again",
          detail: "Edit a.ts again",
          filesAffected: ["src/a.ts"],
        },
      }),
    );

    const chunks = chunkSession(events, sessionId);
    expect(chunks[0].filesInScope.sort()).toEqual(["src/a.ts", "src/b.ts"]);
  });

  it("single-topic session with no split points produces one chunk", () => {
    const events = makeEvents(50, {
      filesAffected: ["src/same-file.ts"],
    });
    const chunks = chunkSession(events, sessionId);
    expect(chunks).toHaveLength(1);
    expect(chunks[0].events).toHaveLength(50);
  });
});

