content.content:
 1→// ── Raw Dev Event ─────────────────────────────────────────────────────
 2→// Unified event format produced by source adapters (Claude Code, etc.)
 3→
 4→export interface RawDevEvent {
 5→  /** Unique ID — the uuid from the original log entry */
 6→  id: string;
 7→
 8→  /** Which tool/system produced this event */
 9→  source: "claude-code";
10→
11→  /** ISO 8601 timestamp */
12→  timestamp: string;
13→
14→  /** Semantic event type */
15→  type:
16→    | "conversation_turn" // user message
17→    | "tool_call"         // AI tool use (Edit, Write, Bash, etc.)
18→    | "tool_result"       // tool results from user messages containing tool_result content
19→    | "ai_response";      // AI text response
20→
21→  /** Original log entry, preserved verbatim */
22→  raw: Record<string, unknown>;
23→}
24→
25→// ── Normalized Dev Event ─────────────────────────────────────────────
26→// Unified format consumed by the rest of the pipeline after normalization.
27→
28→export interface NormalizedDevEvent {
29→  id: string;
30→  sessionId: string;
31→  timestamp: string;
32→  causalOrder: number;
33→  category: "intent" | "proposal" | "action" | "result" | "reflection";
34→  actor: "user" | "ai";
35→  content: {
36→    summary: string;
37→    detail: string;
38→    filesAffected?: string[];
39→  };
40→  rawEventId: string;
41→}
42→
43→// ── Session Chunk ────────────────────────────────────────────────────
44→// Bounded reasoning window produced by the chunking step of the pipeline.
45→
46→export interface SessionChunk {
47→  id: string;
48→  sessionId: string;
49→  chunkIndex: number;
50→  events: NormalizedDevEvent[];
51→  topicHint: string;
52→  filesInScope: string[];
53→  eventRange: [number, number]; // [startCausalOrder, endCausalOrder]
54→}
55→
56→// ── Source Adapter Interface ──────────────────────────────────────────
57→
58→export interface SourceAdapter {
59→  /** Parse a log file and return raw events */
60→  parse(filePath: string): Promise<RawDevEvent[]>;
61→}
62→

 1→import { parseTranscript } from "@constellos/claude-code-kit/transcripts";
 2→import type { RawDevEvent } from "./types.js";
 3→
 4→/**
 5→ * Parse a Claude Code JSONL log file into RawDevEvent[].
 6→ *
 7→ * Uses claude-code-kit's parseTranscript for JSONL parsing and schema
 8→ * validation, then maps each message to one or more RawDevEvents:
 9→ *
10→ *  - User messages with string content → conversation_turn
11→ *  - User messages with tool_result content blocks → tool_result (one per block)
12→ *  - Assistant text blocks → ai_response
13→ *  - Assistant tool_use blocks → tool_call (one per block)
14→ *  - Thinking blocks, system messages → skipped
15→ */
16→export async function parseClaudeCodeLog(
17→  filePath: string,
18→): Promise<RawDevEvent[]> {
19→  const transcript = await parseTranscript(filePath, { lenient: true });
20→  const events: RawDevEvent[] = [];
21→
22→  for (const msg of transcript.messages) {
23→    const raw = msg as unknown as Record<string, unknown>;
24→    const base = {
25→      source: "claude-code" as const,
26→      timestamp: msg.timestamp,
27→      raw,
28→    };
29→
30→    if (msg.type === "user") {
31→      const content = msg.message.content;
32→
33→      // String content → single conversation_turn
34→      if (typeof content === "string") {
35→        events.push({
36→          ...base,
37→          id: msg.uuid,
38→          type: "conversation_turn",
39→        });
40→        continue;
41→      }
42→
43→      // Array of tool_result blocks → one tool_result event per block
44→      if (Array.isArray(content)) {
45→        for (let i = 0; i < content.length; i++) {
46→          const block = content[i];
47→          if (block.type === "tool_result") {
48→            events.push({
49→              ...base,
50→              id: `${msg.uuid}-result-${i}`,
51→              type: "tool_result",
52→            });
53→          }
54→        }
55→      }
56→      continue;
57→    }
58→
59→    if (msg.type === "assistant") {
60→      const content = msg.message.content;
61→
62→      for (let i = 0; i < content.length; i++) {
63→        const block = content[i];
64→
65→        if (block.type === "text") {
66→          events.push({
67→            ...base,
68→            id: `${msg.uuid}-text-${i}`,
69→            type: "ai_response",
70→          });
71→        } else if (block.type === "tool_use") {
72→          events.push({
73→            ...base,
74→            id: `${msg.uuid}-tool-${i}`,
75→            type: "tool_call",
76→          });
77→        }
78→        // skip "thinking" blocks
79→      }
80→      continue;
81→    }
82→
83→    // Skip system messages
84→  }
85→
86→  return events;
87→}
