  1→import type { NormalizedDevEvent, SessionChunk } from "../adapters/types.js";
  2→
  3→// ── Constants ────────────────────────────────────────────────────────
  4→
  5→const PAUSE_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes
  6→const FILE_SHIFT_THRESHOLD = 0.7; // 70% new files
  7→const SIZE_CAP = 80;
  8→const OVERLAP = 3;
  9→const SHORT_SESSION_THRESHOLD = 10;
 10→
 11→const TOPIC_SHIFT_PATTERNS = [
 12→  /\bnow let'?s\b/i,
 13→  /\bmoving on\b/i,
 14→  /\bnext\b/i,
 15→  /\bswitch to\b/i,
 16→  /\bok let'?s work on\b/i,
 17→];
 18→
 19→// ── Main Entry Point ─────────────────────────────────────────────────
 20→
 21→/**
 22→ * Split a session's normalized events into bounded reasoning windows (chunks).
 23→ * Deterministic — no LLM calls.
 24→ */
 25→export function chunkSession(
 26→  events: NormalizedDevEvent[],
 27→  sessionId: string,
 28→): SessionChunk[] {
 29→  if (events.length === 0) return [];
 30→
 31→  // Short sessions: one chunk, no splitting
 32→  if (events.length < SHORT_SESSION_THRESHOLD) {
 33→    return [buildChunk(events, sessionId, 0, [])];
 34→  }
 35→
 36→  // Find all split points
 37→  const splitIndices = findSplitPoints(events);
 38→
 39→  // Build chunks from split points
 40→  const rawChunks = splitAtIndices(events, splitIndices);
 41→
 42→  // Apply size cap to oversized chunks
 43→  const cappedChunks = rawChunks.flatMap((chunk) => applySizeCap(chunk));
 44→
 45→  // Build SessionChunk objects with overlap
 46→  return buildChunksWithOverlap(cappedChunks, sessionId);
 47→}
 48→
 49→// ── Split Point Detection ────────────────────────────────────────────
 50→
 51→/**
 52→ * Find indices where the event list should be split.
 53→ * A split index N means: chunk boundary between events[N-1] and events[N].
 54→ */
 55→function findSplitPoints(events: NormalizedDevEvent[]): number[] {
 56→  const splits = new Set<number>();
 57→
 58→  for (let i = 1; i < events.length; i++) {
 59→    // Priority 1: Large pauses (>5 min gap)
 60→    const gap =
 61→      new Date(events[i].timestamp).getTime() -
 62→      new Date(events[i - 1].timestamp).getTime();
 63→    if (gap > PAUSE_THRESHOLD_MS) {
 64→      splits.add(i);
 65→      continue;
 66→    }
 67→
 68→    // Priority 2: File cluster shift
 69→    if (hasFileClusterShift(events, i)) {
 70→      splits.add(i);
 71→      continue;
 72→    }
 73→
 74→    // Priority 3: Explicit topic shift in user messages
 75→    if (hasTopicShift(events[i])) {
 76→      splits.add(i);
 77→    }
 78→  }
 79→
 80→  return Array.from(splits).sort((a, b) => a - b);
 81→}
 82→
 83→/**
 84→ * Check if >70% of files at index i are new compared to
 85→ * the preceding window of events (look back up to 10 events).
 86→ */
 87→function hasFileClusterShift(
 88→  events: NormalizedDevEvent[],
 89→  index: number,
 90→): boolean {
 91→  const currentFiles = getFilesAffected(events[index]);
 92→  if (currentFiles.length === 0) return false;
 93→
 94→  // Collect files from the preceding window (up to 10 events back)
 95→  const lookback = Math.max(0, index - 10);
 96→  const previousFiles = new Set<string>();
 97→  for (let j = lookback; j < index; j++) {
 98→    for (const f of getFilesAffected(events[j])) {
 99→      previousFiles.add(f);
100→    }
101→  }
102→
103→  if (previousFiles.size === 0) return false;
104→
105→  const newFiles = currentFiles.filter((f) => !previousFiles.has(f));
106→  return newFiles.length / currentFiles.length > FILE_SHIFT_THRESHOLD;
107→}
108→
109→/**
110→ * Check if an event contains an explicit topic shift phrase.
111→ */
112→function hasTopicShift(event: NormalizedDevEvent): boolean {
113→  if (event.category !== "intent") return false;
114→  const text = event.content.detail;
115→  return TOPIC_SHIFT_PATTERNS.some((p) => p.test(text));
116→}
117→
118→// ── Chunk Building ───────────────────────────────────────────────────
119→
120→/**
121→ * Split events array at the given indices into sub-arrays.
122→ */
123→function splitAtIndices(
124→  events: NormalizedDevEvent[],
125→  indices: number[],
126→): NormalizedDevEvent[][] {
127→  if (indices.length === 0) return [events];
128→
129→  const chunks: NormalizedDevEvent[][] = [];
130→  let start = 0;
131→
132→  for (const idx of indices) {
133→    if (idx > start) {
134→      chunks.push(events.slice(start, idx));
135→    }
136→    start = idx;
137→  }
138→
139→  // Remaining events after the last split
140→  if (start < events.length) {
141→    chunks.push(events.slice(start));
142→  }
143→
144→  return chunks;
145→}
146→
147→/**
148→ * If a chunk exceeds SIZE_CAP, split it at natural boundaries.
149→ */
150→function applySizeCap(events: NormalizedDevEvent[]): NormalizedDevEvent[][] {
151→  if (events.length <= SIZE_CAP) return [events];
152→
153→  const result: NormalizedDevEvent[][] = [];
154→  let start = 0;
155→
156→  while (start < events.length) {
157→    if (events.length - start <= SIZE_CAP) {
158→      result.push(events.slice(start));
159→      break;
160→    }
161→
162→    // Find the nearest natural boundary around SIZE_CAP
163→    const target = start + SIZE_CAP;
164→    const splitAt = findNaturalBoundary(events, target);
165→    result.push(events.slice(start, splitAt));
166→    start = splitAt;
167→  }
168→
169→  return result;
170→}
171→
172→/**
173→ * Find a natural boundary near the target index.
174→ * Prefer splitting after a tool_result or before a conversation_turn.
175→ * Search within +/- 10 events of target.
176→ */
177→function findNaturalBoundary(
178→  events: NormalizedDevEvent[],
179→  target: number,
180→): number {
181→  const searchRadius = 10;
182→  const lo = Math.max(1, target - searchRadius);
183→  const hi = Math.min(events.length, target + searchRadius);
184→
185→  // Prefer: after tool_result (split at i+1)
186→  for (let i = target; i >= lo; i--) {
187→    if (events[i - 1]?.category === "result") return i;
188→  }
189→  for (let i = target + 1; i < hi; i++) {
190→    if (events[i - 1]?.category === "result") return i;
191→  }
192→
193→  // Fallback: before conversation_turn
194→  for (let i = target; i >= lo; i--) {
195→    if (events[i]?.category === "intent") return i;
196→  }
197→  for (let i = target + 1; i < hi; i++) {
198→    if (events[i]?.category === "intent") return i;
199→  }
200→
201→  // Last resort: split at target
202→  return Math.min(target, events.length);
203→}
204→
205→/**
206→ * Build final SessionChunk objects with overlap between consecutive chunks.
207→ */
208→function buildChunksWithOverlap(
209→  rawChunks: NormalizedDevEvent[][],
210→  sessionId: string,
211→): SessionChunk[] {
212→  const result: SessionChunk[] = [];
213→
214→  for (let i = 0; i < rawChunks.length; i++) {
215→    const ownedEvents = rawChunks[i];
216→    // Prepend overlap from previous chunk (last OVERLAP events)
217→    const overlapEvents =
218→      i > 0 ? rawChunks[i - 1].slice(-OVERLAP) : [];
219→
220→    result.push(buildChunk(ownedEvents, sessionId, i, overlapEvents));
221→  }
222→
223→  return result;
224→}
225→
226→/**
227→ * Build a single SessionChunk from owned events and optional overlap events.
228→ */
229→function buildChunk(
230→  ownedEvents: NormalizedDevEvent[],
231→  sessionId: string,
232→  chunkIndex: number,
233→  overlapEvents: NormalizedDevEvent[],
234→): SessionChunk {
235→  const allEvents = [...overlapEvents, ...ownedEvents];
236→
237→  const startCausalOrder = ownedEvents[0].causalOrder;
238→  const endCausalOrder = ownedEvents[ownedEvents.length - 1].causalOrder;
239→
240→  return {
241→    id: `${sessionId}-chunk-${chunkIndex}`,
242→    sessionId,
243→    chunkIndex,
244→    events: allEvents,
245→    topicHint: deriveTopicHint(ownedEvents),
246→    filesInScope: deriveFilesInScope(allEvents),
247→    eventRange: [startCausalOrder, endCausalOrder],
248→  };
249→}
250→
251→// ── Topic Hint & Files ───────────────────────────────────────────────
252→
253→/**
254→ * Derive a topic hint from the chunk's owned events.
255→ * Heuristic: most frequent directory/filename from filesAffected,
256→ * falling back to first user message summary.
257→ */
258→function deriveTopicHint(events: NormalizedDevEvent[]): string {
259→  // Count file path frequency
260→  const freq = new Map<string, number>();
261→  for (const event of events) {
262→    for (const file of getFilesAffected(event)) {
263→      freq.set(file, (freq.get(file) ?? 0) + 1);
264→    }
265→  }
266→
267→  if (freq.size > 0) {
268→    // Return the most frequent file path
269→    let best = "";
270→    let bestCount = 0;
271→    for (const [file, count] of freq) {
272→      if (count > bestCount) {
273→        best = file;
274→        bestCount = count;
275→      }
276→    }
277→    return best;
278→  }
279→
280→  // Fallback: first user message summary
281→  const userEvent = events.find((e) => e.category === "intent");
282→  if (userEvent) {
283→    return userEvent.content.summary;
284→  }
285→
286→  return "unknown";
287→}
288→
289→/**
290→ * Collect all unique files from events' filesAffected.
291→ */
292→function deriveFilesInScope(events: NormalizedDevEvent[]): string[] {
293→  const files = new Set<string>();
294→  for (const event of events) {
295→    for (const f of getFilesAffected(event)) {
296→      files.add(f);
297→    }
298→  }
299→  return Array.from(files);
300→}
301→
302→/**
303→ * Get filesAffected from an event, defaulting to empty array.
304→ */
305→function getFilesAffected(event: NormalizedDevEvent): string[] {
306→  return event.content.filesAffected ?? [];
307→}
308→

 1→import { readdir, stat } from "node:fs/promises";
 2→import { homedir } from "node:os";
 3→import { join } from "node:path";
 4→
 5→const CLAUDE_PROJECTS_DIR = join(homedir(), ".claude", "projects");
 6→
 7→interface LogFile {
 8→  path: string;
 9→  mtime: Date;
10→}
11→
12→/** Recursively collect all .jsonl files under a directory */
13→async function collectJsonl(dir: string): Promise<LogFile[]> {
14→  const results: LogFile[] = [];
15→
16→  let entries;
17→  try {
18→    entries = await readdir(dir, { withFileTypes: true });
19→  } catch {
20→    return results;
21→  }
22→
23→  for (const entry of entries) {
24→    const fullPath = join(dir, entry.name);
25→    if (entry.isDirectory()) {
26→      results.push(...(await collectJsonl(fullPath)));
27→    } else if (entry.isFile() && entry.name.endsWith(".jsonl")) {
28→      const info = await stat(fullPath);
29→      results.push({ path: fullPath, mtime: info.mtime });
30→    }
31→  }
32→
33→  return results;
34→}
35→
36→/**
37→ * Find the most recent JSONL log in ~/.claude/projects/.
38→ * If projectDir is provided, scopes to that project's subdirectory.
39→ */
40→export async function discoverLatestLog(
41→  projectDir?: string,
42→): Promise<string | null> {
43→  const logs = await discoverLogs(1, projectDir);
44→  return logs[0] ?? null;
45→}
46→
47→/**
48→ * Return the N most recent JSONL log files, newest first.
49→ * If projectDir is provided, scopes to that project's subdirectory.
50→ */
51→export async function discoverLogs(
52→  count: number,
53→  projectDir?: string,
54→): Promise<string[]> {
55→  const searchDir = projectDir
56→    ? join(CLAUDE_PROJECTS_DIR, projectDir)
57→    : CLAUDE_PROJECTS_DIR;
58→
59→  const files = await collectJsonl(searchDir);
60→
61→  files.sort((a, b) => b.mtime.getTime() - a.mtime.getTime());
62→
63→  return files.slice(0, count).map((f) => f.path);
64→}
