  1→import { describe, it, expect } from "vitest";
  2→import { chunkSession } from "../../src/pipeline/chunk.js";
  3→import type { NormalizedDevEvent } from "../../src/adapters/types.js";
  4→
  5→// ── Helpers ──────────────────────────────────────────────────────────
  6→
  7→function makeEvent(
  8→  overrides: Partial<NormalizedDevEvent> & { causalOrder: number },
  9→): NormalizedDevEvent {
 10→  const order = overrides.causalOrder;
 11→  return {
 12→    id: `s1-${order}`,
 13→    sessionId: "s1",
 14→    timestamp: overrides.timestamp ?? "2026-05-20T10:00:00.000Z",
 15→    causalOrder: order,
 16→    category: overrides.category ?? "action",
 17→    actor: overrides.actor ?? "ai",
 18→    content: overrides.content ?? {
 19→      summary: `Event ${order}`,
 20→      detail: `Detail for event ${order}`,
 21→    },
 22→    rawEventId: `raw-${order}`,
 23→  };
 24→}
 25→
 26→/** Generate N events with sequential causalOrder and timestamps spaced 10s apart. */
 27→function makeEvents(
 28→  n: number,
 29→  opts?: {
 30→    startTime?: Date;
 31→    category?: NormalizedDevEvent["category"];
 32→    filesAffected?: string[];
 33→  },
 34→): NormalizedDevEvent[] {
 35→  const start = opts?.startTime ?? new Date("2026-05-20T10:00:00.000Z");
 36→  return Array.from({ length: n }, (_, i) => {
 37→    const ts = new Date(start.getTime() + i * 10_000); // 10s apart
 38→    return makeEvent({
 39→      causalOrder: i,
 40→      timestamp: ts.toISOString(),
 41→      category: opts?.category,
 42→      content: opts?.filesAffected
 43→        ? {
 44→            summary: `Event ${i}`,
 45→            detail: `Detail for event ${i}`,
 46→            filesAffected: opts.filesAffected,
 47→          }
 48→        : undefined,
 49→    });
 50→  });
 51→}
 52→
 53→// ── Tests ────────────────────────────────────────────────────────────
 54→
 55→describe("chunkSession", () => {
 56→  const sessionId = "test-session";
 57→
 58→  // 1. Empty events → empty array
 59→  it("returns empty array for empty events", () => {
 60→    expect(chunkSession([], sessionId)).toEqual([]);
 61→  });
 62→
 63→  // 2. Short session (<10 events) → one chunk
 64→  it("returns one chunk for short sessions (<10 events)", () => {
 65→    const events = makeEvents(5);
 66→    const chunks = chunkSession(events, sessionId);
 67→
 68→    expect(chunks).toHaveLength(1);
 69→    expect(chunks[0].chunkIndex).toBe(0);
 70→    expect(chunks[0].events).toHaveLength(5);
 71→    expect(chunks[0].eventRange).toEqual([0, 4]);
 72→    expect(chunks[0].sessionId).toBe(sessionId);
 73→    expect(chunks[0].id).toBe(`${sessionId}-chunk-0`);
 74→  });
 75→
 76→  // 3. Pause-based split (>5min gap)
 77→  it("splits at pauses >5 minutes", () => {
 78→    const t0 = new Date("2026-05-20T10:00:00.000Z");
 79→    const events: NormalizedDevEvent[] = [];
 80→
 81→    // First batch: 6 events, 10s apart
 82→    for (let i = 0; i < 6; i++) {
 83→      events.push(
 84→        makeEvent({
 85→          causalOrder: i,
 86→          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
 87→        }),
 88→      );
 89→    }
 90→
 91→    // Gap of 10 minutes
 92→    const afterGap = new Date(t0.getTime() + 6 * 10_000 + 10 * 60_000);
 93→
 94→    // Second batch: 6 events after the gap
 95→    for (let i = 6; i < 12; i++) {
 96→      events.push(
 97→        makeEvent({
 98→          causalOrder: i,
 99→          timestamp: new Date(
100→            afterGap.getTime() + (i - 6) * 10_000,
101→          ).toISOString(),
102→        }),
103→      );
104→    }
105→
106→    const chunks = chunkSession(events, sessionId);
107→
108→    expect(chunks).toHaveLength(2);
109→    expect(chunks[0].eventRange).toEqual([0, 5]);
110→    expect(chunks[1].eventRange).toEqual([6, 11]);
111→  });
112→
113→  // 4. File cluster shift
114→  it("splits when file cluster shifts (>70% new files)", () => {
115→    const t0 = new Date("2026-05-20T10:00:00.000Z");
116→    const events: NormalizedDevEvent[] = [];
117→
118→    // First 6 events touch files in src/
119→    for (let i = 0; i < 6; i++) {
120→      events.push(
121→        makeEvent({
122→          causalOrder: i,
123→          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
124→          content: {
125→            summary: `Edit src/file${i}.ts`,
126→            detail: `Editing src/file${i}.ts`,
127→            filesAffected: [`src/file${i}.ts`],
128→          },
129→        }),
130→      );
131→    }
132→
133→    // Next 6 events touch completely different files in tests/
