138→          timestamp: new Date(t0.getTime() + i * 10_000).toISOString(),
139→          content: {
140→            summary: `Edit tests/test${i}.ts`,
141→            detail: `Editing tests/test${i}.ts`,
142→            filesAffected: [`tests/test${i}.ts`],
143→          },
144→        }),
145→      );
146→    }
147→
148→    const chunks = chunkSession(events, sessionId);
149→
150→    // Should split when files shift from src/ to tests/
151→    expect(chunks.length).toBeGreaterThanOrEqual(2);
152→
153→    // First chunk should have src/ files in scope
154→    expect(chunks[0].filesInScope.some((f) => f.startsWith("src/"))).toBe(
