import { parseClaudeCodeLog } from './src/adapters/claude-code.js';
import { normalize } from './src/pipeline/normalize.js';
import { chunkSession } from './src/pipeline/chunk.js';
import { randomUUID } from 'crypto';
import { homedir } from 'os';
import { join } from 'path';

const LOG = join(homedir(), '.claude/projects/-Users-giladkoch-dev-intent-ai/84280b36-1375-4a79-9d53-e31c6d124146.jsonl');

async function main() {
  console.log('=== STEP 1: Parse CC Log ===');
  const raw = await parseClaudeCodeLog(LOG);
  console.log('Raw events:', raw.length);
  const typeCounts: Record<string, number> = {};
  for (const e of raw) typeCounts[e.type] = (typeCounts[e.type] || 0) + 1;
  console.log('By type:', JSON.stringify(typeCounts, null, 2));

  console.log('\n=== STEP 2: Normalize ===');
  const sessionId = randomUUID();
  const normalized = normalize(raw, sessionId);
  console.log('Normalized events:', normalized.length);
  const catCounts: Record<string, number> = {};
  for (const e of normalized) catCounts[e.category] = (catCounts[e.category] || 0) + 1;
  console.log('By category:', JSON.stringify(catCounts, null, 2));
  const actorCounts: Record<string, number> = {};
  for (const e of normalized) actorCounts[e.actor] = (actorCounts[e.actor] || 0) + 1;
  console.log('By actor:', JSON.stringify(actorCounts, null, 2));

  console.log('\nFirst 15 events:');
  for (const e of normalized.slice(0, 15)) {
    console.log(`  [${e.causalOrder}] ${e.actor}/${e.category}: ${e.content.summary.slice(0, 120)}`);
  }

  console.log('\n=== STEP 3: Chunk ===');
  const chunks = chunkSession(normalized, sessionId);
  console.log('Chunks:', chunks.length);
  for (const c of chunks) {
    console.log(`\n  Chunk ${c.chunkIndex}: ${c.events.length} events, range [${c.eventRange[0]}-${c.eventRange[1]}]`);
    console.log(`    Topic: ${c.topicHint.slice(0, 100)}`);
    console.log(`    Files: ${c.filesInScope.slice(0, 3).join(', ')}${c.filesInScope.length > 3 ? ` (+${c.filesInScope.length - 3} more)` : ''}`);
  }
}

main().catch(console.error);

