  1→import type { NormalizedDevEvent, SessionChunk } from "../adapters/types.js";
  2→
  3→// ── Constants ────────────────────────────────────────────────────────
  4→
  5→const PAUSE_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes
  6→const FILE_SHIFT_THRESHOLD = 0.7; // 70% new files
  7→const SIZE_CAP = 80;
  8→const OVERLAP = 3;
  9→const SHORT_SESSION_THRESHOLD = 10;
 10→
 11→const TOPIC_SHIFT_PATTERNS = [
 12→  /\bnow let'?s\b/i,
 13→  /\bmoving on\b/i,
 14→  /\bnext\b/i,
 15→  /\bswitch to\b/i,
 16→  /\bok let'?s work on\b/i,
 17→];
 18→
 19→// ── Main Entry Point ─────────────────────────────────────────────────
 20→
 21→/**
 22→ * Split a session's normalized events into bounded reasoning windows (chunks).
 23→ * Deterministic — no LLM calls.
 24→ */
 25→export function chunkSession(
 26→  events: NormalizedDevEvent[],
 27→  sessionId: string,
 28→): SessionChunk[] {
 29→  if (events.length === 0) return [];
 30→
 31→  // Short sessions: one chunk, no splitting
 32→  if (events.length < SHORT_SESSION_THRESHOLD) {
 33→    return [buildChunk(events, sessionId, 0, [])];
 34→  }
 35→
 36→  // Find all split points
 37→  const splitIndices = findSplitPoints(events);
 38→
 39→  // Build chunks from split points
 40→  const rawChunks = splitAtIndices(events, splitIndices);
 41→
 42→  // Apply size cap to oversized chunks
 43→  const cappedChunks = rawChunks.flatMap((chunk) => applySizeCap(chunk));
 44→
 45→  // Build SessionChunk objects with overlap
 46→  return buildChunksWithOverlap(cappedChunks, sessionId);
 47→}
 48→
 49→// ── Split Point Detection ────────────────────────────────────────────
 50→
 51→/**
 52→ * Find indices where the event list should be split.
 53→ * A split index N means: chunk boundary between events[N-1] and events[N].
 54→ */
 55→function findSplitPoints(events: NormalizedDevEvent[]): number[] {
 56→  const splits = new Set<number>();
 57→
 58→  for (let i = 1; i < events.length; i++) {
 59→    // Priority 1: Large pauses (>5 min gap)
 60→    const gap =
 61→      new Date(events[i].timestamp).getTime() -
 62→      new Date(events[i - 1].timestamp).getTime();
 63→    if (gap > PAUSE_THRESHOLD_MS) {
 64→      splits.add(i);
 65→      continue;
 66→    }
 67→
 68→    // Priority 2: File cluster shift
 69→    if (hasFileClusterShift(events, i)) {
 70→      splits.add(i);
 71→      continue;
 72→    }
 73→
 74→    // Priority 3: Explicit topic shift in user messages
 75→    if (hasTopicShift(events[i])) {
 76→      splits.add(i);
 77→    }
 78→  }
 79→
 80→  return Array.from(splits).sort((a, b) => a - b);
 81→}
 82→
 83→/**
 84→ * Check if >70% of files at index i are new compared to
 85→ * the preceding window of events (look back up to 10 events).
 86→ */
 87→function hasFileClusterShift(
 88→  events: NormalizedDevEvent[],
 89→  index: number,
 90→): boolean {
 91→  const currentFiles = getFilesAffected(events[index]);
 92→  if (currentFiles.length === 0) return false;
 93→
 94→  // Collect files from the preceding window (up to 10 events back)
 95→  const lookback = Math.max(0, index - 10);
 96→  const previousFiles = new Set<string>();
 97→  for (let j = lookback; j < index; j++) {
 98→    for (const f of getFilesAffected(events[j])) {
 99→      previousFiles.add(f);
100→    }
101→  }
102→
103→  if (previousFiles.size === 0) return false;
104→
105→  const newFiles = currentFiles.filter((f) => !previousFiles.has(f));
106→  return newFiles.length / currentFiles.length > FILE_SHIFT_THRESHOLD;
107→}
108→
109→/**
110→ * Check if an event contains an explicit topic shift phrase.
111→ */
112→function hasTopicShift(event: NormalizedDevEvent): boolean {
113→  if (event.category !== "intent") return false;
114→  const text = event.content.detail;
115→  return TOPIC_SHIFT_PATTERNS.some((p) => p.test(text));
116→}
117→
118→// ── Chunk Building ───────────────────────────────────────────────────
119→
120→/**
121→ * Split events array at the given indices into sub-arrays.
122→ */
123→function splitAtIndices(
124→  events: NormalizedDevEvent[],
125→  indices: number[],
126→): NormalizedDevEvent[][] {
127→  if (indices.length === 0) return [events];
128→
129→  const chunks: NormalizedDevEvent[][] = [];
130→  let start = 0;
131→
132→  for (const idx of indices) {
133→    if (idx > start) {
134→      chunks.push(events.slice(start, idx));
