import { parseClaudeCodeLog } from './src/adapters/claude-code.js';
import { normalize } from './src/pipeline/normalize.js';
import { chunkSession } from './src/pipeline/chunk.js';
import { randomUUID } from 'crypto';
import { homedir } from 'os';
import { join } from 'path';

const LOG = join(homedir(), '.claude/projects/-Users-giladkoch-dev-intent-ai/84280b36-1375-4a79-9d53-e31c6d124146.jsonl');

async function main() {
  const raw = await parseClaudeCodeLog(LOG);
  const sessionId = randomUUID();
  const normalized = normalize(raw, sessionId);
  const chunks = chunkSession(normalized, sessionId);

  // Show what caused each split
  for (let i = 0; i < chunks.length; i++) {
    const c = chunks[i];
    const firstOwned = c.events.find(e => e.causalOrder === c.eventRange[0]);
    const prevChunk = i > 0 ? chunks[i-1] : null;

    let splitReason = 'START';
    if (prevChunk && firstOwned) {
      const prevLast = normalized.find(e => e.causalOrder === prevChunk.eventRange[1]);
      if (prevLast) {
        const gap = new Date(firstOwned.timestamp).getTime() - new Date(prevLast.timestamp).getTime();
        const gapMin = (gap / 60000).toFixed(1);

        // Check what triggered the split
        if (gap > 5 * 60 * 1000) {
          splitReason = `PAUSE (${gapMin}min gap)`;
        } else if (firstOwned.category === 'intent') {
          splitReason = `TOPIC_SHIFT: "${firstOwned.content.summary.slice(0, 80)}"`;
        } else {
          splitReason = `FILE_SHIFT (${gapMin}min gap)`;
        }
      }
    }

    console.log(`\nChunk ${c.chunkIndex} [${c.eventRange[0]}-${c.eventRange[1]}] (${c.events.length} events) — ${splitReason}`);
    console.log(`  Topic: ${c.topicHint.slice(0, 80)}`);
    console.log(`  Files: ${c.filesInScope.length} files`);
  }
}

main().catch(console.error);

