import Anthropic from "@anthropic-ai/sdk";
import type { z } from "zod";

// ── Constants ────────────────────────────────────────────────────────

const SONNET_MODEL = "claude-sonnet-4-20250514";
const HAIKU_MODEL = "claude-haiku-4-5-20251001";

const MAX_RETRIES = 3;
const BASE_DELAY_MS = 1000;

// ── Lazy Client ──────────────────────────────────────────────────────

let _client: Anthropic | undefined;

function getClient(): Anthropic {
  if (!_client) {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      throw new Error(
        "ANTHROPIC_API_KEY is not set. Export it in your environment or add it to .env",
      );
    }
    _client = new Anthropic({ apiKey });
  }
  return _client;
}

// ── Public Interface ─────────────────────────────────────────────────

export interface LlmCallOptions {
  maxTokens?: number;
  temperature?: number;
}

/**
 * Call Claude Sonnet with a structured JSON response validated against a Zod schema.
 */
export async function callSonnet<T>(
  systemPrompt: string,
  userPrompt: string,
  schema: z.ZodType<T>,
  options?: LlmCallOptions,
): Promise<T> {
  return callModel(SONNET_MODEL, systemPrompt, userPrompt, schema, options);
}

/**
 * Call Claude Haiku with a structured JSON response validated against a Zod schema.
 */
export async function callHaiku<T>(
  systemPrompt: string,
  userPrompt: string,
  schema: z.ZodType<T>,
  options?: LlmCallOptions,
): Promise<T> {
  return callModel(HAIKU_MODEL, systemPrompt, userPrompt, schema, options);
}

// ── Internal ─────────────────────────────────────────────────────────

async function callModel<T>(
  model: string,
  systemPrompt: string,
  userPrompt: string,
  schema: z.ZodType<T>,
  options?: LlmCallOptions,
): Promise<T> {
  const maxTokens = options?.maxTokens ?? 4096;
  const temperature = options?.temperature ?? 0;

  let lastError: unknown;

  // Retry loop for network / rate-limit errors
  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      const text = await rawCall(model, systemPrompt, userPrompt, maxTokens, temperature);
      return validateJson(text, schema);
    } catch (err) {
      if (isValidationError(err)) {
        // Validation failed — retry once with a stricter prompt
        return retryWithStricterPrompt(model, systemPrompt, userPrompt, schema, maxTokens, temperature, err);
      }

      // Network / rate-limit — exponential backoff
      lastError = err;
      if (attempt < MAX_RETRIES - 1) {
        const delay = BASE_DELAY_MS * Math.pow(2, attempt);
        await sleep(delay);
      }
    }
  }

  throw new Error(
    `LLM call failed after ${MAX_RETRIES} retries: ${lastError instanceof Error ? lastError.message : String(lastError)}`,
  );
}

async function rawCall(
  model: string,
  systemPrompt: string,
  userPrompt: string,
  maxTokens: number,
  temperature: number,
): Promise<string> {
  const client = getClient();
  const response = await client.messages.create({
    model,
    max_tokens: maxTokens,
    temperature,
    system: systemPrompt,
    messages: [{ role: "user", content: userPrompt }],
  });

  const textBlock = response.content.find((b) => b.type === "text");
  if (!textBlock || textBlock.type !== "text") {
    throw new Error("No text block in LLM response");
  }
  return textBlock.text;
}

function validateJson<T>(text: string, schema: z.ZodType<T>): T {
  // Strip markdown code fences if present
  const cleaned = text
    .replace(/^```(?:json)?\s*\n?/i, "")
    .replace(/\n?```\s*$/i, "")
    .trim();

  let parsed: unknown;
  try {
    parsed = JSON.parse(cleaned);
  } catch {
    throw new ValidationError(`LLM returned invalid JSON: ${cleaned.slice(0, 200)}`);
  }

  const result = schema.safeParse(parsed);
  if (!result.success) {
    throw new ValidationError(
      `Zod validation failed: ${JSON.stringify(result.error.issues ?? result.error, null, 2).slice(0, 500)}`,
    );
  }
  return result.data;
}

async function retryWithStricterPrompt<T>(
  model: string,
  systemPrompt: string,
  userPrompt: string,
  schema: z.ZodType<T>,
  maxTokens: number,
  temperature: number,
  originalError: ValidationError,
): Promise<T> {
  const stricterUser = [
    userPrompt,
    "",
    "IMPORTANT: Your previous response was not valid JSON or did not match the required schema.",
    `Error: ${originalError.message}`,
    "",
    "Please respond with ONLY valid JSON (no markdown fences, no explanation). Ensure every required field is present and has the correct type.",
  ].join("\n");

  try {
    const text = await rawCall(model, systemPrompt, stricterUser, maxTokens, temperature);
    return validateJson(text, schema);
  } catch (retryErr) {
    throw new Error(
      `LLM validation failed after retry. Original: ${originalError.message}. Retry: ${retryErr instanceof Error ? retryErr.message : String(retryErr)}`,
    );
  }
}

// ── Helpers ──────────────────────────────────────────────────────────

class ValidationError extends Error {
  readonly isValidation = true;
  constructor(message: string) {
    super(message);
    this.name = "ValidationError";
  }
}

function isValidationError(err: unknown): err is ValidationError {
  return err instanceof ValidationError;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import { z } from "zod";

// ── Zod Schema ───────────────────────────────────────────────────────

export const SessionShapeSchema = z.object({
  shape: z.enum(["narrative", "exploratory", "janitorial", "debugging", "review"]),
});

export type SessionShape = z.infer<typeof SessionShapeSchema>;

// ── Prompt Input ─────────────────────────────────────────────────────

export interface ClassifyInput {
  /** Total number of events by type */
  eventCounts: Record<string, number>;
  /** List of files touched during the session */
  files: string[];
  /** Sample of user messages (first few, representative) */
  sampleUserMessages: string[];
  /** Total event count */
  totalEvents: number;
}

// ── Prompt Builder ───────────────────────────────────────────────────

export function buildClassifyPrompt(input: ClassifyInput): {
  system: string;
  user: string;
} {
  const system = `You are a development session classifier. You analyze a summary of a developer's coding session and classify it into one of five shapes.

Session shapes:

1. **narrative** — The session tells a story of building something. There is a clear arc: the developer starts with an intent, works through implementation, and arrives at a result. Characterized by a mix of intent, action, and reflection events. The developer is driving toward a goal.

2. **exploratory** — The session is about understanding, investigating, or experimenting. The developer is reading code, searching, asking questions, trying things out. Lots of reflection events, Read/Grep/Glob tool calls. No clear build arc — more like research.

3. **janitorial** — The session is maintenance work: renaming, reformatting, dependency updates, config changes, CI fixes. Lots of small edits across many files. Low cognitive load, high file count. The changes are mechanical rather than creative.

4. **debugging** — The session is dominated by a bug hunt. Characterized by cycles of: hypothesis → test → observe → adjust. Lots of Bash runs, error output in tool results, repeated edits to the same files. The developer is reacting to failures.

5. **review** — The session is primarily about reviewing code, reading diffs, or evaluating existing work. Mostly reading and reflection, with few or no edits. The developer is assessing rather than building.

Respond with ONLY a JSON object: { "shape": "<one of the five shapes>" }`;

  const user = `Here is a summary of the development session:

**Event counts:**
${Object.entries(input.eventCounts)
  .map(([type, count]) => `- ${type}: ${count}`)
  .join("\n")}

**Total events:** ${input.totalEvents}

**Files touched (${input.files.length} total):**
${input.files.slice(0, 30).join("\n")}${input.files.length > 30 ? `\n... and ${input.files.length - 30} more` : ""}

**Sample user messages:**
${input.sampleUserMessages
  .slice(0, 8)
  .map((msg, i) => `${i + 1}. ${msg}`)
  .join("\n")}

Classify this session. Return JSON only.`;

  return { system, user };
}

import { z } from "zod";
import type { NormalizedDevEvent, SessionChunk } from "../../adapters/types.js";
import type { SessionShape } from "./classify.js";

// ── Zod Schemas ──────────────────────────────────────────────────────

const MomentTypeSchema = z.enum([
  "proposal",
  "discovery",
  "pivot",
  "confirmation",
  "rejection",
  "commitment",
  "struggle",
  "breakthrough",
  "execution",
]);

const EvidenceSchema = z.object({
  quote: z.string(),
  sourceEventId: z.string().optional(),
  sourceType: z.enum(["user", "ai", "tool_output"]),
  quoteType: z.enum(["verbatim", "paraphrase"]),
});

const Pass1MomentSchema = z.object({
  type: MomentTypeSchema,
  statement: z.string(),
  significance: z.enum(["high", "medium", "low"]),
  agency: z.enum(["developer", "ai", "collaborative"]),
  confidence: z.enum(["high", "medium", "low"]),
  topicFingerprint: z.string(),
  evidence: z.array(EvidenceSchema).min(1),
});

export const Pass1OutputSchema = z.object({
  moments: z.array(Pass1MomentSchema),
});

const Pass2MomentSchema = Pass1MomentSchema.extend({
  arcId: z.string(),
  arcRole: z.enum(["origin", "development", "turning_point", "resolution"]),
  relatedMomentIds: z.array(z.number()),
});

export const Pass2OutputSchema = z.object({
  moments: z.array(Pass2MomentSchema),
});

export type Pass1Moment = z.infer<typeof Pass1MomentSchema>;
export type Pass1Output = z.infer<typeof Pass1OutputSchema>;
export type Pass2Moment = z.infer<typeof Pass2MomentSchema>;
export type Pass2Output = z.infer<typeof Pass2OutputSchema>;

// ── Pass 1: Per-Chunk Moment Detection ───────────────────────────────

export interface Pass1Input {
  chunk: SessionChunk;
  sessionShape: SessionShape;
}

export function buildPass1Prompt(input: Pass1Input): {
  system: string;
  user: string;
} {
  const { chunk, sessionShape } = input;

  const system = `You are an expert at identifying meaningful moments in developer coding sessions. You read a sequence of events from one chunk of a session and extract the moments that matter.

A "moment" is a point where something meaningful happened — a decision was made, an insight occurred, direction changed, or a commitment was established. NOT every event is a moment. You are looking for the inflection points.

## Moment Types

- **proposal** — Someone (developer or AI) suggests an approach, architecture, or solution. Use the proposer's actual words.
- **discovery** — New information surfaces that changes understanding. "Oh, this API doesn't support streaming" or "The tests are actually passing, it was a caching issue."
- **pivot** — Direction changes. The developer was doing X, now they're doing Y. Must cite what triggered the pivot.
- **confirmation** — A tentative approach becomes accepted. "Yeah, that looks right" or running tests that pass.
- **rejection** — An approach is explicitly rejected. "Actually let's not mock the database" or reverting a change.
- **commitment** — A firm decision that shapes subsequent work. Different from confirmation — this is choosing a path, not validating one.
- **struggle** — Repeated failed attempts, confusion, or difficulty. Cycles of edit-fail-edit on the same problem.
- **breakthrough** — A struggle resolves. The thing that wasn't working now works, or the confusion clears.
- **execution** — Sustained implementation of an already-decided approach. Only flag this for significant scope, not every edit.

## Rules

1. **Be specific, not generic.** "Developer rejected AI's suggestion to use a mock database, saying 'actually let's not mock the database, let's use testcontainers'" — not "a decision was made about testing."
2. **Use the developer's own language.** Quote them. If the AI proposed something and the developer accepted, say what the AI proposed AND how the developer responded.
3. **Every moment MUST have evidence.** At least one direct quote from the events.
4. **Distinguish agency clearly.** Who drove this moment? "developer" if they initiated it. "ai" if the AI proposed it and the developer just went along. "collaborative" if there was back-and-forth.
5. **topicFingerprint** should be a short, stable identifier for the topic area (e.g., "auth-middleware", "test-setup", "api-schema"). Use kebab-case. Two moments about the same topic should share a fingerprint.
6. **Fewer is better.** A chunk of 20 events might have 2-5 moments. Don't pad. If nothing meaningful happened, return an empty array.

${getShapeGuidance(sessionShape.shape)}

Respond with ONLY a JSON object: { "moments": [...] }`;

  const user = `## Session Shape: ${sessionShape.shape}
## Chunk ${chunk.chunkIndex} — Topic: ${chunk.topicHint}
## Files in scope: ${chunk.filesInScope.slice(0, 15).join(", ")}

## Events (${chunk.events.length} total):

${formatEvents(chunk.events)}

Extract the meaningful moments from this chunk. Return JSON only.`;

  return { system, user };
}

// ── Pass 2: Cross-Chunk Merge & Arc Assignment ───────────────────────

export interface Pass2Input {
  pass1Moments: { chunkIndex: number; moments: Pass1Moment[] }[];
  sessionShape: SessionShape;
  totalChunks: number;
}

export function buildPass2Prompt(input: Pass2Input): {
  system: string;
  user: string;
} {
  const { pass1Moments, sessionShape, totalChunks } = input;

  const system = `You are an expert at synthesizing developer session moments into coherent arcs. You receive moments detected across multiple chunks of a single session and must:

1. **Deduplicate** — If the same moment was detected in overlapping chunks, keep the best version (more specific statement, stronger evidence).
2. **Merge** — If two moments describe the same underlying event from different perspectives, merge them into one.
3. **Assign arcs** — Group related moments into narrative arcs. An arc is a thread of related activity (e.g., "setting up auth middleware" or "debugging the flaky test"). Give each arc a short kebab-case ID.
4. **Assign arc roles** — Within each arc, mark each moment's role:
   - **origin** — The moment that started this arc (first proposal, initial discovery)
   - **development** — Moments that advance the arc (execution, further proposals)
   - **turning_point** — Pivots, rejections, breakthroughs that change the arc's direction
   - **resolution** — The arc reaches a conclusion (commitment, final confirmation)
5. **Link related moments** — If moment N was caused by or responds to moment M, include M's index in relatedMomentIds. Use 0-based indices into YOUR output array.

## Rules

- Preserve the developer's own language in statements. Don't rewrite to be more "professional."
- If a moment from Pass 1 is low quality (vague statement, no real evidence), drop it.
- Don't invent moments that weren't in Pass 1. You can only merge, dedupe, enrich, or drop.
- An arc can have 1 moment (a standalone insight) or many (a full narrative thread).
- Total output moments should be <= total input moments.

Respond with ONLY a JSON object: { "moments": [...] }`;

  const user = `## Session Shape: ${sessionShape.shape}
## Total chunks: ${totalChunks}

## Pass 1 Moments by Chunk:

${pass1Moments
  .map(
    ({ chunkIndex, moments }) => `### Chunk ${chunkIndex} (${moments.length} moments):
${moments
  .map(
    (m, i) => `  ${i}. [${m.type}] ${m.statement}
     significance=${m.significance} agency=${m.agency} confidence=${m.confidence}
     topic=${m.topicFingerprint}
     evidence: ${m.evidence.map((e) => `"${e.quote.slice(0, 120)}"`).join("; ")}`,
  )
  .join("\n")}`,
  )
  .join("\n\n")}

Synthesize these into final moments with arc assignments. Return JSON only.`;

  return { system, user };
}

// ── Helpers ──────────────────────────────────────────────────────────

function getShapeGuidance(shape: string): string {
  switch (shape) {
    case "janitorial":
      return `## Shape-specific guidance (janitorial session)
Focus on SCOPE moments — what got included, what got excluded, any scope creep. In janitorial sessions, the interesting moments are:
- When the developer decided what to clean up (commitment)
- When they discovered unexpected issues during cleanup (discovery)
- When cleanup scope expanded or contracted (pivot)
- When mechanical work revealed a deeper problem (breakthrough/discovery)
Don't flag every rename or format change as a moment. Look for the decisions, not the keystrokes.`;

    case "exploratory":
      return `## Shape-specific guidance (exploratory session)
Focus on INSIGHT moments — what the developer learned, what changed their understanding. In exploratory sessions:
- Key discoveries about how code works or doesn't work
- Moments where investigation direction changed (pivot)
- "Aha" moments where confusion cleared (breakthrough)
- Decisions about what to investigate next (commitment)
Don't flag every file read as a moment. Look for what the developer understood differently after reading.`;

    case "debugging":
      return `## Shape-specific guidance (debugging session)
Focus on the HYPOTHESIS-TEST cycle. In debugging sessions:
- Initial hypothesis about the bug (proposal)
- Evidence that confirmed or rejected the hypothesis (confirmation/rejection)
- The actual root cause discovery (breakthrough)
- Failed attempts that narrowed the search (struggle → discovery)
Track the chain of reasoning, not every individual Bash run.`;

    case "narrative":
      return `## Shape-specific guidance (narrative session)
This session has a build arc. Focus on:
- The initial intent and how it evolved
- Key architectural decisions (commitment)
- Moments where the plan changed (pivot)
- AI proposals that were accepted vs rejected
- The progression from intent to working code`;

    case "review":
      return `## Shape-specific guidance (review session)
Focus on ASSESSMENT moments:
- Observations about code quality or correctness (discovery)
- Decisions about what to flag or change (commitment)
- Surprising findings (discovery/breakthrough)
Don't flag every file read. Look for judgments and insights.`;

    default:
      return "";
  }
}

function formatEvents(events: NormalizedDevEvent[]): string {
  return events
    .map((e) => {
      const actor = e.actor === "user" ? "DEV" : "AI";
      const category = e.category.toUpperCase();
      const files = e.content.filesAffected?.length
        ? ` [${e.content.filesAffected.join(", ")}]`
        : "";
      // Truncate detail to keep prompt within bounds
      const detail =
        e.content.detail.length > 400
          ? e.content.detail.slice(0, 400) + "..."
          : e.content.detail;
      return `[${e.causalOrder}] ${actor}/${category}${files}: ${detail}`;
    })
    .join("\n\n");
}

import { z } from "zod";
import type { Pass2Moment } from "./moments.js";
import type { SessionShape } from "./classify.js";

// ── Zod Schemas ──────────────────────────────────────────────────────

const IntentTransitionSchema = z.object({
  fromStatement: z.string(),
  toStatement: z.string(),
  reason: z.string(),
  triggeringMomentIndices: z.array(z.number()),
  arcId: z.string(),
  confidence: z.enum(["high", "medium", "low"]),
});

const AcceptedOutcomeSchema = z.object({
  statement: z.string(),
  supportingMomentIndices: z.array(z.number()),
  filesAffected: z.array(z.string()),
  confidence: z.enum(["high", "medium", "low"]),
});

export const TransitionsOutputSchema = z.object({
  transitions: z.array(IntentTransitionSchema),
  outcomes: z.array(AcceptedOutcomeSchema),
});

export type IntentTransition = z.infer<typeof IntentTransitionSchema>;
export type AcceptedOutcome = z.infer<typeof AcceptedOutcomeSchema>;
export type TransitionsOutput = z.infer<typeof TransitionsOutputSchema>;

// ── Prompt Input ─────────────────────────────────────────────────────

export interface TransitionsInput {
  moments: Pass2Moment[];
  sessionShape: SessionShape;
  filesInSession: string[];
}

// ── Prompt Builder ───────────────────────────────────────────────────

export function buildTransitionsPrompt(input: TransitionsInput): {
  system: string;
  user: string;
} {
  const { moments, sessionShape, filesInSession } = input;

  const system = `You are an expert at identifying intent transitions and accepted outcomes in developer coding sessions.

You receive the final set of moments from a session and must extract two things:

## 1. Intent Transitions

An intent transition is when the developer's working intent shifted. NOT every moment is a transition — only the points where what-the-developer-is-trying-to-do actually changed.

Examples:
- "Implement auth middleware" → "Debug auth middleware CORS issue" (triggered by a discovery that CORS headers were missing)
- "Add unit tests for parser" → "Refactor parser to be testable" (triggered by realizing the parser was too coupled)
- "Explore caching options" → "Implement Redis caching layer" (triggered by a commitment to use Redis)

Each transition must cite which moments triggered it (by index into the moments array).

Only flag genuine shifts. If the developer stayed focused on one thing the whole time, return an empty transitions array.

## 2. Accepted Outcomes

An accepted outcome is something the developer produced and accepted during the session. This is NOT just "files were edited" — it's "the developer reached a state they considered done (or at least good enough) for this piece."

Indicators of acceptance:
- Tests passing after implementation
- Developer explicitly saying "that looks good" or moving on to the next thing
- A commit being made
- No further edits to a file/feature after implementation

Each outcome should:
- State what was accomplished in the developer's terms
- List the specific files affected
- Reference supporting moments

If the session was purely exploratory with no concrete outputs, return an empty outcomes array.

Respond with ONLY a JSON object: { "transitions": [...], "outcomes": [...] }`;

  const user = `## Session Shape: ${sessionShape.shape}

## Moments (${moments.length} total):

${moments
  .map(
    (m, i) => `${i}. [${m.type}] (arc: ${m.arcId}, role: ${m.arcRole}) ${m.statement}
   agency=${m.agency} confidence=${m.confidence}
   topic=${m.topicFingerprint}
   evidence: ${m.evidence.map((e) => `"${e.quote.slice(0, 100)}"`).join("; ")}`,
  )
  .join("\n\n")}

## Files touched in session (${filesInSession.length} total):
${filesInSession.slice(0, 40).join("\n")}${filesInSession.length > 40 ? `\n... and ${filesInSession.length - 40} more` : ""}

Identify intent transitions and accepted outcomes. Return JSON only.`;

  return { system, user };
}

import { z } from "zod";
import type { Pass2Moment } from "./moments.js";
import type { IntentTransition, AcceptedOutcome } from "./transitions.js";
import type { SessionShape } from "./classify.js";

// ── Zod Schemas ──────────────────────────────────────────────────────

const NarrativeArcSchema = z.object({
  arcId: z.string(),
  title: z.string(),
  summary: z.string(),
  resolution: z.enum(["completed", "abandoned", "ongoing", "merged"]),
  momentIds: z.array(z.number()),
});

export const SessionNarrativeSchema = z.object({
  sessionShape: z.string(),
  summary: z.string(),
  arcs: z.array(NarrativeArcSchema),
  progression: z.array(z.string()),
  discoveries: z.array(z.string()),
  stabilizedDirections: z.array(z.string()),
  abandonedDirections: z.array(z.string()),
});

export type NarrativeArc = z.infer<typeof NarrativeArcSchema>;
export type SessionNarrative = z.infer<typeof SessionNarrativeSchema>;

// ── Prompt Input ─────────────────────────────────────────────────────

export interface NarrativeInput {
  moments: Pass2Moment[];
  transitions: IntentTransition[];
  outcomes: AcceptedOutcome[];
  sessionShape: SessionShape;
}

// ── Prompt Builder ───────────────────────────────────────────────────

export function buildNarrativePrompt(input: NarrativeInput): {
  system: string;
  user: string;
} {
  const { moments, transitions, outcomes, sessionShape } = input;

  const system = `You are a technical narrator for developer coding sessions. You synthesize moments, transitions, and outcomes into a concise narrative that captures what actually happened.

## Tone

- **Observational** — You report what happened, not what should have happened. You're a historian, not a coach.
- **Evidence-backed** — Every claim maps to specific moments. Don't editorialize.
- **Developer's language** — Use the same terms the developer used. If they called it "the auth thing," don't upgrade it to "authentication module."
- **Never recommend** — Don't say "consider using X" or "it might be better to Y." You are recording, not advising.

## What to produce

### summary
A 2-4 sentence narrative of the session. What did the developer set out to do? What actually happened? How did it end? Use past tense.

### arcs
Each narrative arc represents a coherent thread of activity. Give each arc:
- **title** — Short, descriptive, in the developer's language
- **summary** — 1-2 sentences about what happened in this arc
- **resolution** — "completed" (the arc reached its goal), "abandoned" (developer gave up or moved on), "ongoing" (still in progress when session ended), "merged" (got absorbed into another arc)
- **momentIds** — Indices into the moments array that belong to this arc

### progression
An ordered list of 3-8 statements describing how the session unfolded chronologically. Each statement should be a single sentence. Think of this as a timeline.

### discoveries
Key things the developer learned or uncovered during the session. Only include genuine insights, not trivial observations. Can be empty.

### stabilizedDirections
Decisions or approaches that became established during this session — things that started uncertain but are now settled. Can be empty.

### abandonedDirections
Approaches that were tried and rejected, or directions that were considered but not pursued. Can be empty.

Respond with ONLY a JSON object matching the schema above.`;

  const user = `## Session Shape: ${sessionShape.shape}

## Moments (${moments.length}):
${moments
  .map(
    (m, i) => `${i}. [${m.type}] (arc: ${m.arcId}, ${m.arcRole}) ${m.statement}`,
  )
  .join("\n")}

## Intent Transitions (${transitions.length}):
${transitions.length === 0 ? "(none — developer maintained consistent intent)" : transitions
  .map(
    (t, i) => `${i}. "${t.fromStatement}" → "${t.toStatement}"
   reason: ${t.reason} (arc: ${t.arcId})`,
  )
  .join("\n")}

## Accepted Outcomes (${outcomes.length}):
${outcomes.length === 0 ? "(none — session was exploratory or incomplete)" : outcomes
  .map(
    (o, i) => `${i}. ${o.statement}
   files: ${o.filesAffected.slice(0, 10).join(", ")}`,
  )
  .join("\n")}

Generate the session narrative. Return JSON only.`;

  return { system, user };
}

