 55→// ── Pass 1: Per-Chunk Moment Detection ───────────────────────────────
 56→
 57→export interface Pass1Input {
 58→  chunk: SessionChunk;
 59→  sessionShape: SessionShape;
 60→}
 61→
 62→export function buildPass1Prompt(input: Pass1Input): {
 63→  system: string;
 64→  user: string;
 65→} {
 66→  const { chunk, sessionShape } = input;
 67→
 68→  const system = `You are an expert at identifying meaningful moments in developer coding sessions. You read a sequence of events from one chunk of a session and extract the moments that matter.
 69→
 70→A "moment" is a point where something meaningful happened — a decision was made, an insight occurred, direction changed, or a commitment was established. NOT every event is a moment. You are looking for the inflection points.
 71→
 72→## Moment Types
 73→
 74→- **proposal** — Someone (developer or AI) suggests an approach, architecture, or solution. Use the proposer's actual words.
 75→- **discovery** — New information surfaces that changes understanding. "Oh, this API doesn't support streaming" or "The tests are actually passing, it was a caching issue."
 76→- **pivot** — Direction changes. The developer was doing X, now they're doing Y. Must cite what triggered the pivot.
 77→- **confirmation** — A tentative approach becomes accepted. "Yeah, that looks right" or running tests that pass.
 78→- **rejection** — An approach is explicitly rejected. "Actually let's not mock the database" or reverting a change.
 79→- **commitment** — A firm decision that shapes subsequent work. Different from confirmation — this is choosing a path, not validating one.
 80→- **struggle** — Repeated failed attempts, confusion, or difficulty. Cycles of edit-fail-edit on the same problem.
 81→- **breakthrough** — A struggle resolves. The thing that wasn't working now works, or the confusion clears.
 82→- **execution** — Sustained implementation of an already-decided approach. Only flag this for significant scope, not every edit.
 83→
 84→## Rules
 85→
 86→1. **Be specific, not generic.** "Developer rejected AI's suggestion to use a mock database, saying 'actually let's not mock the database, let's use testcontainers'" — not "a decision was made about testing."
 87→2. **Use the developer's own language.** Quote them. If the AI proposed something and the developer accepted, say what the AI proposed AND how the developer responded.
 88→3. **Every moment MUST have evidence.** At least one direct quote from the events.
 89→4. **Distinguish agency clearly.** Who drove this moment? "developer" if they initiated it. "ai" if the AI proposed it and the developer just went along. "collaborative" if there was back-and-forth.
 90→5. **topicFingerprint** should be a short, stable identifier for the topic area (e.g., "auth-middleware", "test-setup", "api-schema"). Use kebab-case. Two moments about the same topic should share a fingerprint.
 91→6. **Fewer is better.** A chunk of 20 events might have 2-5 moments. Don't pad. If nothing meaningful happened, return an empty array.
 92→
 93→${getShapeGuidance(sessionShape.shape)}
 94→
 95→Respond with ONLY a JSON object: { "moments": [...] }`;
 96→
 97→  const user = `## Session Shape: ${sessionShape.shape}
 98→## Chunk ${chunk.chunkIndex} — Topic: ${chunk.topicHint}
 99→## Files in scope: ${chunk.filesInScope.slice(0, 15).join(", ")}
100→
101→## Events (${chunk.events.length} total):
102→
103→${formatEvents(chunk.events)}
104→
105→Extract the meaningful moments from this chunk. Return JSON only.`;
106→
107→  return { system, user };
108→}
