110→// ── Pass 2: Cross-Chunk Merge & Arc Assignment ───────────────────────
111→
112→export interface Pass2Input {
113→  pass1Moments: { chunkIndex: number; moments: Pass1Moment[] }[];
114→  sessionShape: SessionShape;
115→  totalChunks: number;
116→}
117→
118→export function buildPass2Prompt(input: Pass2Input): {
119→  system: string;
120→  user: string;
121→} {
122→  const { pass1Moments, sessionShape, totalChunks } = input;
123→
124→  const system = `You are an expert at synthesizing developer session moments into coherent arcs. You receive moments detected across multiple chunks of a single session and must:
125→
126→1. **Deduplicate** — If the same moment was detected in overlapping chunks, keep the best version (more specific statement, stronger evidence).
127→2. **Merge** — If two moments describe the same underlying event from different perspectives, merge them into one.
128→3. **Assign arcs** — Group related moments into narrative arcs. An arc is a thread of related activity (e.g., "setting up auth middleware" or "debugging the flaky test"). Give each arc a short kebab-case ID.
129→4. **Assign arc roles** — Within each arc, mark each moment's role:
130→   - **origin** — The moment that started this arc (first proposal, initial discovery)
131→   - **development** — Moments that advance the arc (execution, further proposals)
132→   - **turning_point** — Pivots, rejections, breakthroughs that change the arc's direction
133→   - **resolution** — The arc reaches a conclusion (commitment, final confirmation)
134→5. **Link related moments** — If moment N was caused by or responds to moment M, include M's index in relatedMomentIds. Use 0-based indices into YOUR output array.
135→
136→## Rules
137→
138→- Preserve the developer's own language in statements. Don't rewrite to be more "professional."
139→- If a moment from Pass 1 is low quality (vague statement, no real evidence), drop it.
140→- Don't invent moments that weren't in Pass 1. You can only merge, dedupe, enrich, or drop.
141→- An arc can have 1 moment (a standalone insight) or many (a full narrative thread).
142→- Total output moments should be <= total input moments.
143→
144→Respond with ONLY a JSON object: { "moments": [...] }`;
145→
146→  const user = `## Session Shape: ${sessionShape.shape}
147→## Total chunks: ${totalChunks}
148→
149→## Pass 1 Moments by Chunk:
150→
151→${pass1Moments
152→  .map(
153→    ({ chunkIndex, moments }) => `### Chunk ${chunkIndex} (${moments.length} moments):
154→${moments
155→  .map(
156→    (m, i) => `  ${i}. [${m.type}] ${m.statement}
157→     significance=${m.significance} agency=${m.agency} confidence=${m.confidence}
158→     topic=${m.topicFingerprint}
159→     evidence: ${m.evidence.map((e) => `"${e.quote.slice(0, 120)}"`).join("; ")}`,
160→  )
161→  .join("\n")}`,
162→  )
163→  .join("\n\n")}
164→
165→Synthesize these into final moments with arc assignments. Return JSON only.`;
166→
167→  return { system, user };
168→}
