170→// ── Helpers ──────────────────────────────────────────────────────────
171→
172→function getShapeGuidance(shape: string): string {
173→  switch (shape) {
174→    case "janitorial":
175→      return `## Shape-specific guidance (janitorial session)
176→Focus on SCOPE moments — what got included, what got excluded, any scope creep. In janitorial sessions, the interesting moments are:
177→- When the developer decided what to clean up (commitment)
178→- When they discovered unexpected issues during cleanup (discovery)
179→- When cleanup scope expanded or contracted (pivot)
180→- When mechanical work revealed a deeper problem (breakthrough/discovery)
181→Don't flag every rename or format change as a moment. Look for the decisions, not the keystrokes.`;
182→
183→    case "exploratory":
184→      return `## Shape-specific guidance (exploratory session)
185→Focus on INSIGHT moments — what the developer learned, what changed their understanding. In exploratory sessions:
186→- Key discoveries about how code works or doesn't work
187→- Moments where investigation direction changed (pivot)
188→- "Aha" moments where confusion cleared (breakthrough)
189→- Decisions about what to investigate next (commitment)
190→Don't flag every file read as a moment. Look for what the developer understood differently after reading.`;
191→
192→    case "debugging":
193→      return `## Shape-specific guidance (debugging session)
194→Focus on the HYPOTHESIS-TEST cycle. In debugging sessions:
195→- Initial hypothesis about the bug (proposal)
196→- Evidence that confirmed or rejected the hypothesis (confirmation/rejection)
197→- The actual root cause discovery (breakthrough)
198→- Failed attempts that narrowed the search (struggle → discovery)
199→Track the chain of reasoning, not every individual Bash run.`;
200→
201→    case "narrative":
202→      return `## Shape-specific guidance (narrative session)
203→This session has a build arc. Focus on:
204→- The initial intent and how it evolved
205→- Key architectural decisions (commitment)
206→- Moments where the plan changed (pivot)
207→- AI proposals that were accepted vs rejected
208→- The progression from intent to working code`;
209→
210→    case "review":
211→      return `## Shape-specific guidance (review session)
212→Focus on ASSESSMENT moments:
213→- Observations about code quality or correctness (discovery)
214→- Decisions about what to flag or change (commitment)
215→- Surprising findings (discovery/breakthrough)
216→Don't flag every file read. Look for judgments and insights.`;
217→
218→    default:
219→      return "";
220→  }
221→}
222→
223→function formatEvents(events: NormalizedDevEvent[]): string {
224→  return events
225→    .map((e) => {
226→      const actor = e.actor === "user" ? "DEV" : "AI";
227→      const category = e.category.toUpperCase();
228→      const files = e.content.filesAffected?.length
229→        ? ` [${e.content.filesAffected.join(", ")}]`
230→        : "";
231→      // Truncate detail to keep prompt within bounds
232→      const detail =
233→        e.content.detail.length > 400
234→          ? e.content.detail.slice(0, 400) + "..."
235→          : e.content.detail;
236→      return `[${e.causalOrder}] ${actor}/${category}${files}: ${detail}`;
237→    })
238→    .join("\n\n");
239→}
