import type { NormalizedDevEvent } from "../adapters/types.js";
import type { SessionShape } from "../adapters/types.js";
import { callHaiku } from "../llm/client.js";
import {
  buildClassifyPrompt,
  SessionShapeSchema,
  type ClassifyInput,
} from "../llm/prompts/classify.js";

// Re-export for convenience
export type { SessionShape };

/**
 * Classify a session's overall shape using Haiku.
 *
 * Builds a lightweight summary of the event stream and asks Haiku
 * to pick one of the five canonical session shapes.
 */
export async function classifySession(
  events: NormalizedDevEvent[],
): Promise<SessionShape> {
  const summary = buildSummary(events);
  const { system, user } = buildClassifyPrompt(summary);
  const result = await callHaiku(system, user, SessionShapeSchema);
  return result.shape as SessionShape;
}

// ── Internal ──────────────────────────────────────────────────────────

function buildSummary(events: NormalizedDevEvent[]): ClassifyInput {
  // Count events by category
  const eventCounts: Record<string, number> = {};
  for (const e of events) {
    eventCounts[e.category] = (eventCounts[e.category] ?? 0) + 1;
  }

  // Count by actor
  for (const e of events) {
    const key = `actor:${e.actor}`;
    eventCounts[key] = (eventCounts[key] ?? 0) + 1;
  }

  // Unique files touched
  const filesSet = new Set<string>();
  for (const e of events) {
    if (e.content.filesAffected) {
      for (const f of e.content.filesAffected) {
        filesSet.add(f);
      }
    }
  }

  // Sample of first 3 user messages, truncated to 200 chars
  const userMessages: string[] = [];
  for (const e of events) {
    if (e.actor === "user" && e.category === "intent") {
      userMessages.push(e.content.summary.slice(0, 200));
      if (userMessages.length >= 3) break;
    }
  }

  return {
    eventCounts,
    files: Array.from(filesSet),
    sampleUserMessages: userMessages,
    totalEvents: events.length,
  };
}

import type { SessionChunk } from "../adapters/types.js";
import type { SessionShape, SessionMoment } from "../adapters/types.js";
import { callSonnet } from "../llm/client.js";
import {
  buildPass1Prompt,
  buildPass2Prompt,
  Pass1OutputSchema,
  Pass2OutputSchema,
  type Pass1Moment,
  type Pass2Moment,
} from "../llm/prompts/moments.js";
import type { SessionShape as PromptSessionShape } from "../llm/prompts/classify.js";

/**
 * Two-pass moment detection across session chunks.
 *
 * Pass 1: Extract candidate moments from each chunk in parallel (Sonnet).
 * Pass 2: Merge, deduplicate, and assign arcs across all candidates (Sonnet).
 */
export async function detectMoments(
  chunks: SessionChunk[],
  sessionShape: SessionShape,
): Promise<SessionMoment[]> {
  const shapeObj: PromptSessionShape = { shape: sessionShape };

  // ── Pass 1: per-chunk extraction in parallel ───────────────────────
  const pass1Results = await Promise.all(
    chunks.map(async (chunk) => {
      const { system, user } = buildPass1Prompt({
        chunk,
        sessionShape: shapeObj,
      });
      const result = await callSonnet(system, user, Pass1OutputSchema);
      return { chunkIndex: chunk.chunkIndex, moments: result.moments };
    }),
  );

  // ── Pass 2: cross-chunk merge & arc assignment ─────────────────────
  const { system, user } = buildPass2Prompt({
    pass1Moments: pass1Results,
    sessionShape: shapeObj,
    totalChunks: chunks.length,
  });
  const pass2Result = await callSonnet(system, user, Pass2OutputSchema);

  // Convert Pass2Moment[] → SessionMoment[]
  return pass2Result.moments.map((m, i) => toSessionMoment(m, i, chunks));
}

// ── Internal ──────────────────────────────────────────────────────────

function toSessionMoment(
  m: Pass2Moment,
  index: number,
  chunks: SessionChunk[],
): SessionMoment {
  // Use first chunk's id as a fallback chunkId
  const chunkId = chunks[0]?.id ?? "unknown";

  return {
    id: `moment-${index}`,
    chunkId,
    type: m.type,
    statement: m.statement,
    significance: m.significance,
    agency: m.agency === "collaborative" ? "collaborative" : m.agency,
    confidence: m.confidence,
    topicFingerprint: m.topicFingerprint,
    relatedMomentIds: m.relatedMomentIds.map((id) => `moment-${id}`),
    arcId: m.arcId,
    arcRole: mapArcRole(m.arcRole),
    evidence: m.evidence.map((e) => ({
      quote: e.quote,
      sourceEventId: e.sourceEventId ?? "",
      sourceType: mapSourceType(e.sourceType),
      quoteType: e.quoteType === "verbatim" ? "verbatim" : "summarized",
    })),
  };
}

function mapArcRole(
  role: string,
): "origin" | "escalation" | "turning_point" | "resolution" {
  switch (role) {
    case "origin":
      return "origin";
    case "turning_point":
      return "turning_point";
    case "resolution":
      return "resolution";
    default:
      return "escalation";
  }
}

function mapSourceType(
  st: string,
): "human_message" | "ai_message" | "tool_output" | "tool_input" {
  switch (st) {
    case "user":
      return "human_message";
    case "ai":
      return "ai_message";
    case "tool_output":
      return "tool_output";
    default:
      return "tool_input";
  }
}

import type {
  SessionMoment,
  IntentTransition,
  AcceptedOutcome,
} from "../adapters/types.js";
import { callSonnet } from "../llm/client.js";
import {
  buildTransitionsPrompt,
  TransitionsOutputSchema,
} from "../llm/prompts/transitions.js";
import type { Pass2Moment } from "../llm/prompts/moments.js";
import type { SessionShape as PromptSessionShape } from "../llm/prompts/classify.js";

/**
 * Detect intent transitions and accepted outcomes from session moments.
 */
export async function detectTransitionsAndOutcomes(
  moments: SessionMoment[],
  sessionId: string,
): Promise<{ transitions: IntentTransition[]; outcomes: AcceptedOutcome[] }> {
  // Convert SessionMoment[] to Pass2Moment[] for the prompt builder
  const pass2Moments: Pass2Moment[] = moments.map((m) => ({
    type: m.type,
    statement: m.statement,
    significance: m.significance as "high" | "medium" | "low",
    agency: mapAgency(m.agency),
    confidence: m.confidence,
    topicFingerprint: m.topicFingerprint,
    evidence: m.evidence.map((e) => ({
      quote: e.quote,
      sourceEventId: e.sourceEventId || undefined,
      sourceType: mapSourceTypeBack(e.sourceType),
      quoteType: e.quoteType === "verbatim" ? ("verbatim" as const) : ("paraphrase" as const),
    })),
    arcId: m.arcId ?? "",
    arcRole: mapArcRoleBack(m.arcRole),
    relatedMomentIds: m.relatedMomentIds.map((id) => {
      const num = parseInt(id.replace("moment-", ""), 10);
      return isNaN(num) ? 0 : num;
    }),
  }));

  // Collect all files from moments' evidence
  const filesInSession = collectFiles(moments);

  const shapeObj: PromptSessionShape = { shape: "narrative" }; // default; shape not needed for transitions
  const { system, user } = buildTransitionsPrompt({
    moments: pass2Moments,
    sessionShape: shapeObj,
    filesInSession,
  });

  const result = await callSonnet(system, user, TransitionsOutputSchema);

  // Map LLM output to our domain types
  const transitions: IntentTransition[] = result.transitions.map((t, i) => ({
    id: `transition-${i}`,
    sessionId,
    fromStatement: t.fromStatement,
    toStatement: t.toStatement,
    reason: t.reason,
    originMomentIds: t.triggeringMomentIndices.map((idx) => `moment-${idx}`),
    arcId: t.arcId,
    confidence: t.confidence,
  }));

  const outcomes: AcceptedOutcome[] = result.outcomes.map((o, i) => ({
    id: `outcome-${i}`,
    sessionId,
    statement: o.statement,
    supportingMomentIds: o.supportingMomentIndices.map(
      (idx) => `moment-${idx}`,
    ),
    supportingFiles: o.filesAffected,
    confidence: o.confidence,
  }));

  return { transitions, outcomes };
}

// ── Helpers ──────────────────────────────────────────────────────────

function collectFiles(moments: SessionMoment[]): string[] {
  const files = new Set<string>();
  for (const m of moments) {
    // topicFingerprint might hint at files, but we'll use evidence sourceEventIds
    // In practice, files come from the chunks — for now return empty
  }
  return Array.from(files);
}

function mapAgency(
  agency: string,
): "developer" | "ai" | "collaborative" {
  if (agency === "developer" || agency === "ai" || agency === "collaborative") {
    return agency;
  }
  return "collaborative";
}

function mapSourceTypeBack(
  st: string,
): "user" | "ai" | "tool_output" {
  switch (st) {
    case "human_message":
      return "user";
    case "ai_message":
      return "ai";
    case "tool_output":
      return "tool_output";
    default:
      return "user";
  }
}

function mapArcRoleBack(
  role?: string,
): "origin" | "development" | "turning_point" | "resolution" {
  switch (role) {
    case "origin":
      return "origin";
    case "turning_point":
      return "turning_point";
    case "resolution":
      return "resolution";
    default:
      return "development";
  }
}

import type {
  SessionMoment,
  IntentTransition,
  AcceptedOutcome,
  SessionShape,
  SessionNarrative,
} from "../adapters/types.js";
import { callSonnet } from "../llm/client.js";
import {
  buildNarrativePrompt,
  SessionNarrativeSchema,
} from "../llm/prompts/narrative.js";
import type { Pass2Moment } from "../llm/prompts/moments.js";
import type { SessionShape as PromptSessionShape } from "../llm/prompts/classify.js";
import type {
  IntentTransition as PromptTransition,
  AcceptedOutcome as PromptOutcome,
} from "../llm/prompts/transitions.js";

/**
 * Generate a narrative summary of a session from its moments,
 * transitions, and outcomes.
 */
export async function generateNarrative(
  moments: SessionMoment[],
  transitions: IntentTransition[],
  outcomes: AcceptedOutcome[],
  sessionShape: SessionShape,
): Promise<SessionNarrative> {
  const shapeObj: PromptSessionShape = { shape: sessionShape };

  // Convert domain types to prompt types
  const pass2Moments: Pass2Moment[] = moments.map((m) => ({
    type: m.type,
    statement: m.statement,
    significance: m.significance as "high" | "medium" | "low",
    agency: mapAgency(m.agency),
    confidence: m.confidence,
    topicFingerprint: m.topicFingerprint,
    evidence: m.evidence.map((e) => ({
      quote: e.quote,
      sourceEventId: e.sourceEventId || undefined,
      sourceType: mapSourceTypeBack(e.sourceType),
      quoteType: e.quoteType === "verbatim" ? ("verbatim" as const) : ("paraphrase" as const),
    })),
    arcId: m.arcId ?? "",
    arcRole: mapArcRoleBack(m.arcRole),
    relatedMomentIds: m.relatedMomentIds.map((id) => {
      const num = parseInt(id.replace("moment-", ""), 10);
      return isNaN(num) ? 0 : num;
    }),
  }));

  const promptTransitions: PromptTransition[] = transitions.map((t) => ({
    fromStatement: t.fromStatement,
    toStatement: t.toStatement,
    reason: t.reason,
    triggeringMomentIndices: t.originMomentIds.map((id) => {
      const num = parseInt(id.replace("moment-", ""), 10);
      return isNaN(num) ? 0 : num;
    }),
    arcId: t.arcId ?? "",
    confidence: t.confidence,
  }));

  const promptOutcomes: PromptOutcome[] = outcomes.map((o) => ({
    statement: o.statement,
    supportingMomentIndices: o.supportingMomentIds.map((id) => {
      const num = parseInt(id.replace("moment-", ""), 10);
      return isNaN(num) ? 0 : num;
    }),
    filesAffected: o.supportingFiles,
    confidence: o.confidence,
  }));

  const { system, user } = buildNarrativePrompt({
    moments: pass2Moments,
    transitions: promptTransitions,
    outcomes: promptOutcomes,
    sessionShape: shapeObj,
  });

  const result = await callSonnet(system, user, SessionNarrativeSchema);

  return {
    sessionId: "", // Caller should set this
    sessionShape,
    summary: result.summary,
    progression: result.progression,
    discoveries: result.discoveries,
    stabilizedDirections: result.stabilizedDirections,
    abandonedDirections: result.abandonedDirections,
    arcs: result.arcs.map((arc) => ({
      arcId: arc.arcId,
      title: arc.title,
      summary: arc.summary,
      momentIds: arc.momentIds.map((idx) => `moment-${idx}`),
      resolution: mapResolution(arc.resolution),
    })),
  };
}

// ── Helpers ──────────────────────────────────────────────────────────

function mapAgency(
  agency: string,
): "developer" | "ai" | "collaborative" {
  if (agency === "developer" || agency === "ai" || agency === "collaborative") {
    return agency;
  }
  return "collaborative";
}

function mapSourceTypeBack(
  st: string,
): "user" | "ai" | "tool_output" {
  switch (st) {
    case "human_message":
      return "user";
    case "ai_message":
      return "ai";
    case "tool_output":
      return "tool_output";
    default:
      return "user";
  }
}

function mapArcRoleBack(
  role?: string,
): "origin" | "development" | "turning_point" | "resolution" {
  switch (role) {
    case "origin":
      return "origin";
    case "turning_point":
      return "turning_point";
    case "resolution":
      return "resolution";
    default:
      return "development";
  }
}

function mapResolution(
  res: string,
): "resolved" | "abandoned" | "open" {
  switch (res) {
    case "completed":
      return "resolved";
    case "abandoned":
      return "abandoned";
    case "ongoing":
      return "open";
    case "merged":
      return "resolved";
    default:
      return "open";
  }
}

import { describe, it, expect, vi, beforeEach } from "vitest";
