 13→import type { Pass2Moment } from "../llm/prompts/moments.js";
 14→import type { SessionShape as PromptSessionShape } from "../llm/prompts/classify.js";
 15→import type {
 16→  IntentTransition as PromptTransition,
 17→  AcceptedOutcome as PromptOutcome,
 18→} from "../llm/prompts/transitions.js";
 19→
 20→/**
 21→ * Generate a narrative summary of a session from its moments,
 22→ * transitions, and outcomes.
 23→ */
 24→export async function generateNarrative(
 25→  moments: SessionMoment[],
 26→  transitions: IntentTransition[],
 27→  outcomes: AcceptedOutcome[],
 28→  sessionShape: SessionShape,
 29→): Promise<SessionNarrative> {
 30→  const shapeObj: PromptSessionShape = { shape: sessionShape };
 31→
 32→  // Convert domain types to prompt types
 33→  const pass2Moments: Pass2Moment[] = moments.map((m) => ({
 34→    type: m.type,
 35→    statement: m.statement,
 36→    significance: m.significance as "high" | "medium" | "low",
 37→    agency: mapAgency(m.agency),
 38→    confidence: m.confidence,
 39→    topicFingerprint: m.topicFingerprint,
 40→    evidence: m.evidence.map((e) => ({
 41→      quote: e.quote,
 42→      sourceEventId: e.sourceEventId || undefined,
 43→      sourceType: mapSourceTypeBack(e.sourceType),
 44→      quoteType: e.quoteType === "verbatim" ? ("verbatim" as const) : ("paraphrase" as const),
 45→    })),
 46→    arcId: m.arcId ?? "",
 47→    arcRole: mapArcRoleBack(m.arcRole),
 48→    relatedMomentIds: m.relatedMomentIds.map((id) => {
 49→      const num = parseInt(id.replace("moment-", ""), 10);
 50→      return isNaN(num) ? 0 : num;
 51→    }),
 52→  }));
 53→
 54→  const promptTransitions: PromptTransition[] = transitions.map((t) => ({
 55→    fromStatement: t.fromStatement,
 56→    toStatement: t.toStatement,
 57→    reason: t.reason,
 58→    triggeringMomentIndices: t.originMomentIds.map((id) => {
 59→      const num = parseInt(id.replace("moment-", ""), 10);
 60→      return isNaN(num) ? 0 : num;
 61→    }),
 62→    arcId: t.arcId ?? "",
 63→    confidence: t.confidence,
 64→  }));
 65→
 66→  const promptOutcomes: PromptOutcome[] = outcomes.map((o) => ({
 67→    statement: o.statement,
 68→    supportingMomentIndices: o.supportingMomentIds.map((id) => {
 69→      const num = parseInt(id.replace("moment-", ""), 10);
 70→      return isNaN(num) ? 0 : num;
 71→    }),
 72→    filesAffected: o.supportingFiles,
 73→    confidence: o.confidence,
 74→  }));
 75→
 76→  const { system, user } = buildNarrativePrompt({
 77→    moments: pass2Moments,
 78→    transitions: promptTransitions,
 79→    outcomes: promptOutcomes,
 80→    sessionShape: shapeObj,
 81→  });
 82→
 83→  const result = await callSonnet(system, user, SessionNarrativeSchema);
 84→
 85→  return {
 86→    sessionId: "", // Caller should set this
 87→    sessionShape,
 88→    summary: result.summary,
 89→    progression: result.progression,
 90→    discoveries: result.discoveries,
 91→    stabilizedDirections: result.stabilizedDirections,
 92→    abandonedDirections: result.abandonedDirections,
 93→    arcs: result.arcs.map((arc) => ({
 94→      arcId: arc.arcId,
 95→      title: arc.title,
 96→      summary: arc.summary,
 97→      momentIds: arc.momentIds.map((idx) => `moment-${idx}`),
 98→      resolution: mapResolution(arc.resolution),
 99→    })),
100→  };
101→}
102→
103→// ── Helpers ──────────────────────────────────────────────────────────
104→
105→function mapAgency(
106→  agency: string,
107→): "developer" | "ai" | "collaborative" {
108→  if (agency === "developer" || agency === "ai" || agency === "collaborative") {
109→    return agency;
110→  }
111→  return "collaborative";
112→}
113→
114→function mapSourceTypeBack(
115→  st: string,
116→): "user" | "ai" | "tool_output" {
117→  switch (st) {
118→    case "human_message":
119→      return "user";
120→    case "ai_message":
121→      return "ai";
122→    case "tool_output":
123→      return "tool_output";
124→    default:
125→      return "user";
126→  }
127→}
128→
129→function mapArcRoleBack(
130→  role?: string,
131→): "origin" | "development" | "turning_point" | "resolution" {
132→  switch (role) {
133→    case "origin":
134→      return "origin";
135→    case "turning_point":
136→      return "turning_point";
137→    case "resolution":
138→      return "resolution";
139→    default:
140→      return "development";
141→  }
142→}
143→
144→function mapResolution(
145→  res: string,
146→): "resolved" | "abandoned" | "open" {
147→  switch (res) {
148→    case "completed":
149→      return "resolved";
150→    case "abandoned":
151→      return "abandoned";
152→    case "ongoing":
153→      return "open";
154→    case "merged":
155→      return "resolved";
156→    default:
157→      return "open";
158→  }
159→}
