 14→/**
 15→ * Detect intent transitions and accepted outcomes from session moments.
 16→ */
 17→export async function detectTransitionsAndOutcomes(
 18→  moments: SessionMoment[],
 19→  sessionId: string,
 20→): Promise<{ transitions: IntentTransition[]; outcomes: AcceptedOutcome[] }> {
 21→  // Convert SessionMoment[] to Pass2Moment[] for the prompt builder
 22→  const pass2Moments: Pass2Moment[] = moments.map((m) => ({
 23→    type: m.type,
 24→    statement: m.statement,
 25→    significance: m.significance as "high" | "medium" | "low",
 26→    agency: mapAgency(m.agency),
 27→    confidence: m.confidence,
 28→    topicFingerprint: m.topicFingerprint,
 29→    evidence: m.evidence.map((e) => ({
 30→      quote: e.quote,
 31→      sourceEventId: e.sourceEventId || undefined,
 32→      sourceType: mapSourceTypeBack(e.sourceType),
 33→      quoteType: e.quoteType === "verbatim" ? ("verbatim" as const) : ("paraphrase" as const),
 34→    })),
 35→    arcId: m.arcId ?? "",
 36→    arcRole: mapArcRoleBack(m.arcRole),
 37→    relatedMomentIds: m.relatedMomentIds.map((id) => {
 38→      const num = parseInt(id.replace("moment-", ""), 10);
 39→      return isNaN(num) ? 0 : num;
 40→    }),
 41→  }));
 42→
 43→  // Collect all files from moments' evidence
 44→  const filesInSession = collectFiles(moments);
 45→
 46→  const shapeObj: PromptSessionShape = { shape: "narrative" }; // default; shape not needed for transitions
 47→  const { system, user } = buildTransitionsPrompt({
 48→    moments: pass2Moments,
 49→    sessionShape: shapeObj,
 50→    filesInSession,
 51→  });
 52→
 53→  const result = await callSonnet(system, user, TransitionsOutputSchema);
 54→
 55→  // Map LLM output to our domain types
 56→  const transitions: IntentTransition[] = result.transitions.map((t, i) => ({
 57→    id: `transition-${i}`,
 58→    sessionId,
 59→    fromStatement: t.fromStatement,
 60→    toStatement: t.toStatement,
 61→    reason: t.reason,
 62→    originMomentIds: t.triggeringMomentIndices.map((idx) => `moment-${idx}`),
 63→    arcId: t.arcId,
 64→    confidence: t.confidence,
 65→  }));
 66→
 67→  const outcomes: AcceptedOutcome[] = result.outcomes.map((o, i) => ({
 68→    id: `outcome-${i}`,
 69→    sessionId,
 70→    statement: o.statement,
 71→    supportingMomentIds: o.supportingMomentIndices.map(
 72→      (idx) => `moment-${idx}`,
 73→    ),
 74→    supportingFiles: o.filesAffected,
 75→    confidence: o.confidence,
 76→  }));
 77→
 78→  return { transitions, outcomes };
 79→}
