  1→import type { NormalizedDevEvent, SessionChunk } from "../adapters/types.js";
  2→
  3→// ── Constants ────────────────────────────────────────────────────────
  4→
  5→const PAUSE_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes
  6→const FILE_SHIFT_THRESHOLD = 0.7; // 70% new files
  7→const MIN_PREVIOUS_FILES = 3; // need enough file context to detect a real shift
  8→const MIN_CURRENT_FILES = 1; // at least one file needed
  9→const MIN_CHUNK_SIZE = 8; // merge tiny chunks into neighbors
 10→const SIZE_CAP = 80;
 11→const OVERLAP = 3;
 12→const SHORT_SESSION_THRESHOLD = 10;
 13→
 14→// Ignore files outside the project — skill docs, tmp files, etc.
 15→const IGNORED_FILE_PATTERNS = [
 16→  /\/\.claude\//,
 17→  /\/node_modules\//,
 18→  /^\/tmp\//,
 19→  /^\/private\/tmp\//,
 20→];
 21→
 22→const TOPIC_SHIFT_PATTERNS = [
 23→  /\bnow let'?s\b/i,
 24→  /\bmoving on\b/i,
 25→  /\bswitch to\b/i,
 26→  /\bok let'?s work on\b/i,
 27→  /\bok\s+next\b/i,
 28→  /\blet'?s move on\b/i,
 29→];
 30→
 31→// ── Main Entry Point ─────────────────────────────────────────────────
 32→
 33→/**
 34→ * Split a session's normalized events into bounded reasoning windows (chunks).
 35→ * Deterministic — no LLM calls.
 36→ */
 37→export function chunkSession(
 38→  events: NormalizedDevEvent[],
 39→  sessionId: string,
 40→): SessionChunk[] {
 41→  if (events.length === 0) return [];
 42→
 43→  // Short sessions: one chunk, no splitting
 44→  if (events.length < SHORT_SESSION_THRESHOLD) {
 45→    return [buildChunk(events, sessionId, 0, [])];
 46→  }
 47→
 48→  // Find all split points
 49→  const splitIndices = findSplitPoints(events);
 50→
 51→  // Build chunks from split points
 52→  const rawChunks = splitAtIndices(events, splitIndices);
 53→
 54→  // Merge tiny chunks into neighbors
 55→  const mergedChunks = mergeTinyChunks(rawChunks);
 56→
 57→  // Apply size cap to oversized chunks
 58→  const cappedChunks = mergedChunks.flatMap((chunk) => applySizeCap(chunk));
 59→
 60→  // Build SessionChunk objects with overlap
 61→  return buildChunksWithOverlap(cappedChunks, sessionId);
 62→}
 63→
 64→// ── Split Point Detection ────────────────────────────────────────────
 65→
 66→/**
 67→ * Find indices where the event list should be split.
 68→ * A split index N means: chunk boundary between events[N-1] and events[N].
 69→ */
 70→function findSplitPoints(events: NormalizedDevEvent[]): number[] {
 71→  const splits: number[] = [];
 72→  let lastSplit = 0; // Enforce minimum gap between splits
 73→
 74→  for (let i = 1; i < events.length; i++) {
 75→    // Don't split if we're too close to the last split
 76→    if (i - lastSplit < MIN_CHUNK_SIZE) continue;
 77→
 78→    // Priority 1: Large pauses (>5 min gap)
 79→    const gap =
 80→      new Date(events[i].timestamp).getTime() -
 81→      new Date(events[i - 1].timestamp).getTime();
 82→    if (gap > PAUSE_THRESHOLD_MS) {
 83→      splits.push(i);
 84→      lastSplit = i;
 85→      continue;
 86→    }
 87→
 88→    // Priority 2: File cluster shift
 89→    if (hasFileClusterShift(events, i)) {
 90→      splits.push(i);
 91→      lastSplit = i;
 92→      continue;
 93→    }
 94→
 95→    // Priority 3: Explicit topic shift in user messages
 96→    if (hasTopicShift(events[i])) {
 97→      splits.push(i);
 98→      lastSplit = i;
 99→    }
100→  }
101→
102→  return splits;
103→}
104→
105→/**
106→ * Check if the forward window of files at index i represents a cluster shift
107→ * compared to the preceding window.
108→ *
109→ * Compares files from events[index..index+LOOKAHEAD] against
110→ * files from events[index-LOOKBACK..index-1].
111→ * Triggers when >70% of the forward window's files are new.
112→ */
113→function hasFileClusterShift(
114→  events: NormalizedDevEvent[],
115→  index: number,
116→): boolean {
117→  const LOOKAHEAD = 5;
118→  const LOOKBACK = 15;
119→
120→  // Collect files from forward window (current + next few events)
121→  const forwardEnd = Math.min(events.length, index + LOOKAHEAD);
122→  const forwardFiles = new Set<string>();
123→  for (let j = index; j < forwardEnd; j++) {
124→    for (const f of getProjectFiles(events[j])) {
125→      forwardFiles.add(f);
126→    }
127→  }
128→  if (forwardFiles.size < MIN_CURRENT_FILES) return false;
129→
130→  // Collect files from the preceding window
131→  const lookbackStart = Math.max(0, index - LOOKBACK);
132→  const previousFiles = new Set<string>();
133→  for (let j = lookbackStart; j < index; j++) {
134→    for (const f of getProjectFiles(events[j])) {
135→      previousFiles.add(f);
136→    }
137→  }
138→
139→  if (previousFiles.size < MIN_PREVIOUS_FILES) return false;
140→
141→  // Check what percentage of forward files are new
142→  const forwardArr = [...forwardFiles];
143→  const newFiles = forwardArr.filter((f) => !previousFiles.has(f));
144→  return newFiles.length / forwardArr.length > FILE_SHIFT_THRESHOLD;
145→}
146→
147→/**
148→ * Check if an event contains an explicit topic shift phrase.
149→ */
150→function hasTopicShift(event: NormalizedDevEvent): boolean {
151→  if (event.category !== "intent") return false;
152→  const text = event.content.detail;
153→  return TOPIC_SHIFT_PATTERNS.some((p) => p.test(text));
154→}
155→
156→// ── Merge Tiny Chunks ────────────────────────────────────────────────
157→
158→/**
159→ * Merge chunks smaller than MIN_CHUNK_SIZE into their preceding neighbor.
160→ * If the first chunk is tiny, merge it into the next one.
161→ */
162→function mergeTinyChunks(
163→  chunks: NormalizedDevEvent[][],
164→): NormalizedDevEvent[][] {
165→  if (chunks.length <= 1) return chunks;
166→
167→  const result: NormalizedDevEvent[][] = [chunks[0]];
168→
169→  for (let i = 1; i < chunks.length; i++) {
170→    if (chunks[i].length < MIN_CHUNK_SIZE) {
171→      // Merge into the previous chunk
172→      result[result.length - 1] = [
173→        ...result[result.length - 1],
174→        ...chunks[i],
175→      ];
176→    } else {
177→      result.push(chunks[i]);
178→    }
179→  }
180→
181→  // If the first chunk ended up tiny (from being the original first), merge forward
182→  if (result.length > 1 && result[0].length < MIN_CHUNK_SIZE) {
183→    result[1] = [...result[0], ...result[1]];
184→    result.shift();
185→  }
186→
187→  return result;
188→}
189→
190→// ── Chunk Building ───────────────────────────────────────────────────
191→
192→/**
193→ * Split events array at the given indices into sub-arrays.
194→ */
195→function splitAtIndices(
196→  events: NormalizedDevEvent[],
197→  indices: number[],
198→): NormalizedDevEvent[][] {
199→  if (indices.length === 0) return [events];
200→
201→  const chunks: NormalizedDevEvent[][] = [];
202→  let start = 0;
203→
204→  for (const idx of indices) {
205→    if (idx > start) {
206→      chunks.push(events.slice(start, idx));
207→    }
208→    start = idx;
209→  }
210→
211→  // Remaining events after the last split
212→  if (start < events.length) {
213→    chunks.push(events.slice(start));
214→  }
215→
216→  return chunks;
217→}
218→
219→/**
220→ * If a chunk exceeds SIZE_CAP, split it at natural boundaries.
221→ */
222→function applySizeCap(events: NormalizedDevEvent[]): NormalizedDevEvent[][] {
223→  if (events.length <= SIZE_CAP) return [events];
224→
225→  const result: NormalizedDevEvent[][] = [];
226→  let start = 0;
227→
228→  while (start < events.length) {
229→    if (events.length - start <= SIZE_CAP) {
230→      result.push(events.slice(start));
231→      break;
232→    }
233→
234→    // Find the nearest natural boundary around SIZE_CAP
235→    const target = start + SIZE_CAP;
236→    const splitAt = findNaturalBoundary(events, target);
237→    result.push(events.slice(start, splitAt));
238→    start = splitAt;
239→  }
240→
241→  return result;
242→}
243→
244→/**
245→ * Find a natural boundary near the target index.
246→ * Prefer splitting after a tool_result or before a conversation_turn.
247→ * Search within +/- 10 events of target.
248→ */
249→function findNaturalBoundary(
250→  events: NormalizedDevEvent[],
251→  target: number,
252→): number {
253→  const searchRadius = 10;
254→  const lo = Math.max(1, target - searchRadius);
255→  const hi = Math.min(events.length, target + searchRadius);
256→
257→  // Prefer: after tool_result (split at i+1)
258→  for (let i = target; i >= lo; i--) {
259→    if (events[i - 1]?.category === "result") return i;
260→  }
261→  for (let i = target + 1; i < hi; i++) {
262→    if (events[i - 1]?.category === "result") return i;
263→  }
264→
265→  // Fallback: before conversation_turn
266→  for (let i = target; i >= lo; i--) {
267→    if (events[i]?.category === "intent") return i;
268→  }
269→  for (let i = target + 1; i < hi; i++) {
270→    if (events[i]?.category === "intent") return i;
271→  }
272→
273→  // Last resort: split at target
274→  return Math.min(target, events.length);
275→}
276→
277→/**
278→ * Build final SessionChunk objects with overlap between consecutive chunks.
279→ */
280→function buildChunksWithOverlap(
281→  rawChunks: NormalizedDevEvent[][],
282→  sessionId: string,
283→): SessionChunk[] {
284→  const result: SessionChunk[] = [];
285→
286→  for (let i = 0; i < rawChunks.length; i++) {
287→    const ownedEvents = rawChunks[i];
288→    // Prepend overlap from previous chunk (last OVERLAP events)
289→    const overlapEvents =
290→      i > 0 ? rawChunks[i - 1].slice(-OVERLAP) : [];
291→
292→    result.push(buildChunk(ownedEvents, sessionId, i, overlapEvents));
293→  }
294→
295→  return result;
296→}
297→
298→/**
299→ * Build a single SessionChunk from owned events and optional overlap events.
300→ */
301→function buildChunk(
302→  ownedEvents: NormalizedDevEvent[],
303→  sessionId: string,
304→  chunkIndex: number,
305→  overlapEvents: NormalizedDevEvent[],
306→): SessionChunk {
307→  const allEvents = [...overlapEvents, ...ownedEvents];
308→
309→  const startCausalOrder = ownedEvents[0].causalOrder;
310→  const endCausalOrder = ownedEvents[ownedEvents.length - 1].causalOrder;
311→
312→  return {
313→    id: `${sessionId}-chunk-${chunkIndex}`,
314→    sessionId,
315→    chunkIndex,
316→    events: allEvents,
317→    topicHint: deriveTopicHint(ownedEvents),
318→    filesInScope: deriveFilesInScope(allEvents),
319→    eventRange: [startCausalOrder, endCausalOrder],
320→  };
321→}
322→
323→// ── Topic Hint & Files ───────────────────────────────────────────────
324→
325→/**
326→ * Derive a topic hint from the chunk's owned events.
327→ * Heuristic: most frequent directory/filename from filesAffected,
328→ * falling back to first user message summary.
329→ */
330→function deriveTopicHint(events: NormalizedDevEvent[]): string {
331→  // Count file path frequency
332→  const freq = new Map<string, number>();
333→  for (const event of events) {
334→    for (const file of getFilesAffected(event)) {
335→      freq.set(file, (freq.get(file) ?? 0) + 1);
336→    }
337→  }
338→
339→  if (freq.size > 0) {
340→    // Return the most frequent file path
341→    let best = "";
342→    let bestCount = 0;
343→    for (const [file, count] of freq) {
344→      if (count > bestCount) {
345→        best = file;
346→        bestCount = count;
347→      }
348→    }
349→    return best;
350→  }
351→
352→  // Fallback: first user message summary
353→  const userEvent = events.find((e) => e.category === "intent");
354→  if (userEvent) {
355→    return userEvent.content.summary;
356→  }
357→
358→  return "unknown";
359→}
360→
361→/**
362→ * Collect all unique files from events' filesAffected.
363→ */
364→function deriveFilesInScope(events: NormalizedDevEvent[]): string[] {
365→  const files = new Set<string>();
366→  for (const event of events) {
367→    for (const f of getFilesAffected(event)) {
368→      files.add(f);
369→    }
370→  }
371→  return Array.from(files);
372→}
373→
374→/**
375→ * Get filesAffected from an event, defaulting to empty array.
376→ */
377→function getFilesAffected(event: NormalizedDevEvent): string[] {
378→  return event.content.filesAffected ?? [];
379→}
380→
381→/**
382→ * Get only project-relevant files (filter out skill docs, tmp, node_modules).
383→ * Used for file cluster shift detection — we don't want reading a skill doc
384→ * to trigger a chunk split.
385→ */
386→function getProjectFiles(event: NormalizedDevEvent): string[] {
387→  return getFilesAffected(event).filter(
388→    (f) => !IGNORED_FILE_PATTERNS.some((p) => p.test(f)),
389→  );
390→}
