  1→import Anthropic from "@anthropic-ai/sdk";
  2→import type { z } from "zod";
  3→
  4→// ── Constants ────────────────────────────────────────────────────────
  5→
  6→const SONNET_MODEL = "claude-sonnet-4-20250514";
  7→const HAIKU_MODEL = "claude-haiku-4-5-20251001";
  8→
  9→const MAX_RETRIES = 3;
 10→const BASE_DELAY_MS = 1000;
 11→
 12→// ── Lazy Client ──────────────────────────────────────────────────────
 13→
 14→let _client: Anthropic | undefined;
 15→
 16→function getClient(): Anthropic {
 17→  if (!_client) {
 18→    const apiKey = process.env.ANTHROPIC_API_KEY;
 19→    if (!apiKey) {
 20→      throw new Error(
 21→        "ANTHROPIC_API_KEY is not set. Export it in your environment or add it to .env",
 22→      );
 23→    }
 24→    _client = new Anthropic({ apiKey });
 25→  }
 26→  return _client;
 27→}
 28→
 29→// ── Public Interface ─────────────────────────────────────────────────
 30→
 31→export interface LlmCallOptions {
 32→  maxTokens?: number;
 33→  temperature?: number;
 34→}
 35→
 36→/**
 37→ * Call Claude Sonnet with a structured JSON response validated against a Zod schema.
 38→ */
 39→export async function callSonnet<T>(
 40→  systemPrompt: string,
 41→  userPrompt: string,
 42→  schema: z.ZodType<T>,
 43→  options?: LlmCallOptions,
 44→): Promise<T> {
 45→  return callModel(SONNET_MODEL, systemPrompt, userPrompt, schema, options);
 46→}
 47→
 48→/**
 49→ * Call Claude Haiku with a structured JSON response validated against a Zod schema.
 50→ */
 51→export async function callHaiku<T>(
 52→  systemPrompt: string,
 53→  userPrompt: string,
 54→  schema: z.ZodType<T>,
 55→  options?: LlmCallOptions,
 56→): Promise<T> {
 57→  return callModel(HAIKU_MODEL, systemPrompt, userPrompt, schema, options);
 58→}
 59→
 60→// ── Internal ─────────────────────────────────────────────────────────
 61→
 62→async function callModel<T>(
 63→  model: string,
 64→  systemPrompt: string,
 65→  userPrompt: string,
 66→  schema: z.ZodType<T>,
 67→  options?: LlmCallOptions,
 68→): Promise<T> {
 69→  const maxTokens = options?.maxTokens ?? 4096;
 70→  const temperature = options?.temperature ?? 0;
 71→
 72→  let lastError: unknown;
 73→
 74→  // Retry loop for network / rate-limit errors
 75→  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
 76→    try {
 77→      const text = await rawCall(model, systemPrompt, userPrompt, maxTokens, temperature);
 78→      return validateJson(text, schema);
 79→    } catch (err) {
 80→      if (isValidationError(err)) {
 81→        // Validation failed — retry once with a stricter prompt
 82→        return retryWithStricterPrompt(model, systemPrompt, userPrompt, schema, maxTokens, temperature, err);
 83→      }
 84→
 85→      // Network / rate-limit — exponential backoff
 86→      lastError = err;
 87→      if (attempt < MAX_RETRIES - 1) {
 88→        const delay = BASE_DELAY_MS * Math.pow(2, attempt);
 89→        await sleep(delay);
 90→      }
 91→    }
 92→  }
 93→
 94→  throw new Error(
 95→    `LLM call failed after ${MAX_RETRIES} retries: ${lastError instanceof Error ? lastError.message : String(lastError)}`,
 96→  );
 97→}
 98→
 99→async function rawCall(
100→  model: string,
101→  systemPrompt: string,
102→  userPrompt: string,
103→  maxTokens: number,
104→  temperature: number,
105→): Promise<string> {
106→  const client = getClient();
107→  const response = await client.messages.create({
108→    model,
109→    max_tokens: maxTokens,
110→    temperature,
111→    system: systemPrompt,
112→    messages: [{ role: "user", content: userPrompt }],
113→  });
114→
115→  const textBlock = response.content.find((b) => b.type === "text");
116→  if (!textBlock || textBlock.type !== "text") {
117→    throw new Error("No text block in LLM response");
118→  }
119→  return textBlock.text;
120→}
121→
122→function validateJson<T>(text: string, schema: z.ZodType<T>): T {
123→  // Strip markdown code fences if present
124→  const cleaned = text
125→    .replace(/^```(?:json)?\s*\n?/i, "")
126→    .replace(/\n?```\s*$/i, "")
127→    .trim();
128→
129→  let parsed: unknown;
130→  try {
131→    parsed = JSON.parse(cleaned);
132→  } catch {
133→    throw new ValidationError(`LLM returned invalid JSON: ${cleaned.slice(0, 200)}`);
134→  }
135→
136→  const result = schema.safeParse(parsed);
137→  if (!result.success) {
138→    throw new ValidationError(
139→      `Zod validation failed: ${JSON.stringify(result.error.issues ?? result.error, null, 2).slice(0, 500)}`,
140→    );
141→  }
142→  return result.data;
143→}
144→
145→async function retryWithStricterPrompt<T>(
146→  model: string,
147→  systemPrompt: string,
148→  userPrompt: string,
149→  schema: z.ZodType<T>,
150→  maxTokens: number,
151→  temperature: number,
152→  originalError: ValidationError,
153→): Promise<T> {
154→  const stricterUser = [
155→    userPrompt,
156→    "",
157→    "IMPORTANT: Your previous response was not valid JSON or did not match the required schema.",
158→    `Error: ${originalError.message}`,
159→    "",
160→    "Please respond with ONLY valid JSON (no markdown fences, no explanation). Ensure every required field is present and has the correct type.",
161→  ].join("\n");
162→
163→  try {
164→    const text = await rawCall(model, systemPrompt, stricterUser, maxTokens, temperature);
165→    return validateJson(text, schema);
166→  } catch (retryErr) {
167→    throw new Error(
168→      `LLM validation failed after retry. Original: ${originalError.message}. Retry: ${retryErr instanceof Error ? retryErr.message : String(retryErr)}`,
169→    );
170→  }
171→}
172→
173→// ── Helpers ──────────────────────────────────────────────────────────
174→
175→class ValidationError extends Error {
176→  readonly isValidation = true;
177→  constructor(message: string) {
178→    super(message);
179→    this.name = "ValidationError";
180→  }
181→}
182→
183→function isValidationError(err: unknown): err is ValidationError {
184→  return err instanceof ValidationError;
185→}
186→
187→function sleep(ms: number): Promise<void> {
188→  return new Promise((resolve) => setTimeout(resolve, ms));
189→}
