import { eq } from "drizzle-orm";
import { getDb } from "./connection.js";
import {
  sessions,
  rawEvents,
  normalizedEvents,
  chunks,
  moments,
  momentEvidence,
  momentRelations,
  transitions,
  transitionMoments,
  outcomes,
  outcomeMoments,
  outcomeFiles,
  narratives,
  narrativeArcs,
} from "./schema.js";
import type {
  RawDevEvent,
  NormalizedDevEvent,
  SessionChunk,
  SessionMoment,
  IntentTransition,
  AcceptedOutcome,
  SessionNarrative,
  SessionShape,
} from "../adapters/types.js";

// ── Store Full Session Digest ───────────────────────────────────────

export async function storeSessionDigest(data: {
  sessionId: string;
  sourceType: string;
  sourcePath: string;
  sessionShape: SessionShape;
  startedAt: Date | null;
  endedAt: Date | null;
  rawEvents: RawDevEvent[];
  normalizedEvents: NormalizedDevEvent[];
  chunks: SessionChunk[];
  moments: SessionMoment[];
  transitions: IntentTransition[];
  outcomes: AcceptedOutcome[];
  narrative: SessionNarrative;
}): Promise<void> {
  const db = getDb();

  // 1. sessions
  await db.insert(sessions).values({
    id: data.sessionId,
    sourceType: data.sourceType,
    sourcePath: data.sourcePath,
    sessionShape: data.sessionShape,
    startedAt: data.startedAt,
    endedAt: data.endedAt,
  });

  // 2. raw_events
  if (data.rawEvents.length > 0) {
    await db.insert(rawEvents).values(
      data.rawEvents.map((e) => ({
        id: e.id,
        sessionId: data.sessionId,
        source: e.source,
        timestamp: e.timestamp ? new Date(e.timestamp) : null,
        type: e.type,
        raw: e.raw,
      })),
    );
  }

  // 3. normalized_events
  if (data.normalizedEvents.length > 0) {
    await db.insert(normalizedEvents).values(
      data.normalizedEvents.map((e) => ({
        id: e.id,
        sessionId: data.sessionId,
        rawEventId: e.rawEventId,
        causalOrder: e.causalOrder,
        category: e.category,
        actor: e.actor,
        summary: e.content.summary,
        detail: e.content.detail,
        filesAffected: e.content.filesAffected ?? null,
      })),
    );
  }

  // 4. chunks
  if (data.chunks.length > 0) {
    await db.insert(chunks).values(
      data.chunks.map((c) => ({
        id: c.id,
        sessionId: data.sessionId,
        chunkIndex: c.chunkIndex,
        topicHint: c.topicHint,
        filesInScope: c.filesInScope,
        eventRangeStart: c.eventRange[0],
        eventRangeEnd: c.eventRange[1],
      })),
    );
  }

  // 5. moments
  if (data.moments.length > 0) {
    await db.insert(moments).values(
      data.moments.map((m) => ({
        id: m.id,
        sessionId: data.sessionId,
        chunkId: m.chunkId,
        type: m.type,
        statement: m.statement,
        significance: m.significance,
        agency: m.agency,
        confidence: m.confidence,
        topicFingerprint: m.topicFingerprint,
        arcId: m.arcId ?? null,
        arcRole: m.arcRole ?? null,
      })),
    );

    // 6. moment_evidence
    const evidenceRows = data.moments.flatMap((m) =>
      m.evidence.map((e) => ({
        momentId: m.id,
        quote: e.quote,
        sourceEventId: e.sourceEventId || null,
        sourceType: e.sourceType,
        quoteType: e.quoteType,
      })),
    );
    if (evidenceRows.length > 0) {
      await db.insert(momentEvidence).values(evidenceRows);
    }

    // 7. moment_relations
    const relationRows = data.moments.flatMap((m) =>
      m.relatedMomentIds.map((relId) => ({
        momentId: m.id,
        relatedMomentId: relId,
        relationType: "evolved_into" as const,
      })),
    );
    if (relationRows.length > 0) {
      await db.insert(momentRelations).values(relationRows);
    }
  }

  // 8. transitions
  if (data.transitions.length > 0) {
    await db.insert(transitions).values(
      data.transitions.map((t) => ({
        id: t.id,
        sessionId: data.sessionId,
        fromStatement: t.fromStatement,
        toStatement: t.toStatement,
        reason: t.reason,
        arcId: t.arcId ?? null,
        confidence: t.confidence,
      })),
    );

    // 9. transition_moments
    const tmRows = data.transitions.flatMap((t) =>
      t.originMomentIds.map((mId) => ({
        transitionId: t.id,
        momentId: mId,
      })),
    );
    if (tmRows.length > 0) {
      await db.insert(transitionMoments).values(tmRows);
    }
  }

  // 10. outcomes
  if (data.outcomes.length > 0) {
    await db.insert(outcomes).values(
      data.outcomes.map((o) => ({
        id: o.id,
        sessionId: data.sessionId,
        statement: o.statement,
        confidence: o.confidence,
      })),
    );

    // 11. outcome_moments
    const omRows = data.outcomes.flatMap((o) =>
      o.supportingMomentIds.map((mId) => ({
        outcomeId: o.id,
        momentId: mId,
      })),
    );
    if (omRows.length > 0) {
      await db.insert(outcomeMoments).values(omRows);
    }

    // 12. outcome_files
    const ofRows = data.outcomes.flatMap((o) =>
      o.supportingFiles.map((fp) => ({
        outcomeId: o.id,
        filePath: fp,
      })),
    );
    if (ofRows.length > 0) {
      await db.insert(outcomeFiles).values(ofRows);
    }
  }

  // 13. narratives
  const [narrativeRow] = await db
    .insert(narratives)
    .values({
      sessionId: data.sessionId,
      sessionShape: data.narrative.sessionShape,
      summary: data.narrative.summary,
      progression: data.narrative.progression,
      discoveries: data.narrative.discoveries,
      stabilizedDirections: data.narrative.stabilizedDirections,
      abandonedDirections: data.narrative.abandonedDirections,
    })
    .returning({ id: narratives.id });

  // 14. narrative_arcs
  if (data.narrative.arcs.length > 0) {
    await db.insert(narrativeArcs).values(
      data.narrative.arcs.map((arc) => ({
        narrativeId: narrativeRow.id,
        arcId: arc.arcId,
        title: arc.title,
        summary: arc.summary,
        resolution: arc.resolution,
        momentIds: arc.momentIds,
      })),
    );
  }
}

// ── Query Helpers ───────────────────────────────────────────────────

export async function getSessionNarrative(
  sessionId: string,
): Promise<SessionNarrative | null> {
  const db = getDb();

  const rows = await db
    .select()
    .from(narratives)
    .where(eq(narratives.sessionId, sessionId))
    .limit(1);

  if (rows.length === 0) return null;

  const row = rows[0];

  const arcRows = await db
    .select()
    .from(narrativeArcs)
    .where(eq(narrativeArcs.narrativeId, row.id));

  return {
    sessionId,
    sessionShape: row.sessionShape as SessionShape,
    summary: row.summary,
    progression: row.progression ?? [],
    discoveries: row.discoveries ?? [],
    stabilizedDirections: row.stabilizedDirections ?? [],
    abandonedDirections: row.abandonedDirections ?? [],
    arcs: arcRows.map((a) => ({
      arcId: a.arcId,
      title: a.title,
      summary: a.summary ?? "",
      momentIds: a.momentIds ?? [],
      resolution: (a.resolution as "resolved" | "abandoned" | "open") ?? "open",
    })),
  };
}

export async function getSessionMoments(
  sessionId: string,
): Promise<SessionMoment[]> {
  const db = getDb();

  const momentRows = await db
    .select()
    .from(moments)
    .where(eq(moments.sessionId, sessionId));

  const result: SessionMoment[] = [];

  for (const m of momentRows) {
    const evidenceRows = await db
      .select()
      .from(momentEvidence)
      .where(eq(momentEvidence.momentId, m.id));

    const relationRows = await db
      .select()
      .from(momentRelations)
      .where(eq(momentRelations.momentId, m.id));

    result.push({
      id: m.id,
      chunkId: m.chunkId ?? "",
      type: m.type as SessionMoment["type"],
      statement: m.statement,
      significance: m.significance ?? "",
      agency: (m.agency as SessionMoment["agency"]) ?? "ambiguous",
      confidence: (m.confidence as SessionMoment["confidence"]) ?? "low",
      topicFingerprint: m.topicFingerprint ?? "",
      relatedMomentIds: relationRows.map((r) => r.relatedMomentId),
      arcId: m.arcId ?? undefined,
      arcRole: (m.arcRole as SessionMoment["arcRole"]) ?? undefined,
      evidence: evidenceRows.map((e) => ({
        quote: e.quote,
        sourceEventId: e.sourceEventId ?? "",
        sourceType: (e.sourceType as SessionMoment["evidence"][0]["sourceType"]) ?? "human_message",
        quoteType: (e.quoteType as "verbatim" | "summarized") ?? "summarized",
      })),
    });
  }

  return result;
}

export async function listSessions(): Promise<
  Array<{ id: string; shape: string; startedAt: Date | null; summary: string }>
> {
  const db = getDb();

  const sessionRows = await db.select().from(sessions);

  const result: Array<{
    id: string;
    shape: string;
    startedAt: Date | null;
    summary: string;
  }> = [];

  for (const s of sessionRows) {
    const narr = await db
      .select({ summary: narratives.summary })
      .from(narratives)
      .where(eq(narratives.sessionId, s.id))
      .limit(1);

    result.push({
      id: s.id,
      shape: s.sessionShape ?? "unknown",
      startedAt: s.startedAt,
      summary: narr[0]?.summary ?? "",
    });
  }

  return result;
}

import crypto from "node:crypto";
import { parseClaudeCodeLog } from "../adapters/claude-code.js";
import { normalize } from "./normalize.js";
import { classifySession } from "./classify.js";
import { chunkSession } from "./chunk.js";
import { detectMoments } from "./moments.js";
import { detectTransitionsAndOutcomes } from "./transitions.js";
import { generateNarrative } from "./narrative.js";
import { storeSessionDigest } from "../storage/queries.js";
import type {
  SessionNarrative,
  SessionMoment,
  IntentTransition,
  AcceptedOutcome,
} from "../adapters/types.js";

function log(step: string): void {
  process.stderr.write(`${step}\n`);
}

export async function runPipeline(logPath: string): Promise<{
  sessionId: string;
  narrative: SessionNarrative;
  moments: SessionMoment[];
  transitions: IntentTransition[];
  outcomes: AcceptedOutcome[];
}> {
  // 1. Parse
  log("[1/9] Parsing CC log...");
  const rawEvents = await parseClaudeCodeLog(logPath);

  // 2. Generate sessionId
  const sessionId = crypto.randomUUID();

  // 3. Normalize
  log(`[2/9] Normalizing ${rawEvents.length} events...`);
  const normalizedEvents = normalize(rawEvents, sessionId);

  // Large session warning
  if (normalizedEvents.length > 300) {
    const estimatedChunks = Math.ceil(normalizedEvents.length / 60);
    const estimatedLlmCalls = estimatedChunks + 3; // pass1 per chunk + classify + pass2 + transitions + narrative
    log(
      `  ⚠ Large session: ${normalizedEvents.length} events, ~${estimatedChunks} chunks, ~${estimatedLlmCalls} LLM calls`,
    );
  }

  // 4. Classify
  log("[3/9] Classifying session shape...");
  const sessionShape = await classifySession(normalizedEvents);

  // 5. Chunk
  const sessionChunks = chunkSession(normalizedEvents, sessionId);
  log(`[4/9] Chunking into ${sessionChunks.length} windows...`);

  // 6. Detect moments (pass 1 + 2)
  log("[5/9] Detecting moments (pass 1)...");
  log("[6/9] Detecting moments (pass 2)...");
  const sessionMoments = await detectMoments(sessionChunks, sessionShape);

  // 7. Transitions + outcomes
  log("[7/9] Detecting transitions & outcomes...");
  const { transitions, outcomes } = await detectTransitionsAndOutcomes(
    sessionMoments,
    sessionId,
  );

  // 8. Narrative
  log("[8/9] Generating narrative...");
  const narrative = await generateNarrative(
    sessionMoments,
    transitions,
    outcomes,
    sessionShape,
  );
  narrative.sessionId = sessionId;

  // 9. Store
  log("[9/9] Storing to database...");

  // Derive timestamps from raw events
  const timestamps = rawEvents
    .map((e) => e.timestamp)
    .filter(Boolean)
    .map((t) => new Date(t));
  const startedAt = timestamps.length > 0 ? new Date(Math.min(...timestamps.map((d) => d.getTime()))) : null;
  const endedAt = timestamps.length > 0 ? new Date(Math.max(...timestamps.map((d) => d.getTime()))) : null;

  try {
    await storeSessionDigest({
      sessionId,
      sourceType: "claude-code",
      sourcePath: logPath,
      sessionShape,
      startedAt,
      endedAt,
      rawEvents,
      normalizedEvents,
      chunks: sessionChunks,
      moments: sessionMoments,
      transitions,
      outcomes,
      narrative,
    });
  } catch (err) {
    log(
      `  ⚠ Database write failed: ${err instanceof Error ? err.message : String(err)}`,
    );
    log("  Pipeline results are still available, just not persisted.");
  }

  return {
    sessionId,
    narrative,
    moments: sessionMoments,
    transitions,
    outcomes,
  };
}

import type { Command } from "commander";
import { runPipeline } from "../pipeline/orchestrator.js";
import { parseClaudeCodeLog } from "../adapters/claude-code.js";
import { normalize } from "../pipeline/normalize.js";
import { chunkSession } from "../pipeline/chunk.js";
import { discoverLatestLog, discoverLogs } from "../utils/log-discovery.js";
import type {
  SessionNarrative,
  SessionMoment,
  IntentTransition,
  AcceptedOutcome,
} from "../adapters/types.js";

export function registerDigestCommand(program: Command): void {
  program
    .command("digest [path]")
    .description("Ingest conversation logs and produce session digests")
    .option("--last <n>", "Process N most recent sessions", parseInt)
    .option("--dry-run", "Run deterministic pipeline only (no LLM calls), print stats")
    .action(async (path: string | undefined, opts: { last?: number; dryRun?: boolean }) => {
      try {
        if (opts.dryRun) {
          await runDryRun(path, opts.last);
          return;
        }

        const paths = await resolvePaths(path, opts.last);

        for (const logPath of paths) {
          const result = await runPipeline(logPath);
          printDigest(result);
          if (paths.length > 1) {
            console.log("\n" + "─".repeat(60) + "\n");
          }
        }
      } catch (err) {
        console.error(
          `Error: ${err instanceof Error ? err.message : String(err)}`,
        );
        process.exit(1);
      }
    });
}

// ── Path Resolution ─────────────────────────────────────────────────

async function resolvePaths(
  path: string | undefined,
  last: number | undefined,
): Promise<string[]> {
  if (path) {
    return [path];
  }

  if (last && last > 0) {
    const paths = await discoverLogs(last);
    if (paths.length === 0) {
      throw new Error("No Claude Code logs found in ~/.claude/projects/");
    }
    return paths;
  }

  // Default: latest log
  const latest = await discoverLatestLog();
  if (!latest) {
    throw new Error(
      "No Claude Code logs found in ~/.claude/projects/. Provide an explicit path.",
    );
  }
  return [latest];
}

// ── Dry Run ─────────────────────────────────────────────────────────

async function runDryRun(
  path: string | undefined,
  last: number | undefined,
): Promise<void> {
  const paths = await resolvePaths(path, last);

  for (const logPath of paths) {
    console.log(`Log: ${logPath}`);
    const rawEvents = await parseClaudeCodeLog(logPath);
    const sessionId = "dry-run";
    const normalizedEvents = normalize(rawEvents, sessionId);
    const sessionChunks = chunkSession(normalizedEvents, sessionId);

    const timestamps = rawEvents
      .map((e) => e.timestamp)
      .filter(Boolean)
      .map((t) => new Date(t));
    const startedAt =
      timestamps.length > 0
        ? new Date(Math.min(...timestamps.map((d) => d.getTime())))
        : null;
    const endedAt =
      timestamps.length > 0
        ? new Date(Math.max(...timestamps.map((d) => d.getTime())))
        : null;

    console.log(`  Raw events:        ${rawEvents.length}`);
    console.log(`  Normalized events: ${normalizedEvents.length}`);
    console.log(`  Chunks:            ${sessionChunks.length}`);
    if (startedAt && endedAt) {
      const durationMin = Math.round(
        (endedAt.getTime() - startedAt.getTime()) / 60000,
      );
      console.log(`  Time span:         ${formatTime(startedAt)} → ${formatTime(endedAt)} (${durationMin} min)`);
    }

    // Category breakdown
    const categories: Record<string, number> = {};
    for (const e of normalizedEvents) {
      categories[e.category] = (categories[e.category] ?? 0) + 1;
    }
    console.log(
      `  Categories:        ${Object.entries(categories)
        .map(([k, v]) => `${k}:${v}`)
        .join(", ")}`,
    );

    if (paths.length > 1) console.log();
  }
}

// ── Output Formatting ───────────────────────────────────────────────

function printDigest(result: {
  sessionId: string;
  narrative: SessionNarrative;
  moments: SessionMoment[];
  transitions: IntentTransition[];
  outcomes: AcceptedOutcome[];
}): void {
  const { narrative, moments, transitions, outcomes } = result;

  // Header
  console.log(`Session: ${narrative.sessionShape}`);
  console.log();

  // Summary
  console.log(`Summary: ${narrative.summary}`);
  console.log();

  // Arcs
  if (narrative.arcs.length > 0) {
    console.log("Arcs:");
    for (const arc of narrative.arcs) {
      console.log(`  ◆ ${arc.title} (${arc.resolution})`);
      // Find progression items that belong to this arc's moments
      const arcMomentIds = new Set(arc.momentIds);
      const arcProgressions = narrative.progression.filter((_, idx) => {
        // Map progression items to moments by index
        return idx < moments.length && arcMomentIds.has(moments[idx]?.id);
      });
      for (const item of arcProgressions) {
        console.log(`    → ${item}`);
      }
    }
    console.log();
  }

  // Accepted outcomes
  if (outcomes.length > 0) {
    console.log("Accepted Outcomes:");
    for (const o of outcomes) {
      console.log(`  • ${o.statement}`);
    }
    console.log();
  }

  // Abandoned directions
  if (narrative.abandonedDirections.length > 0) {
    console.log("Abandoned:");
    for (const d of narrative.abandonedDirections) {
      console.log(`  • ${d}`);
    }
    console.log();
  }

  // Stats
  const high = moments.filter((m) => m.confidence === "high").length;
  const medium = moments.filter((m) => m.confidence === "medium").length;
  const low = moments.filter((m) => m.confidence === "low").length;
  console.log(
    `Moments: ${moments.length} total (${high} high, ${medium} medium, ${low} low confidence)`,
  );
  console.log(`Transitions: ${transitions.length}`);
}

function formatTime(date: Date): string {
  return date.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

