import { parseClaudeCodeLog } from './src/adapters/claude-code.js';
import { normalize } from './src/pipeline/normalize.js';
import { chunkSession } from './src/pipeline/chunk.js';
import { randomUUID } from 'crypto';
import { homedir } from 'os';
import { join } from 'path';

const LOG = join(homedir(), '.claude/projects/-Users-giladkoch-dev-intent-ai/84280b36-1375-4a79-9d53-e31c6d124146.jsonl');

function estimateTokens(text: string): number {
  // Rough estimate: ~4 chars per token for English
  return Math.ceil(text.length / 4);
}

async function main() {
  const raw = await parseClaudeCodeLog(LOG);
  const sessionId = randomUUID();
  const normalized = normalize(raw, sessionId);
  const chunks = chunkSession(normalized, sessionId);

  console.log(`Session: ${raw.length} raw → ${normalized.length} normalized → ${chunks.length} chunks\n`);

  let totalPass1Tokens = 0;

  for (const c of chunks) {
    // Build what would go into the LLM prompt for this chunk
    const chunkText = c.events.map(e => {
      const actor = e.actor === 'user' ? 'USER' : 'AI';
      const cat = e.category.toUpperCase();
      const detail = e.content.detail.slice(0, 400);
      const files = e.content.filesAffected?.join(', ') || '';
      return `[${e.causalOrder}] ${actor}/${cat}: ${e.content.summary}\n${detail}${files ? '\nFiles: ' + files : ''}`;
    }).join('\n---\n');

    const tokens = estimateTokens(chunkText);
    totalPass1Tokens += tokens;

    // Categorize events
    const cats: Record<string, number> = {};
    for (const e of c.events) {
      cats[e.category] = (cats[e.category] || 0) + 1;
    }

    // Get first user message for context
    const firstIntent = c.events.find(e => e.category === 'intent');
    const contextHint = firstIntent?.content.summary.slice(0, 100) || c.topicHint.slice(0, 100);

    console.log(`── Chunk ${c.chunkIndex} [${c.eventRange[0]}-${c.eventRange[1]}] ──`);
    console.log(`  Events: ${c.events.length} (owned: ${c.eventRange[1] - c.eventRange[0] + 1})`);
    console.log(`  Est. tokens: ~${tokens.toLocaleString()}`);
    console.log(`  Categories: ${Object.entries(cats).map(([k,v]) => `${k}:${v}`).join(', ')}`);
    console.log(`  Files: ${c.filesInScope.length}`);
    console.log(`  Context: ${contextHint}`);
    console.log();
  }

  // Estimate total LLM costs
  const pass2InputTokens = Math.ceil(totalPass1Tokens * 0.15); // moments are compressed
  const transitionsTokens = Math.ceil(pass2InputTokens * 0.8);
  const narrativeTokens = Math.ceil(pass2InputTokens * 1.2);
  const classifyTokens = 500;

  const totalInputTokens = classifyTokens + totalPass1Tokens + pass2InputTokens + transitionsTokens + narrativeTokens;

  console.log(`════════════════════════════════════`);
  console.log(`Total chunks: ${chunks.length}`);
  console.log(`\nEstimated input tokens per step:`);
  console.log(`  Classify (Haiku):          ~${classifyTokens.toLocaleString()}`);
  console.log(`  Moments pass 1 (Sonnet):   ~${totalPass1Tokens.toLocaleString()} (${chunks.length} calls, parallel)`);
  console.log(`  Moments pass 2 (Sonnet):   ~${pass2InputTokens.toLocaleString()} (1 call)`);
  console.log(`  Transitions (Sonnet):      ~${transitionsTokens.toLocaleString()} (1 call)`);
  console.log(`  Narrative (Sonnet):        ~${narrativeTokens.toLocaleString()} (1 call)`);
  console.log(`  ─────────────────────────────────`);
  console.log(`  Total input:               ~${totalInputTokens.toLocaleString()} tokens`);
  console.log(`  Total LLM calls:           ${chunks.length + 4} (${chunks.length} pass1 + 1 haiku + 3 sonnet)`);
  console.log(`\n  Sonnet input: ~$${((totalInputTokens - classifyTokens) * 3 / 1_000_000).toFixed(3)}`);
  console.log(`  Haiku input:  ~$${(classifyTokens * 0.8 / 1_000_000).toFixed(4)}`);
}

main().catch(console.error);

