257→ */
258→function extractFilePath(
259→  input: Record<string, unknown> | undefined,
260→): string | undefined {
261→  if (!input) return undefined;
262→  const candidates = ["file_path", "path", "filePath"];
263→  for (const key of candidates) {
264→    if (typeof input[key] === "string") return input[key] as string;
