269→/**
270→ * Extract text from a tool_result event.
271→ */
272→function getToolResultText(raw: Record<string, unknown>): string | null {
273→  const msg = raw.message as { content?: unknown } | undefined;
274→  if (!msg?.content) return null;
275→
276→  if (typeof msg.content === "string") return msg.content;
277→
278→  if (Array.isArray(msg.content)) {
279→    for (const block of msg.content) {
280→      const b = block as { type?: string; content?: unknown };
281→      if (b.type === "tool_result") {
282→        // content can be a string or array of text blocks
283→        if (typeof b.content === "string") return b.content;
284→        if (Array.isArray(b.content)) {
285→          const texts: string[] = [];
286→          for (const inner of b.content) {
287→            const t = inner as { type?: string; text?: string };
288→            if (t.type === "text" && t.text) texts.push(t.text);
289→          }
290→          if (texts.length > 0) return texts.join("\n");
