  1→import type { RawDevEvent, NormalizedDevEvent } from "../adapters/types.js";
  2→
  3→// Tools that modify state — their tool_call events are categorized as "action"
  4→const STATE_MODIFYING_TOOLS = new Set([
  5→  "Edit",
  6→  "Write",
  7→  "Bash",
  8→  "NotebookEdit",
  9→]);
 10→
 11→// Tools that read state — their tool_call events are categorized as "reflection"
 12→// (Read, Glob, Grep, Agent, Explore, WebSearch, WebFetch, etc.)
 13→
 14→/**
 15→ * Normalize a sequence of RawDevEvents into NormalizedDevEvents.
 16→ *
 17→ * Assigns causal order, classifies each event into a semantic category,
 18→ * extracts content summaries, and filters out events with no meaningful content.
 19→ */
 20→export function normalize(
 21→  events: RawDevEvent[],
 22→  sessionId: string,
 23→): NormalizedDevEvent[] {
 24→  // ── Pass 1: classify + extract content ──────────────────────────────
 25→  const result: NormalizedDevEvent[] = [];
 26→  let causalOrder = 0;
 27→
 28→  for (let i = 0; i < events.length; i++) {
 29→    const event = events[i];
 30→    const extracted = extractContent(event);
 31→
 32→    // Filter out events with no meaningful content
 33→    if (!extracted) continue;
 34→
 35→    const { category, actor } = classify(event, events, i);
 36→
 37→    result.push({
 38→      id: `${sessionId}-${causalOrder}`,
 39→      sessionId,
 40→      timestamp: event.timestamp,
 41→      causalOrder,
 42→      category,
 43→      actor,
 44→      content: extracted,
 45→      rawEventId: event.id,
 46→      turnId: deriveTurnId(event.id),
 47→    });
 48→
 49→    causalOrder++;
 50→  }
 51→
 52→  // ── Pass 2: assign respondingTo ─────────────────────────────────────
 53→  assignRespondingTo(result, events);
 54→
 55→  return result;
 56→}
 57→
 58→// ── Classification ───────────────────────────────────────────────────
 59→
 60→type Classification = {
 61→  category: NormalizedDevEvent["category"];
 62→  actor: NormalizedDevEvent["actor"];
 63→};
 64→
 65→function classify(
 66→  event: RawDevEvent,
 67→  events: RawDevEvent[],
 68→  index: number,
 69→): Classification {
 70→  switch (event.type) {
 71→    case "conversation_turn":
 72→      return { category: "intent", actor: "user" };
 73→
 74→    case "tool_result":
 75→      return { category: "result", actor: "user" };
 76→
 77→    case "tool_call":
 78→      return {
 79→        category: isStateModifying(event) ? "action" : "reflection",
 80→        actor: "ai",
 81→      };
 82→
 83→    case "ai_response":
 84→      return {
 85→        category: isAfterToolResult(events, index)
 86→          ? "reflection"
 87→          : "proposal",
 88→        actor: "ai",
 89→      };
 90→  }
 91→}
 92→
 93→/**
 94→ * Check whether a tool_call event uses a state-modifying tool.
 95→ */
 96→function isStateModifying(event: RawDevEvent): boolean {
 97→  const toolName = getToolName(event);
 98→  return toolName !== undefined && STATE_MODIFYING_TOOLS.has(toolName);
 99→}
100→
101→/**
102→ * An ai_response is a "reflection" if the most recent non-ai_response event
103→ * before it (scanning backwards) is a tool_result. Otherwise it's a "proposal".
104→ */
105→function isAfterToolResult(events: RawDevEvent[], index: number): boolean {
106→  for (let j = index - 1; j >= 0; j--) {
107→    const prev = events[j];
108→    // Skip over other ai_response events in the same message
109→    if (prev.type === "ai_response") continue;
110→    return prev.type === "tool_result";
111→  }
112→  return false;
113→}
114→
115→// ── Content Extraction ───────────────────────────────────────────────
116→
117→function extractContent(
118→  event: RawDevEvent,
119→): NormalizedDevEvent["content"] | null {
120→  const raw = event.raw;
121→
122→  switch (event.type) {
123→    case "conversation_turn": {
124→      const text = getUserText(raw);
125→      if (!text) return null;
126→      return {
127→        summary: truncate(text, 200),
128→        detail: text,
129→      };
130→    }
131→
132→    case "ai_response": {
133→      const text = getAiText(event);
134→      if (!text) return null;
135→      return {
136→        summary: truncate(text, 200),
137→        detail: text,
138→      };
139→    }
140→
141→    case "tool_call": {
142→      const toolName = getToolName(event);
143→      const input = getToolInput(event);
144→      if (!toolName) return null;
145→
146→      const filePath = extractFilePath(input);
147→      const summary = filePath
148→        ? `Tool: ${toolName} on ${filePath}`
149→        : `Tool: ${toolName}`;
150→      const detail = input ? JSON.stringify(input) : summary;
151→      const filesAffected = filePath ? [filePath] : undefined;
152→
153→      return { summary: truncate(summary, 200), detail, filesAffected };
154→    }
155→
156→    case "tool_result": {
157→      const text = getToolResultText(raw);
158→      if (!text) return null;
159→      return {
160→        summary: truncate(text, 200),
161→        detail: text,
162→      };
163→    }
164→  }
165→}
166→
167→// ── Helpers ──────────────────────────────────────────────────────────
168→
169→function truncate(s: string, maxLen: number): string {
170→  return s.length <= maxLen ? s : s.slice(0, maxLen);
171→}
172→
173→/**
174→ * Extract user text from the raw log entry.
175→ * Content can be a string or an array of content blocks.
176→ */
177→function getUserText(raw: Record<string, unknown>): string | null {
178→  const msg = raw.message as { content?: unknown } | undefined;
179→  if (!msg?.content) return null;
180→  if (typeof msg.content === "string") return msg.content;
181→  return null;
182→}
183→
184→/**
185→ * Extract AI text from an ai_response event.
186→ * The event ID encodes which content block it came from (e.g., "a-001-text-1").
187→ */
188→function getAiText(event: RawDevEvent): string | null {
189→  const raw = event.raw;
190→  const msg = raw.message as { content?: unknown[] } | undefined;
191→  if (!msg?.content || !Array.isArray(msg.content)) return null;
192→
193→  // Find the text block index from the event ID (format: "...-text-N")
194→  const match = event.id.match(/-text-(\d+)$/);
195→  if (match) {
196→    const idx = parseInt(match[1], 10);
197→    const block = msg.content[idx] as { type?: string; text?: string } | undefined;
198→    if (block?.type === "text" && block.text) return block.text;
199→  }
200→
201→  // Fallback: find first text block
202→  for (const block of msg.content) {
203→    const b = block as { type?: string; text?: string };
204→    if (b.type === "text" && b.text) return b.text;
205→  }
206→  return null;
207→}
208→
209→/**
210→ * Extract tool name from a tool_call event.
211→ */
212→function getToolName(event: RawDevEvent): string | undefined {
213→  const raw = event.raw;
214→  const msg = raw.message as { content?: unknown[] } | undefined;
215→  if (!msg?.content || !Array.isArray(msg.content)) return undefined;
216→
217→  // Find tool_use block index from event ID (format: "...-tool-N")
218→  const match = event.id.match(/-tool-(\d+)$/);
219→  if (match) {
220→    const idx = parseInt(match[1], 10);
221→    const block = msg.content[idx] as { type?: string; name?: string } | undefined;
222→    if (block?.type === "tool_use" && block.name) return block.name;
223→  }
224→
225→  // Fallback: first tool_use block
226→  for (const block of msg.content) {
227→    const b = block as { type?: string; name?: string };
228→    if (b.type === "tool_use" && b.name) return b.name;
229→  }
230→  return undefined;
231→}
232→
233→/**
234→ * Extract tool input from a tool_call event.
235→ */
236→function getToolInput(
237→  event: RawDevEvent,
238→): Record<string, unknown> | undefined {
239→  const raw = event.raw;
240→  const msg = raw.message as { content?: unknown[] } | undefined;
241→  if (!msg?.content || !Array.isArray(msg.content)) return undefined;
242→
243→  const match = event.id.match(/-tool-(\d+)$/);
244→  if (match) {
245→    const idx = parseInt(match[1], 10);
246→    const block = msg.content[idx] as {
247→      type?: string;
248→      input?: Record<string, unknown>;
249→    } | undefined;
250→    if (block?.type === "tool_use" && block.input) return block.input;
251→  }
252→
253→  for (const block of msg.content) {
254→    const b = block as { type?: string; input?: Record<string, unknown> };
255→    if (b.type === "tool_use" && b.input) return b.input;
256→  }
257→  return undefined;
258→}
259→
260→/**
261→ * Extract file path from tool input parameters.
262→ */
263→function extractFilePath(
264→  input: Record<string, unknown> | undefined,
265→): string | undefined {
266→  if (!input) return undefined;
267→  const candidates = ["file_path", "path", "filePath"];
268→  for (const key of candidates) {
269→    if (typeof input[key] === "string") return input[key] as string;
270→  }
271→  return undefined;
272→}
273→
274→// ── Causal Threading ─────────────────────────────────────────────────
275→
276→/**
277→ * Derive the turnId from a rawEventId.
278→ *
279→ * ID formats:
280→ *  - User conversation_turn: "u-001" → turnId "u-001"
281→ *  - AI text:    "a-001-text-0"   → turnId "a-001"
282→ *  - AI tool:    "a-001-tool-1"   → turnId "a-001"
283→ *  - Tool result: "u-002-result-0" → turnId "u-002"
284→ *
285→ * Strip the last two hyphen-separated segments if they match known suffixes.
286→ */
287→function deriveTurnId(rawEventId: string): string {
288→  // Match IDs with a type suffix: -text-N, -tool-N, -result-N
289→  const match = rawEventId.match(/^(.+)-(text|tool|result)-\d+$/);
290→  if (match) return match[1];
291→  // Plain user ID: "u-001"
292→  return rawEventId;
293→}
294→
295→/**
296→ * Extract tool_use_id from a tool_result event's raw data.
297→ * The raw content is an array with blocks like { type: "tool_result", tool_use_id: "tu-001" }.
298→ */
299→function getToolUseIdFromResult(event: NormalizedDevEvent, rawEvents: RawDevEvent[]): string | undefined {
300→  // Find the original raw event
301→  const rawEvent = rawEvents.find((r) => r.id === event.rawEventId);
302→  if (!rawEvent) return undefined;
303→
304→  const raw = rawEvent.raw;
305→  const msg = raw.message as { content?: unknown } | undefined;
306→  if (!msg?.content || !Array.isArray(msg.content)) return undefined;
307→
308→  // The event ID tells us which block index: e.g., "u-002-result-0" → index 0
309→  const idxMatch = event.rawEventId.match(/-result-(\d+)$/);
310→  if (idxMatch) {
311→    const idx = parseInt(idxMatch[1], 10);
312→    const block = msg.content[idx] as { type?: string; tool_use_id?: string } | undefined;
313→    if (block?.type === "tool_result" && block.tool_use_id) return block.tool_use_id;
314→  }
315→
316→  // Fallback: first tool_result block
317→  for (const block of msg.content) {
