330→
331→  const raw = rawEvent.raw;
332→  const msg = raw.message as { content?: unknown[] } | undefined;
333→  if (!msg?.content || !Array.isArray(msg.content)) return undefined;
334→
335→  const idxMatch = event.rawEventId.match(/-tool-(\d+)$/);
