347→ *
348→ * Rules:
349→ *  - First event: no respondingTo
350→ *  - Tool result: responds to matching tool_call (by tool_use_id)
351→ *  - AI event: responds to first event of the most recent user turn
352→ *  - User conversation_turn: responds to last event of the most recent AI turn
353→ */
354→function assignRespondingTo(
355→  events: NormalizedDevEvent[],
356→  rawEvents: RawDevEvent[],
357→): void {
358→  // Build a map of tool_use_id → normalized event id for tool_call events
359→  const toolUseIdToEventId = new Map<string, string>();
360→  for (const event of events) {
361→    if (event.rawEventId.includes("-tool-")) {
362→      const toolUseId = getToolUseIdFromCall(event, rawEvents);
363→      if (toolUseId) {
364→        toolUseIdToEventId.set(toolUseId, event.id);
365→      }
366→    }
367→  }
368→
369→  // Track turns: first event per turnId, last event per turnId
370→  const firstEventByTurn = new Map<string, NormalizedDevEvent>();
371→  const lastEventByTurn = new Map<string, NormalizedDevEvent>();
372→
373→  // Track the most recent completed user and AI turns
374→  let lastUserTurnId: string | undefined;
375→  let lastAiTurnId: string | undefined;
376→
377→  for (const event of events) {
378→    const turnId = event.turnId;
379→    const isUserTurn = turnId.startsWith("u-");
380→    const isAiTurn = turnId.startsWith("a-");
381→
382→    // Track first/last event per turn
383→    if (!firstEventByTurn.has(turnId)) {
384→      firstEventByTurn.set(turnId, event);
385→    }
386→    lastEventByTurn.set(turnId, event);
387→
388→    // Determine respondingTo
389→    if (event.causalOrder === 0) {
390→      // First event — no respondingTo
391→      // (leave undefined)
392→    } else if (event.rawEventId.includes("-result-")) {
393→      // Tool result → responds to matching tool_call
394→      const toolUseId = getToolUseIdFromResult(event, rawEvents);
395→      if (toolUseId && toolUseIdToEventId.has(toolUseId)) {
396→        event.respondingTo = toolUseIdToEventId.get(toolUseId);
397→      }
398→    } else if (isAiTurn) {
399→      // AI event → responds to first event of most recent user turn
400→      if (lastUserTurnId) {
401→        const firstUserEvent = firstEventByTurn.get(lastUserTurnId);
402→        if (firstUserEvent) {
403→          event.respondingTo = firstUserEvent.id;
404→        }
405→      }
406→    } else if (isUserTurn && !event.rawEventId.includes("-result-")) {
407→      // User conversation_turn → responds to last event of most recent AI turn
408→      if (lastAiTurnId) {
409→        const lastAiEvent = lastEventByTurn.get(lastAiTurnId);
410→        if (lastAiEvent) {
411→          event.respondingTo = lastAiEvent.id;
412→        }
413→      }
414→    }
415→
416→    // Update last completed turn tracking
417→    // A turn is "completed" when we see the first event of a different turn
418→    if (isUserTurn && lastUserTurnId !== turnId) {
419→      lastUserTurnId = turnId;
420→    }
421→    if (isAiTurn && lastAiTurnId !== turnId) {
422→      lastAiTurnId = turnId;
423→    }
424→  }
425→}
426→
427→/**
428→ * Extract text from a tool_result event.
429→ */
430→function getToolResultText(raw: Record<string, unknown>): string | null {
431→  const msg = raw.message as { content?: unknown } | undefined;
432→  if (!msg?.content) return null;
433→
434→  if (typeof msg.content === "string") return msg.content;
435→
436→  if (Array.isArray(msg.content)) {
437→    for (const block of msg.content) {
438→      const b = block as { type?: string; content?: unknown };
439→      if (b.type === "tool_result") {
440→        // content can be a string or array of text blocks
441→        if (typeof b.content === "string") return b.content;
442→        if (Array.isArray(b.content)) {
443→          const texts: string[] = [];
444→          for (const inner of b.content) {
445→            const t = inner as { type?: string; text?: string };
446→            if (t.type === "text" && t.text) texts.push(t.text);
447→          }
448→          if (texts.length > 0) return texts.join("\n");
449→        }
450→      }
451→    }
452→  }
453→  return null;
454→}
