  1→import type { SessionChunk } from "../adapters/types.js";
  2→import type { SessionShape, SessionMoment } from "../adapters/types.js";
  3→import { callSonnet } from "../llm/client.js";
  4→import {
  5→  buildPass1Prompt,
  6→  buildPass2Prompt,
  7→  Pass1OutputSchema,
  8→  Pass2OutputSchema,
  9→  type Pass1Moment,
 10→  type Pass2Moment,
 11→} from "../llm/prompts/moments.js";
 12→import type { SessionShape as PromptSessionShape } from "../llm/prompts/classify.js";
 13→
 14→/**
 15→ * Two-pass moment detection across session chunks.
 16→ *
 17→ * Pass 1: Extract candidate moments from each chunk in parallel (Sonnet).
 18→ * Pass 2: Merge, deduplicate, and assign arcs across all candidates (Sonnet).
 19→ */
 20→export async function detectMoments(
 21→  chunks: SessionChunk[],
 22→  sessionShape: SessionShape,
 23→): Promise<SessionMoment[]> {
 24→  const shapeObj: PromptSessionShape = { shape: sessionShape };
 25→
 26→  // ── Pass 1: per-chunk extraction in parallel ───────────────────────
 27→  const pass1Results = await Promise.all(
 28→    chunks.map(async (chunk) => {
 29→      const { system, user } = buildPass1Prompt({
 30→        chunk,
 31→        sessionShape: shapeObj,
 32→      });
 33→      const result = await callSonnet(system, user, Pass1OutputSchema);
 34→      return { chunkIndex: chunk.chunkIndex, moments: result.moments };
 35→    }),
 36→  );
 37→
 38→  // ── Pass 2: cross-chunk merge & arc assignment ─────────────────────
 39→  const { system, user } = buildPass2Prompt({
 40→    pass1Moments: pass1Results,
 41→    sessionShape: shapeObj,
 42→    totalChunks: chunks.length,
 43→  });
 44→  const pass2Result = await callSonnet(system, user, Pass2OutputSchema);
 45→
 46→  // Convert Pass2Moment[] → SessionMoment[]
 47→  return pass2Result.moments.map((m, i) => toSessionMoment(m, i, chunks));
 48→}
 49→
 50→// ── Internal ──────────────────────────────────────────────────────────
 51→
 52→function toSessionMoment(
 53→  m: Pass2Moment,
 54→  index: number,
 55→  chunks: SessionChunk[],
 56→): SessionMoment {
 57→  // Use first chunk's id as a fallback chunkId
 58→  const chunkId = chunks[0]?.id ?? "unknown";
 59→
 60→  return {
 61→    id: `moment-${index}`,
 62→    chunkId,
 63→    type: m.type,
 64→    statement: m.statement,
 65→    significance: m.significance,
 66→    agency: m.agency === "collaborative" ? "collaborative" : m.agency,
 67→    confidence: m.confidence,
 68→    topicFingerprint: m.topicFingerprint,
 69→    relatedMomentIds: m.relatedMomentIds.map((id) => `moment-${id}`),
 70→    arcId: m.arcId,
 71→    arcRole: mapArcRole(m.arcRole),
 72→    evidence: m.evidence.map((e) => ({
 73→      quote: e.quote,
 74→      sourceEventId: e.sourceEventId ?? "",
 75→      sourceType: mapSourceType(e.sourceType),
 76→      quoteType: e.quoteType === "verbatim" ? "verbatim" : "summarized",
 77→    })),
 78→  };
 79→}
 80→
 81→function mapArcRole(
 82→  role: string,
 83→): "origin" | "escalation" | "turning_point" | "resolution" {
 84→  switch (role) {
 85→    case "origin":
 86→      return "origin";
 87→    case "turning_point":
 88→      return "turning_point";
 89→    case "resolution":
 90→      return "resolution";
 91→    default:
 92→      return "escalation";
 93→  }
 94→}
 95→
 96→function mapSourceType(
 97→  st: string,
 98→): "human_message" | "ai_message" | "tool_output" | "tool_input" {
 99→  switch (st) {
100→    case "user":
101→      return "human_message";
102→    case "ai":
103→      return "ai_message";
104→    case "tool_output":
105→      return "tool_output";
106→    default:
107→      return "tool_input";
108→  }
109→}
