 14→export function registerDigestCommand(program: Command): void {
 15→  program
 16→    .command("digest [path]")
 17→    .description("Ingest conversation logs and produce session digests")
 18→    .option("--last <n>", "Process N most recent sessions", parseInt)
 19→    .option("--dry-run", "Run deterministic pipeline only (no LLM calls), print stats")
 20→    .action(async (path: string | undefined, opts: { last?: number; dryRun?: boolean }) => {
 21→      try {
 22→        if (opts.dryRun) {
 23→          await runDryRun(path, opts.last);
 24→          return;
 25→        }
 26→
 27→        const paths = await resolvePaths(path, opts.last);
 28→
 29→        for (const logPath of paths) {
 30→          const result = await runPipeline(logPath);
 31→          printDigest(result);
 32→          if (paths.length > 1) {
 33→            console.log("\n" + "─".repeat(60) + "\n");
 34→          }
 35→        }
