    21→  sourceEventId: z.string().optional(),
    22→  sourceType: z.enum(["user", "ai", "tool_output"]).optional().default("ai"),
    23→  quoteType: z.enum(["verbatim", "paraphrase"]).optional().default("verbatim"),
    24→});
    25→
    26→// Accept evidence as either structured objects or plain strings
    27→const FlexibleEvidenceSchema = z.union([
    28→  EvidenceSchema,
    29→  z.string().transform((s) => ({ quote: s, sourceType: "ai" as const, quoteType: "verbatim" as const })),
    30→]);
    31→
    32→const Pass1MomentSchema = z.object({
    33→  type: MomentTypeSchema,
    34→  statement: z.string(),
    35→  significance: z.string(), // why this moment matters — free text
    36→  agency: z.enum(["developer", "ai", "collaborative"]),
    37→  confidence: z.enum(["high", "medium", "low"]),
    38→  topicFingerprint: z.string().optional().default("general"),
    39→  evidence: z.union([
    40→    z.array(FlexibleEvidenceSchema).min(1),
    41→    z.string().transform((s) => [{ quote: s, sourceType: "ai" as const, quoteType: "verbatim" as const }]),
    42→  ]),
    43→});
    44→
    45→export const Pass1OutputSchema = z.object({
    46→  moments: z.array(Pass1MomentSchema),
    47→});
    48→
    49→const Pass2MomentSchema = Pass1MomentSchema.passthrough().extend({
    50→  arcId: z.string(),
    51→  arcRole: z.enum(["origin", "development", "turning_point", "resolution"]),
    52→  relatedMomentIds: z.array(z.number()),
    53→});
