    59→export type Pass1Moment = z.infer<typeof Pass1MomentSchema>;
    60→export type Pass1Output = z.infer<typeof Pass1OutputSchema>;
    61→export type Pass2Moment = z.infer<typeof Pass2MomentSchema>;
    62→export type Pass2Output = z.infer<typeof Pass2OutputSchema>;
    63→
    64→// ── Pass 1: Per-Chunk Moment Detection ───────────────────────────────
    65→
    66→export interface Pass1Input {
    67→  chunk: SessionChunk;
    68→  sessionShape: SessionShape;
    69→  directives?: PipelineDirectives;
    70→}
    71→
    72→export function buildPass1Prompt(input: Pass1Input): {
    73→  system: string;
    74→  user: string;
    75→} {
    76→  const { chunk, sessionShape, directives } = input;
    77→
    78→  let directiveGuidance = "";
    79→  if (directives?.promptSections) {
    80→    const sections = directives.promptSections;
    81→    const notes: string[] = [];
    82→
    83→    if (sections.detectPassiveAcceptance) {
    84→      notes.push(
    85→        "Note: This session contains many short developer responses. When you see 'yes', 'ok', 'sure' — distinguish active agreement from passive acceptance. This matters for agency classification.",
    86→      );
    87→    }
    88→    if (sections.trackDelegation) {
    89→      notes.push(
    90→        "Note: The developer frequently defers decisions. Look for moments where the AI made choices the developer didn't engage with.",
    91→      );
    92→    }
    93→    if (sections.detectIgnoredProposals) {
    94→      notes.push(
    95→        "Note: The AI made proposals that the developer didn't fully address. Flag proposals that received no direct response as potential ignored proposals.",
    96→      );
    97→    }
    98→    if (sections.isLearningExchange) {
    99→      notes.push(
   100→        "Note: The developer is asking questions to understand. Focus on what insights or understanding emerged, not just what actions were taken.",
   101→      );
   102→    }
   103→
   104→    if (notes.length > 0) {
   105→      directiveGuidance = "\n\n## Interaction Signals\n\n" + notes.join("\n\n");
   106→    }
   107→  }
   108→
   109→  const system = `You are an expert at identifying meaningful moments in developer coding sessions. You read a sequence of events from one chunk of a session and extract the moments that matter.
   110→
   111→A "moment" is a point where something meaningful happened — a decision was made, an insight occurred, direction changed, or a commitment was established. NOT every event is a moment. You are looking for the inflection points.
   112→
   113→## Moment Types
   114→
   115→- **proposal** — Someone (developer or AI) suggests an approach, architecture, or solution. Use the proposer's actual words.
   116→- **discovery** — New information surfaces that changes understanding. "Oh, this API doesn't support streaming" or "The tests are actually passing, it was a caching issue."
   117→- **pivot** — Direction changes. The developer was doing X, now they're doing Y. Must cite what triggered the pivot.
   118→- **confirmation** — A tentative approach becomes accepted. "Yeah, that looks right" or running tests that pass.
   119→- **rejection** — An approach is explicitly rejected. "Actually let's not mock the database" or reverting a change.
   120→- **commitment** — A firm decision that shapes subsequent work. Different from confirmation — this is choosing a path, not validating one.
   121→- **struggle** — Repeated failed attempts, confusion, or difficulty. Cycles of edit-fail-edit on the same problem.
   122→- **breakthrough** — A struggle resolves. The thing that wasn't working now works, or the confusion clears.
   123→- **execution** — Sustained implementation of an already-decided approach. Only flag this for significant scope, not every edit.
   124→
   125→## Rules
   126→
   127→1. **Be specific, not generic.** "Developer rejected AI's suggestion to use a mock database, saying 'actually let's not mock the database, let's use testcontainers'" — not "a decision was made about testing."
   128→2. **Use the developer's own language.** Quote them. If the AI proposed something and the developer accepted, say what the AI proposed AND how the developer responded.
   129→3. **Every moment MUST have evidence.** At least one direct quote from the events.
   130→4. **Distinguish agency clearly.** Who drove this moment? "developer" if they initiated it. "ai" if the AI proposed it and the developer just went along. "collaborative" if there was back-and-forth.
   131→5. **topicFingerprint** should be a short, stable identifier for the topic area (e.g., "auth-middleware", "test-setup", "api-schema"). Use kebab-case. Two moments about the same topic should share a fingerprint.
   132→6. **Fewer is better.** A chunk of 20 events might have 2-5 moments. Don't pad. If nothing meaningful happened, return an empty array.
   133→
   134→${getShapeGuidance(sessionShape.shape)}${directiveGuidance}
   135→
   136→## Output Format
   137→
   138→Return ONLY a JSON object:
   139→{
   140→  "moments": [
   141→    {
   142→      "type": "proposal|discovery|pivot|confirmation|rejection|commitment|struggle|breakthrough|execution",
   143→      "statement": "What happened, in the developer's own language",
   144→      "significance": "Why this moment matters in the context of the session",
   145→      "agency": "developer|ai|collaborative",
   146→      "confidence": "high|medium|low",
   147→      "topicFingerprint": "kebab-case-topic-id",
   148→      "evidence": [
   149→        {
   150→          "quote": "Exact or near-exact quote from the events",
   151→          "sourceEventId": "the [N] event index as a string",
   152→          "sourceType": "user|ai|tool_output",
   153→          "quoteType": "verbatim|paraphrase"
   154→        }
   155→      ]
   156→    }
   157→  ]
   158→}`;
   159→
   160→  const user = `## Session Shape: ${sessionShape.shape}
   161→## Chunk ${chunk.chunkIndex} — Topic: ${chunk.topicHint}
   162→## Files in scope: ${chunk.filesInScope.slice(0, 15).join(", ")}
   163→
   164→## Events (${chunk.events.length} total):
   165→
   166→${formatThreadedEvents(chunk.events)}
   167→
   168→Extract the meaningful moments from this chunk. Return JSON only.`;
   169→
   170→  return { system, user };
   171→}
   172→
   173→// ── Pass 2: Cross-Chunk Merge & Arc Assignment ───────────────────────
   174→
   175→export interface Pass2Input {
   176→  pass1Moments: { chunkIndex: number; moments: Pass1Moment[] }[];
   177→  sessionShape: SessionShape;
   178→  totalChunks: number;
   179→}
   180→
   181→export function buildPass2Prompt(input: Pass2Input): {
   182→  system: string;
   183→  user: string;
   184→} {
   185→  const { pass1Moments, sessionShape, totalChunks } = input;
   186→
   187→  const system = `You are an expert at synthesizing developer session moments into coherent arcs. You receive moments detected across multiple chunks of a single session and must:
   188→
   189→1. **Deduplicate** — If the same moment was detected in overlapping chunks, keep the best version (more specific statement, stronger evidence).
   190→2. **Merge** — If two moments describe the same underlying event from different perspectives, merge them into one.
   191→3. **Assign arcs** — Group related moments into narrative arcs. An arc is a thread of related activity (e.g., "setting up auth middleware" or "debugging the flaky test"). Give each arc a short kebab-case ID.
   192→4. **Assign arc roles** — Within each arc, mark each moment's role:
   193→   - **origin** — The moment that started this arc (first proposal, initial discovery)
   194→   - **development** — Moments that advance the arc (execution, further proposals)
   195→   - **turning_point** — Pivots, rejections, breakthroughs that change the arc's direction
   196→   - **resolution** — The arc reaches a conclusion (commitment, final confirmation)
   197→5. **Link related moments** — If moment N was caused by or responds to moment M, include M's index in relatedMomentIds. Use 0-based indices into YOUR output array.
   198→
   199→## Rules
   200→
   201→- Preserve the developer's own language in statements. Don't rewrite to be more "professional."
   202→- If a moment from Pass 1 is low quality (vague statement, no real evidence), drop it.
   203→- Don't invent moments that weren't in Pass 1. You can only merge, dedupe, enrich, or drop.
   204→- An arc can have 1 moment (a standalone insight) or many (a full narrative thread).
   205→- Total output moments should be <= total input moments.
   206→
   207→Respond with ONLY a JSON object: { "moments": [...] }`;
   208→
   209→  const user = `## Session Shape: ${sessionShape.shape}
   210→## Total chunks: ${totalChunks}
   211→
   212→## Pass 1 Moments by Chunk:
   213→
   214→${pass1Moments
   215→  .map(
   216→    ({ chunkIndex, moments }) => `### Chunk ${chunkIndex} (${moments.length} moments):
   217→${moments
   218→  .map(
   219→    (m, i) => `  ${i}. [${m.type}] ${m.statement}
   220→     significance=${m.significance} agency=${m.agency} confidence=${m.confidence}
   221→     topic=${m.topicFingerprint}
   222→     evidence: ${m.evidence.map((e) => `"${e.quote.slice(0, 120)}"`).join("; ")}`,
   223→  )
   224→  .join("\n")}`,
   225→  )
   226→  .join("\n\n")}
   227→
   228→Synthesize these into final moments with arc assignments. Return JSON only.`;
   229→
   230→  return { system, user };
   231→}
