  1→import crypto from "node:crypto";
  2→import { parseClaudeCodeLog } from "../adapters/claude-code.js";
  3→import { normalize } from "./normalize.js";
  4→import { analyzeInteractions } from "./analyze.js";
  5→import { classifySession } from "./classify.js";
  6→import { chunkSession } from "./chunk.js";
  7→import { detectMoments } from "./moments.js";
