 81→// ── Helpers ──────────────────────────────────────────────────────────
 82→
 83→function collectFiles(moments: SessionMoment[]): string[] {
 84→  const files = new Set<string>();
 85→  for (const m of moments) {
 86→    // topicFingerprint might hint at files, but we'll use evidence sourceEventIds
 87→    // In practice, files come from the chunks — for now return empty
 88→  }
 89→  return Array.from(files);
 90→}
