 92→function mapAgency(
 93→  agency: string,
 94→): "developer" | "ai" | "collaborative" {
 95→  if (agency === "developer" || agency === "ai" || agency === "collaborative") {
 96→    return agency;
 97→  }
 98→  return "collaborative";
 99→}
100→
101→function mapSourceTypeBack(
102→  st: string,
103→): "user" | "ai" | "tool_output" {
104→  switch (st) {
105→    case "human_message":
106→      return "user";
107→    case "ai_message":
108→      return "ai";
109→    case "tool_output":
110→      return "tool_output";
111→    default:
112→      return "user";
113→  }
114→}
115→
116→function mapArcRoleBack(
117→  role?: string,
118→): "origin" | "development" | "turning_point" | "resolution" {
119→  switch (role) {
120→    case "origin":
121→      return "origin";
122→    case "turning_point":
123→      return "turning_point";
124→    case "resolution":
125→      return "resolution";
126→    default:
127→      return "development";
128→  }
129→}
