 38→    confidence: m.confidence,
 39→    topicFingerprint: m.topicFingerprint,
 40→    evidence: m.evidence.map((e) => ({
 41→      quote: e.quote,
 42→      sourceEventId: e.sourceEventId || undefined,
 43→      sourceType: mapSourceTypeBack(e.sourceType),
