  1→import type { SessionChunk, PipelineDirectives } from "../adapters/types.js";
  2→import type { SessionShape, SessionMoment } from "../adapters/types.js";
  3→import { callSonnet } from "../llm/client.js";
  4→import {
  5→  buildPass1Prompt,
  6→  buildPass2Prompt,
  7→  Pass1OutputSchema,
  8→  Pass2OutputSchema,
  9→  type Pass1Moment,
 10→  type Pass2Moment,
 11→} from "../llm/prompts/moments.js";
 12→import type { SessionShape as PromptSessionShape } from "../llm/prompts/classify.js";
 13→
 14→/**
 15→ * Two-pass moment detection across session chunks.
 16→ *
 17→ * Pass 1: Extract candidate moments from each chunk in parallel (Sonnet).
 18→ * Pass 2: Merge, deduplicate, and assign arcs across all candidates (Sonnet).
 19→ */
 20→export async function detectMoments(
 21→  chunks: SessionChunk[],
 22→  sessionShape: SessionShape,
 23→  directives?: PipelineDirectives,
 24→): Promise<SessionMoment[]> {
 25→  const shapeObj: PromptSessionShape = { shape: sessionShape };
 26→
 27→  // ── Pass 1: per-chunk extraction in parallel ───────────────────────
 28→  const pass1Results = await Promise.all(
 29→    chunks.map(async (chunk) => {
 30→      const { system, user } = buildPass1Prompt({
 31→        chunk,
 32→        sessionShape: shapeObj,
 33→        directives,
 34→      });
 35→      const result = await callSonnet(system, user, Pass1OutputSchema);
 36→      return { chunkIndex: chunk.chunkIndex, moments: result.moments };
 37→    }),
 38→  );
 39→
 40→  // ── Pass 2: cross-chunk merge & arc assignment ─────────────────────
 41→  const { system, user } = buildPass2Prompt({
 42→    pass1Moments: pass1Results,
 43→    sessionShape: shapeObj,
 44→    totalChunks: chunks.length,
 45→  });
 46→  const pass2Result = await callSonnet(system, user, Pass2OutputSchema);
 47→
 48→  // Convert Pass2Moment[] → SessionMoment[]
 49→  return pass2Result.moments.map((m, i) => toSessionMoment(m, i, chunks));
 50→}
 51→
 52→// ── Internal ──────────────────────────────────────────────────────────
 53→
 54→function toSessionMoment(
 55→  m: Pass2Moment,
 56→  index: number,
 57→  chunks: SessionChunk[],
 58→): SessionMoment {
 59→  // Use first chunk's id as a fallback chunkId
 60→  const chunkId = chunks[0]?.id ?? "unknown";
 61→
 62→  return {
 63→    id: `moment-${index}`,
 64→    chunkId,
 65→    type: m.type,
 66→    statement: m.statement,
 67→    significance: m.significance,
 68→    agency: m.agency === "collaborative" ? "collaborative" : m.agency,
 69→    confidence: m.confidence,
 70→    topicFingerprint: m.topicFingerprint,
 71→    relatedMomentIds: m.relatedMomentIds.map((id) => `moment-${id}`),
 72→    arcId: m.arcId,
 73→    arcRole: mapArcRole(m.arcRole),
 74→    evidence: m.evidence.map((e) => ({
 75→      quote: e.quote,
 76→      sourceEventId: e.sourceEventId ?? "",
 77→      sourceType: mapSourceType(e.sourceType),
 78→      quoteType: e.quoteType === "verbatim" ? "verbatim" : "summarized",
 79→    })),
 80→  };
 81→}
 82→
 83→function mapArcRole(
 84→  role: string,
 85→): "origin" | "escalation" | "turning_point" | "resolution" {
 86→  switch (role) {
 87→    case "origin":
 88→      return "origin";
 89→    case "turning_point":
 90→      return "turning_point";
 91→    case "resolution":
 92→      return "resolution";
 93→    default:
 94→      return "escalation";
 95→  }
 96→}
 97→
 98→function mapSourceType(
 99→  st: string,
100→): "human_message" | "ai_message" | "tool_output" | "tool_input" {
101→  switch (st) {
102→    case "user":
103→      return "human_message";
104→    case "ai":
105→      return "ai_message";
106→    case "tool_output":
107→      return "tool_output";
108→    default:
109→      return "tool_input";
110→  }
111→}
