    await writeFile(join(FIXTURES_DIR, 'scope-pivot.jsonl'), pivotLines.join('\n') + '\n');
    console.log(`Scope: pivot — ${pivotLines.length} lines`);
  }

  // Scope 4: Full session
  await writeFile(join(FIXTURES_DIR, 'scope-full.jsonl'), content);
  console.log(`Scope: full — ${lines.length} lines`);

  console.log(`\nFixtures saved to ${FIXTURES_DIR}`);
}

main().catch(console.error);
